async function loadSummary(){const e=$('#summaryBox');if(!e)return;try{const d=await api('/api/admin/summary');const map=[['users','المستخدمون','👥'],['advertisers','المعلنون','📣'],['pendingTasks','مهام قيد المراجعة','⏳'],['pendingWithdrawals','سحوبات قيد المراجعة','💳'],['tickets','تذاكر مفتوحة','💬'],['campaigns','الحملات','📊'],['revenue','إيرادات المنصة','💰']];e.innerHTML=map.map(x=>`<div class=card metric><span class=icon>${x[2]}</span><span class=kpi>${x[1]}</span><strong>${fmt(d[x[0]])}</strong></div>`).join('')}catch(err){console.error(err);e.innerHTML='<div class=card empty>تعذر تحميل بيانات لوحة التحكم. جرّب تحديث الصفحة.</div>'}}

