async function createAdv(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/advertisers',{method:'POST',body:JSON.stringify({company:$('#ac').value,contact:$('#acn').value,email:$('#ace').value,password:$('#acp').value,vip:$('#vip').checked,confirm})});toast('تم إنشاء المعلن');render()}catch(e){toast(e.message)}}






async function loadAdvSelect(){const d=await api('/api/admin/advertisers');$('#ca').innerHTML='<option value="">بدون معلن</option>'+d.advertisers.map(a=>`<option value="${a.id}">${esc(a.company)}</option>`).join('')}

async function createTask(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks',{method:'POST',body:JSON.stringify({title:$('#tn').value,type:$('#tt').value,goalType:$('#tt').value,goalTarget:Number($('#ngt').value)||1,period:$('#nper').value,startsAt:$('#nst').value||null,endsAt:$('#nen').value||null,points:$('#tp').value,xp:$('#tx').value,duration:$('#td').value,levelMinId:$('#tl').value,package:$('#ntp').value,verification:$('#tv').value,category:$('#nc').value||'عام',isAdditional:$('#nadd').checked,dailyLimit:$('#ndl').value,description:$('#ndesc').value,conditions:$('#ncond').value,confirm})});toast('تمت إضافة المهمة');render()}catch(e){toast(e.message)}}
async function loadAdminTasks(){const e=$('#taskAdminBox');if(!e)return;try{const d=await api('/api/admin/tasks');e.innerHTML=d.tasks.map(t=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(t.title)}</h3><small class=muted>${esc(t.category||'عام')} · ${esc(t.period||'once')} · ${t.startsAt?date(t.startsAt):'بدون بداية'} → ${t.endsAt?date(t.endsAt):'بدون نهاية'}</small></div><span class="pill ${t.active?'green':'red'}">${t.active?'Active':'Inactive'}</span></div><div class=taskMeta><span class=reward>${fmt(t.points)} Points</span><span class=pill>+${fmt(t.xp)} XP</span><span class=pill>${esc(t.goalType||t.type||'custom')} · ${fmt(t.goalTarget||1)}</span><span class=pill>${esc(t.package||'Free')}</span></div><div class=row style="margin-top:10px"><button class="btn ghost" onclick='editTask(${JSON.stringify(t).replace(/'/g,"&#39;")})'>تعديل</button><button class="btn secondary" onclick="toggleTask('${esc(t.id)}')">${t.active?'إيقاف':'تفعيل'}</button></div></div>`).join('')||'<div class=card empty>لا توجد مهام.</div>'}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المهام. حاول إعادة المحاولة.</div>'}}
function editTask(t){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>تعديل المهمة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>الاسم</label><input id=etn class=input value="${esc(t.title)}"></div><div class=field><label>النوع</label><select id=ett class=input><option value="custom">مخصصة</option><option value="complete_tasks">إكمال عدد من المهام</option><option value="login_count">تسجيل الدخول عدد مرات</option><option value="daily_login">تسجيل الدخول يومياً</option><option value="collect_points">جمع Points</option><option value="collect_xp">جمع XP</option><option value="referrals">دعوة أصدقاء مؤهلين</option><option value="streak">Streak متواصل</option><option value="category_tasks">إكمال مهام من فئة</option></select></div><div class=field><label>الهدف</label><input id=egt class=input type=number min=1 value="${fmt(t.goalTarget||1)}"></div><div class=field><label>الدورة</label><select id=eper class=input><option>once</option><option>daily</option><option>weekly</option><option>monthly</option><option>custom</option></select></div><div class=field><label>تبدأ</label><input id=est class=input type=datetime-local value="${t.startsAt?String(t.startsAt).slice(0,16):''}"></div><div class=field><label>تنتهي</label><input id=een class=input type=datetime-local value="${t.endsAt?String(t.endsAt).slice(0,16):''}"></div><div class=field><label>Points</label><input id=etp class=input type=number min=0 value="${fmt(t.points)}"></div><div class=field><label>XP</label><input id=etx class=input type=number min=0 value="${fmt(t.xp)}"></div></div><div class=field><label>الوصف</label><textarea id=edesc class=input rows=3>${esc(t.description||'')}</textarea></div><button class=btn onclick="saveTaskEdit('${esc(t.id)}')">حفظ التعديلات</button></div>`;document.body.appendChild(m);$('#ett').value=t.goalType||t.type||'custom';$('#eper').value=t.period||'once'}
async function saveTaskEdit(id){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks/update',{method:'POST',body:JSON.stringify({id,title:$('#etn').value,goalType:$('#ett').value,type:$('#ett').value,goalTarget:Number($('#egt').value)||1,period:$('#eper').value,startsAt:$('#est').value||null,endsAt:$('#een').value||null,points:Number($('#etp').value)||0,xp:Number($('#etx').value)||0,description:$('#edesc').value,confirm})});document.querySelector('.modalBack')?.remove();toast('تم تعديل المهمة');render()}catch(e){toast(e.message)}}
async function toggleTask(id){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks/toggle',{method:'POST',body:JSON.stringify({id,confirm})});toast('تم تحديث حالة المهمة');render()}catch(e){toast(e.message)}}
function withdrawalsPage(){return `<h1>السحوبات</h1><p class=subtitle>كل قرار اعتماد/رفض يحتاج تأكيداً ثانوياً، وبعد المعالجة تختفي أزرار القرار.</p><div class=card><div class=searchRow><input id=wq class=input placeholder="بحث بالمرجع أو المستخدم" oninput="loadW()"><select id=ws class=input onchange="loadW()"><option value="">كل الحالات</option><option>pending</option><option>approved</option><option>rejected</option></select><div></div><button class="btn secondary" onclick="loadW()">تحديث</button></div></div><div id=wBox class=section>جارٍ التحميل...</div>`}
async function replyTicket(id){const m=prompt('اكتب الرد');if(!m)return;try{await api('/api/admin/ticket',{method:'POST',body:JSON.stringify({id,message:m,status:'open'})});toast('تم إرسال الرد');render()}catch(e){toast(e.message)}}
function reportsPage(){return `<h1>التقارير والتحليلات</h1><p class=subtitle>هنا التفاصيل التشغيلية الكاملة. الصفحة الرئيسية تبقى مختصرة فقط.</p><div class=card><div class=searchRow><select id=rd class=input><option value=7>آخر 7 أيام</option><option value=30 selected>آخر 30 يوم</option><option value=90>آخر 90 يوم</option><option value=365>آخر سنة</option></select><button class="btn secondary" onclick="loadReports()">تحديث التقرير</button></div></div><div id=rBox class=section>جارٍ التحميل...</div>`}async function loadReports(){const days=$('#rd')?.value||30;const d=await api('/api/admin/reports?days='+days);const o=d.overview;$('#rBox').innerHTML=`<div class=grid4></div><div class=grid section><div class=card metric><span class=kpi>المستخدمون</span><strong>${fmt(o.users)}</strong><small class=muted>جدد 7 أيام: ${fmt(o.newUsers7)} · 30 يوم: ${fmt(o.newUsers30)}</small></div><div class=card metric><span class=kpi>المعلنون</span><strong>${fmt(o.advertisers)}</strong><small class=muted>نشط: ${fmt(o.activeAdvertisers)}</small></div><div class=card metric><span class=kpi>الحملات</span><strong>${fmt(o.campaigns)}</strong><small class=muted>نشطة ${fmt(o.activeCampaigns)} · Pending ${fmt(o.pendingCampaigns)} · مكتملة ${fmt(o.completedCampaigns)}</small></div><div class=card metric><span class=kpi>العمليات</span><strong>${fmt(o.taskAttempts+o.withdrawals+o.redemptions+o.transactions)}</strong><small class=muted>Transactions ${fmt(o.transactions)}</small></div></div><div class="grid2 section"><div class=card><h2>دورة المهام</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>بدأت</small><strong>${fmt(o.startedTasks)}</strong></div><div class=reportStat><small>قيد المراجعة</small><strong>${fmt(o.pendingTasks)}</strong></div><div class=reportStat><small>مقبولة</small><strong>${fmt(o.approvedTasks)}</strong></div><div class=reportStat><small>مرفوضة</small><strong>${fmt(o.rejectedTasks)}</strong></div></div><p class=muted>Points موزعة: ${fmt(d.tasks.pointsAwarded)} · XP موزعة: ${fmt(d.tasks.xpAwarded)}</p></div><div class=card><h2>السحوبات</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>كل الطلبات</small><strong>${fmt(o.withdrawals)}</strong></div><div class=reportStat><small>Pending</small><strong>${fmt(o.pendingWithdrawals)}</strong></div><div class=reportStat><small>مقبولة</small><strong>${fmt(o.approvedWithdrawals)}</strong></div><div class=reportStat><small>مرفوضة</small><strong>${fmt(o.rejectedWithdrawals)}</strong></div></div><p class=muted>المطلوب: ${fmt(d.withdrawals.requested)} · المعتمد: ${fmt(d.withdrawals.approved)}</p></div></div><div class="grid2 section"><div class=card><h2>الحملات والأداء</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>Budget</small><strong>${fmt(d.campaigns.budget)}</strong></div><div class=reportStat><small>Spent</small><strong>${fmt(d.campaigns.spent)}</strong></div><div class=reportStat><small>Clicks</small><strong>${fmt(o.clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(o.conversions)}</strong></div></div><div class=notice style="margin-top:13px">Conversion Rate: <b>${o.conversionRate}%</b></div></div><div class=card><h2>متجر المكافآت</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>الاستردادات</small><strong>${fmt(o.redemptions)}</strong></div><div class=reportStat><small>Points مصروفة</small><strong>${fmt(d.redemptions.pointsSpent)}</strong></div></div><p class=muted>المخالفات المسجلة: ${fmt(o.violations)} · التذاكر المفتوحة: ${fmt(o.ticketsOpen)}</p></div></div><div class="grid2 section"><div class=card><h2>توزيع المستخدمين</h2><div class=taskMeta>${Object.entries(d.users.byPackage||{}).map(([k,v])=>`<span class=pill>${esc(k)}: ${fmt(v)}</span>`).join('')||'لا بيانات'}</div><div class=taskMeta>${Object.entries(d.users.byState||{}).map(([k,v])=>`<span class=pill>${esc(k)}: ${fmt(v)}</span>`).join('')}</div></div><div class=card><h2>المالية</h2><div class=grid2><div class=reportStat><small>Points داخلة</small><strong>${fmt(d.financial.pointsIn)}</strong></div><div class=reportStat><small>Points خارجة</small><strong>${fmt(d.financial.pointsOut)}</strong></div><div class=reportStat><small>Cash Flow</small><strong>${fmt(d.financial.cashFlow)}</strong></div><div class=reportStat><small>Revenue</small><strong>${fmt(o.revenue)}</strong></div></div></div></div><div class="card section"><h2>ملخص الحالات</h2><div class=tableWrap style="margin-top:12px"><table class=table><tr><th>المؤشر</th><th>القيمة</th><th>ماذا يعني</th></tr><tr><td>المستخدمون الجدد</td><td>${fmt(o.newUsers30)}</td><td>حسابات أنشئت خلال الفترة</td></tr><tr><td>العمليات قيد التنفيذ</td><td>${fmt(o.startedTasks)}</td><td>محاولات مهام بدأت ولم تُرسل بعد</td></tr><tr><td>Pending</td><td>${fmt(o.pendingTasks+o.pendingWithdrawals)}</td><td>تحتاج قرار مراجعة</td></tr><tr><td>الحملات المكتملة</td><td>${fmt(o.completedCampaigns)}</td><td>حملات وصلت إلى حالة مكتملة</td></tr><tr><td>إجمالي العمليات المالية</td><td>${fmt(d.financial.transactionCount)}</td><td>سجل المعاملات الداخلي</td></tr></table></div></div>`}





function emergencyConfirm(action,cb){root.insertAdjacentHTML('beforeend',`<div class=modalBack id=emModal><div class=modal><h2>⚠️ تأكيد إجراء حساس</h2><p class=muted>${esc(action)}</p><div class=field><label>رمز الطوارئ</label><input id=emCode class=input type=password></div><div class=row><button class="btn danger" onclick="${cb}">تأكيد وتنفيذ</button><button class="btn ghost" onclick="$('#emModal').remove()">إلغاء</button></div></div></div>`)}
function saveEmergency(){const p={registrationsOpen:$('#ereg').checked,tasksOpen:$('#etasks').checked,withdrawalsOpen:$('#ewd').checked,maintenance:$('#emaint').checked,emergencyMode:!$('#ereg').checked||!$('#etasks').checked||!$('#ewd').checked||$('#emaint').checked,reason:$('#ereason').value};emergencyConfirm('سيتم تغيير حالة خدمات المنصة. تأكد قبل التنفيذ.',`doEmergency(${JSON.stringify(p)})`)}
async function doEmergency(p){try{const d=await api('/api/admin/emergency',{method:'POST',body:JSON.stringify({...p,confirm:$('#emCode').value})});$('#emModal').remove();toast('تم تحديث حالة المنصة');renderEmergency(d.settings)}catch(e){toast(e.message)}}


function packagePayload(k){return {name:$('#p_'+k+'_name').value,price:Number($('#p_'+k+'_price').value),durationDays:Number($('#p_'+k+'_duration').value),dailyTasks:Number($('#p_'+k+'_daily').value),minLevel:Number($('#p_'+k+'_level').value),withdrawalMin:Number($('#p_'+k+'_wmin').value),withdrawalDailyLimit:Number($('#p_'+k+'_wdaily').value),priority:$('#p_'+k+'_priority').value,currency:$('#p_'+k+'_currency').value,active:$('#p_'+k+'_active').checked,visible:$('#p_'+k+'_visible').checked,features:$('#p_'+k+'_features').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function savePackage(k){emergencyConfirm('حفظ تغييرات باقة '+k+' قد يغير وصول المستخدمين وحدودهم.',`doSavePackage('${k}')`)}async function doSavePackage(k){try{await api('/api/admin/packages',{method:'POST',body:JSON.stringify({key:k,package:packagePayload(k),confirm:$('#emCode').value})});$('#emModal').remove();toast('تم حفظ الباقة');loadPackagesAdmin()}catch(e){toast(e.message)}}
function sandboxPage(){return `<h1>Test Center</h1><p class=subtitle>بيئة اختبار معزولة. اختر أي حساب تجريبي وعدّل Cash / Points / XP / Level مباشرة.</p><div class=card><div class=grid2><div class=field><label>الحساب التجريبي</label><select id=sbUser class=input onchange="loadSandboxUserValues()"><option>جارٍ التحميل...</option></select></div><div class=field><label>المستوى المباشر</label><select id=sbLevel class=input></select></div><div class=field><label>Points</label><input id=sbPoints class=input type=number></div><div class=field><label>XP</label><input id=sbXp class=input type=number></div><div class=field><label>Cash</label><input id=sbCash class=input type=number step="0.01"></div><div class=field><label>الباقة</label><select id=sbPackage class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div></div><button class=btn onclick=saveSandboxUser()>حفظ تغييرات الحساب التجريبي</button><div id=sbMsg class=notice style="margin-top:12px">Sandbox/Test فقط — لا تستخدم هذه الأدوات مع بيانات الإنتاج.</div></div><div class=grid3 section><div class=card><h2>Full Loop</h2><p class=muted>مهمة → Pending → Approved → Reward.</p><button class=btn onclick="runSandbox('full-loop')">تشغيل</button></div><div class=card><h2>Fraud</h2><p class=muted>Warning → Limited → Suspended → Banned.</p><button class="btn secondary" onclick="runSandbox('fraud')">تشغيل</button></div><div class=card><h2>Withdrawal</h2><p class=muted>طلب → اعتماد/رفض → Refund.</p><button class="btn secondary" onclick="runSandbox('withdrawal')">تشغيل</button></div></div><div id=sbBox class=section></div>`}
async function loadSandbox(){try{const d=await api('/api/admin/sandbox/users'),s=$('#sbUser');if(!s)return;s.innerHTML=d.users.map(u=>`<option value="${u.id}">${esc(u.name||u.email||u.id)} — ${esc(u.role)} — ${esc(u.id)}</option>`).join('');$('#sbLevel').innerHTML=d.levels.map(l=>`<option value="${l.id}">${l.name} (${l.minXP} XP)</option>`).join('');const xp=$('#sbXp');const lv=$('#sbLevel');if(xp&&!xp.dataset.syncBound){xp.dataset.syncBound='1';xp.addEventListener('input',()=>{state.sandboxSyncMode='xp';const v=Math.max(0,Number(xp.value)||0);const chosen=[...lv.options].filter(o=>Number(o.textContent.match(/\((\d+) XP\)/)?.[1]||0)<=v).pop();if(chosen)lv.value=chosen.value})}if(lv&&!lv.dataset.syncBound){lv.dataset.syncBound='1';lv.addEventListener('change',()=>{state.sandboxSyncMode='level';const opt=lv.options[lv.selectedIndex];const min=Number(opt?.textContent.match(/\((\d+) XP\)/)?.[1]||0);if(xp)xp.value=min})}loadSandboxUserValues()}catch(e){toast(e.message)}}
function loadSandboxUserValues(){const idv=$('#sbUser')?.value;if(!idv)return;state.sandboxSyncMode='xp';api('/api/admin/sandbox/users').then(d=>{const u=d.users.find(x=>x.id===idv);if(!u)return;$('#sbPoints').value=u.points||0;$('#sbXp').value=u.xp||0;$('#sbCash').value=u.cash||0;$('#sbPackage').value=u.package||'Free';$('#sbLevel').value=u.level?.id||'bronze'}).catch(e=>toast(e.message))}
async function saveSandboxUser(){const confirm=prompt('رمز الأمان الخاص بحسابك');if(confirm===null)return;try{const payload={id:$('#sbUser').value,points:Number($('#sbPoints').value),cash:Number($('#sbCash').value),package:$('#sbPackage').value,confirm};if(state.sandboxSyncMode==='level')payload.levelId=$('#sbLevel').value;else payload.xp=Math.max(0,Number($('#sbXp').value)||0);const d=await api('/api/admin/sandbox/user',{method:'POST',body:JSON.stringify(payload)});$('#sbMsg').textContent='تم حفظ الحساب التجريبي: '+d.user.id+' — '+d.level.name+' — '+d.level.min+' XP';toast('تم تحديث Sandbox');loadSandboxUserValues()}catch(e){toast(e.message)}}
function previewPage(){if(state.user.role!=='owner'&&!state.user.permissions.includes('preview'))return `<div class=card><h1>غير مصرح</h1></div>`;return `<div class=hero><div class=preview>PREVIEW / SANDBOX</div><h1>Preview as User</h1><p>بدء المعاينة سينقلك مباشرة إلى واجهة المستخدم الكاملة داخل Sandbox.</p><button class=btn onclick="startPreview()">بدء المعاينة المعزولة</button></div>`}
function advertiserRender(){let c;if(state.view==='dashboard')c=`<div class=hero><h1>مرحباً بك في Tasko for Business</h1><p>إدارة الحملات والطلبات والنتائج من مكان واحد.</p><div class=row><button class=btn onclick="go('campaigns')">عرض حملاتي</button><button class="btn secondary" onclick="requestCampaign()">➕ طلب حملة جديدة</button></div></div><div id=advDash class=grid2>جارٍ التحميل...</div>`;else if(state.view==='campaigns')c=`<div class=space><div><h1>حملاتي</h1><p class=subtitle>تفاصيل الحملات، الميزانيات، الإنفاق، النتائج والتحليلات.</p></div><button class=btn onclick="requestCampaign()">➕ طلب حملة جديدة</button></div><div id=advDash class=section>جارٍ التحميل...</div>`;else if(state.view==='account')c=advertiserAccountPage();else c=advertiserAccountPage();layout(c)}
function advertiserAccountPage(){return `<div class=space><div><h1>معلومات الحساب</h1><p class=subtitle>كل معلومات المعلن الشخصية وحساب الشركة في صفحة مستقلة عن الحملات.</p></div></div><div id=advAccountBox class=section><div class=card>جارٍ تحميل معلومات الحساب...</div></div>`}
async function loadAdvertiserAccount(){try{const d=await api('/api/advertiser/account'),a=d.account,s=d.campaigns,e=$('#advAccountBox');if(!e)return;e.innerHTML=`<div class=grid2><div class=card><h2>المعلومات الشخصية والحسابية</h2><div class=detailList>${[['معرف الحساب',a.id],['معرف المعلن',a.advertiserId],['الاسم / المسؤول',a.name],['البريد الإلكتروني',a.email],['رقم الهاتف',a.phone],['المسمى الوظيفي',a.jobTitle],['الدولة',a.country],['المدينة',a.city],['تاريخ إنشاء الحساب',date(a.createdAt)]].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></div><div class=card><h2>بيانات الشركة</h2><div class=detailList>${[['اسم الشركة',a.company],['نوع النشاط',a.businessType],['نبذة',a.description],['حالة الحساب',a.status],['التحقق',a.verification],['نوع الحساب',a.vip?'VIP Advertiser':'Regular Advertiser']].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div><div class=grid2 style="margin-top:14px"><div class=reportStat><small>عدد الحملات</small><strong>${s.total}</strong></div><div class=reportStat><small>إجمالي الإنفاق</small><strong>${fmt(s.spend)} JOD</strong></div></div></div></div>`}catch(e){toast(e.message)}}


function userChallenges(u,challenges=[]){const by=(period)=>challenges.filter(x=>x.period===period);const mk=(x)=>{const target=Math.max(1,Number(x.goalTarget)||1),n=Math.min(target,Math.max(0,Number(x.progress)||0)),pct=Math.round(n/target*100);return `<div class=card><div class=space><div><b>${esc(x.title)}</b><small class=muted style="display:block;margin-top:4px">${esc(x.periodLabel||x.period)}</small></div><span class="pill ${pct===100?'green':''}">${n} / ${target}</span></div><div style="height:7px;background:#e9eef5;border-radius:999px;overflow:hidden;margin:14px 0 8px"><div style="width:${pct}%;height:100%;background:#2563eb"></div></div><div class=space><small class=muted>${pct}% مكتمل · ${pct===100?'مكتمل':'باقي '+(target-n)}</small><span class=reward>${fmt(x.points||0)} Points</span></div></div>`};if(!challenges.length)return '';return `<div class="section"><div class=space><div><h2>🎯 المهام الإضافية</h2><p class=muted>تحديات تظهر داخل الرئيسية وتتجدد حسب الدورة التي يحددها الـAdmin.</p></div></div><div class=grid3 style="margin-top:12px">${['daily','weekly','monthly'].flatMap(by).map(mk).join('')}</div></div>`}

async function userRender(){const u=state.user;let c;if(state.view==='dashboard'){let challenges=[];try{const cd=await api('/api/challenges');challenges=cd.challenges||[]}catch(e){console.error(e)}c=`<div class=hero><h1>أهلاً ${esc(u.name)} 👋</h1><p>كل مهمة مكتملة ترفع رصيدك وتزيد XP وتقرّبك من مستوى أعلى.</p><button class=btn onclick="go('tasks')">استكشف المهام</button></div><div class=grid><div class="card metric"><span class=icon>🎁</span><span class=kpi>Points</span><strong>${fmt(u.points)}</strong></div><div class="card metric"><span class=icon>💰</span><span class=kpi>Cash</span><strong>${fmt(u.cash)}</strong></div><div class="card metric"><span class=icon>⚡</span><span class=kpi>XP</span><strong>${fmt(u.xp)}</strong></div><div class="card metric"><span class=kpi>الباقة</span><strong style="font-size:22px">${esc(u.package||'Free')}</strong></div></div><div class=section>${levelBlock(u)}</div>${userChallenges(u,challenges)}<div class="grid2 section"><div class=card><div class=space><div><h2>تقدمك</h2><p class=muted>المستوى مستقل عن الباقة.</p></div><button class="btn secondary" onclick="go('profile')">تفاصيل الحساب</button></div></div><div class=card><div class=space><div><h2>الباقة الحالية</h2><p class=muted>الوصول والحدود حسب الباقة.</p></div><span class=pill>${esc(u.package||'Free')}</span></div><button class="btn" onclick="go('packages')">عرض الباقات</button></div></div>`}else if(state.view==='tasks')c=await tasksPage();else if(state.view==='packages')c=packagesPage();else if(state.view==='rewards')c=await rewardsPage();else if(state.view==='wallet')c=walletPage();else if(state.view==='referrals')c=await referralsPage();else if(state.view==='notifications')c=await notificationsPage();else if(state.view==='support')c=await supportPage();else if(state.view==='fairplay')c=fairPlayPage();else c=profilePage();layout(c)}

async function loadAdvDash(){const d=await api('/api/advertiser/dashboard');const cs=d.campaigns||[];const sum=cs.reduce((a,c)=>({budget:a.budget+Number(c.budget||0),spent:a.spent+Number(c.results?.spent||0),clicks:a.clicks+Number(c.results?.clicks||0),conv:a.conv+Number(c.results?.conversions||0)}),{budget:0,spent:0,clicks:0,conv:0});const cards=cs.map(c=>{const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;return `<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.objective||'حملة')}</small></div><span class="pill ${c.status==='active'?'green':'gold'}">${esc(c.status)}</span></div><div class=grid3 style="margin-top:13px"><div class=reportStat><small>الميزانية</small><strong>${fmt(c.budget)} JOD</strong></div><div class=reportStat><small>المصروف</small><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=reportStat><small>المتبقي</small><strong>${fmt(Math.max(0,Number(c.budget||0)-Number(c.results?.spent||0)))} JOD</strong></div><div class=reportStat><small>النقرات</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>التحويلات</small><strong>${fmt(c.results?.conversions)}</strong></div><div class=reportStat><small>الإنجاز</small><strong>${pct}%</strong></div></div><div style="height:7px;background:#e9eef5;border-radius:999px;overflow:hidden;margin:12px 0"><div style="width:${pct}%;height:100%;background:#2563eb"></div></div>${c.adminModifiedNotice?'<div class="notice">تم التعديل من قبل أدمن.</div>':''}${v25CampaignCode(c)}<button class="btn ghost" onclick='openCampaignDetails(${JSON.stringify(c).replace(/'/g,"&#39;")})'>عرض التفاصيل</button></div>`}).join('');const summary=`<div class="card metric"><span class=kpi>الحملات</span><strong>${fmt(cs.length)}</strong><small class=muted>${fmt(cs.filter(c=>c.status==='active').length)} شغالة · ${fmt(cs.filter(c=>c.status==='pending').length)} قيد المراجعة</small></div><div class="card metric"><span class=kpi>إجمالي الميزانية</span><strong>${fmt(sum.budget)} JOD</strong></div><div class="card metric"><span class=kpi>المصروف</span><strong>${fmt(sum.spent)} JOD</strong></div><div class="card metric"><span class=kpi>المتبقي</span><strong>${fmt(Math.max(0,sum.budget-sum.spent))} JOD</strong></div>`;$('#advDash').innerHTML=state.view==='dashboard'?summary+`<div class=section>${cards||'<div class=card empty>لا توجد حملات بعد.</div>'}</div>`:cards||'<div class=card empty>لا توجد حملات مسندة لحسابك بعد.</div>'}
function campaignChart(c){const b=Math.max(1,Number(c.budget)||1),s=Math.min(b,Number(c.results?.spent||0))/b,k=Math.min(1,Number(c.results?.clicks||0)/Math.max(1,Number(c.results?.clicks||0)+50)),v=Math.min(1,Number(c.results?.conversions||0)/Math.max(1,Number(c.results?.conversions||0)+10));const pts=[0.08,0.2+s*.18,0.38+k*.2,0.62+v*.16,Math.min(.94,.45+s*.35+k*.12+v*.08)];const p=pts.map((y,i)=>`${i*25+5},${92-y*70}`).join(' ');return `<div class=card style="margin-top:14px"><div class=space><h3>منحنى التقدم</h3><span class=pill>${Math.round(s*100)}%</span></div><svg viewBox="0 0 110 100" preserveAspectRatio="none" style="width:100%;height:150px;margin-top:10px" aria-label="Campaign progress chart"><polyline points="${p}" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/><line x1="5" y1="92" x2="105" y2="92" stroke="currentColor" opacity=".15"/></svg></div>`}

function requestCampaign(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:90vh;overflow:auto"><div class=space><h2>طلب حملة جديدة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>اسم الحملة</label><input id=rcn class=input></div><div class=field><label>الهدف</label><select id=rco class=input><option value="conversion">Conversions</option><option value="lead">Leads</option><option value="traffic">Traffic</option><option value="video">Video Views</option></select></div><div class=field><label>الميزانية المقترحة</label><input id=rcb class=input type=number min=0></div><div class=field><label>المدة المقترحة بالأيام</label><input id=rcd class=input type=number min=1></div><div class=field><label>نوع المهمة</label><select id=rct class=input><option>video</option><option>survey</option><option>signup</option><option>lead</option><option>testing</option><option>purchase</option></select></div><div class=field><label>الحد الأقصى لكل شخص</label><input id=rcm class=input type=number min=1 value="1"></div></div><div class=field><label>رابط المحتوى / الصفحة</label><input id=rcu class=input placeholder="YouTube أو رابط موقع أو منصة أخرى"></div><div class=field><label>وصف وتعليمات الحملة</label><textarea id=rcx class=input rows=5></textarea></div><button class=btn onclick="submitCampaignRequest()">إرسال الطلب</button></div>`;document.body.appendChild(m)}
async function submitCampaignRequest(){try{const d=await api('/api/advertiser/campaign',{method:'POST',body:JSON.stringify({name:$('#rcn').value,objective:$('#rco').value,budget:$('#rcb').value,startAt:null,endAt:null,taskType:$('#rct').value,maxPerUser:$('#rcm').value,landingUrl:$('#rcu').value,description:$('#rcx').value,conditions:$('#rcx').value})});document.querySelector('.modalBack')?.remove();toast('تم إرسال طلب الحملة للمراجعة');go('campaigns')}catch(e){toast(e.message)}}

async function loadRewardsAdmin(){const e=$('#rewardsAdminBox');if(!e)return;try{const d=await api('/api/admin/rewards');$('#rp').innerHTML='<option value="">بدون شريك</option>'+d.partners.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');e.innerHTML=d.offers.map(o=>`<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(o.title)}</h2><small class=muted>${esc(o.partner||'بدون شريك')} · ${fmt(o.pointsCost)} Points · ${levelLabel(o)}+</small></div><span class="pill ${o.active?'green':'red'}">${o.active?'مفعلة':'موقوفة'}</span></div><p>${esc(o.description||'')}</p><div class=taskMeta><span class=pill>الباقة: ${esc(o.packageMin||'Free')}</span><span class=pill>الاستخدام: ${fmt(o.usesPerUser||1)}</span><span class=pill>${esc(o.redemptionType||'code')}</span></div><div class=row style="margin-top:10px"><button class="btn secondary" onclick='editReward(${JSON.stringify(o).replace(/'/g,"&#39;")})'>تعديل</button><button class="btn ${o.active?'danger':'secondary'}" onclick="toggleReward('${esc(o.id)}',${!o.active})">${o.active?'إيقاف':'تفعيل'}</button><button class="btn danger" onclick="deleteReward('${esc(o.id)}')">حذف</button></div></div>`).join('')||'<div class=card empty>لا توجد مكافآت.</div>'}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المكافآت.</div>';toast(err.message)}}
function editReward(o){const title=prompt('اسم المكافأة',o.title);if(title===null)return;const description=prompt('الوصف',o.description||'');if(description===null)return;const points=prompt('النقاط المطلوبة',o.pointsCost);if(points===null)return;const levelMin=prompt('الحد الأدنى للمستوى',o.levelMin||0);if(levelMin===null)return;const packageMin=prompt('الباقة المطلوبة: Free / Plus / Premium',o.packageMin||'Free');if(packageMin===null)return;const uses=prompt('عدد الاستخدامات لكل مستخدم',o.usesPerUser||1);if(uses===null)return;const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id:o.id,title,description,pointsCost:Number(points),levelMin:Number(levelMin),packageMin,usesPerUser:Number(uses),confirm})}).then(()=>{toast('تم تعديل المكافأة');render()}).catch(e=>toast(e.message))}
async function addReward(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards',{method:'POST',body:JSON.stringify({title:$('#rn').value,description:$('#rd').value,partnerId:$('#rp').value,pointsCost:Number($('#rc').value)||0,levelMin:Number($('#rl').value)||0,packageMin:$('#rpg').value,usesPerUser:Number($('#ru').value)||1,redemptionType:$('#rt').value,active:$('#ra').checked,confirm})});toast('تمت إضافة المكافأة');render()}catch(e){toast(e.message)}}
async function toggleReward(id,active){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id,active,confirm})});toast(active?'تم تفعيل المكافأة':'تم إيقاف المكافأة');render()}catch(e){toast(e.message)}}
async function deleteReward(id){if(!confirm('حذف المكافأة نهائياً؟'))return;const code=prompt('رمز التأكيد الأمني من 4 أرقام');if(code===null)return;try{await api('/api/admin/rewards/delete',{method:'POST',body:JSON.stringify({id,confirm:code})});toast('تم حذف المكافأة');render()}catch(e){toast(e.message)}}

async function createCampaign(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/campaigns',{method:'POST',body:JSON.stringify({name:$('#cn').value,budget:$('#cb').value,advertiserId:$('#ca').value,objective:$('#co').value,taskType:$('#ct').value,rewardPerPerson:$('#cr').value,maxPerUser:$('#cm').value,xp:$('#cxp').value,levelMin:$('#cl').value,packageMin:$('#cp').value,verification:$('#cv').value,requiredPeople:$('#crp').value,estimatedMinutes:$('#cem').value,startAt:$('#cs').value,endAt:$('#ce').value,description:$('#cd').value,conditions:$('#ci').value,contentUrl:$('#cu').value,landingUrl:$('#clu').value,contentType:$('#ct').value,confirm})});toast('تم إنشاء الحملة');render()}catch(e){toast(e.message)}}

function openAdminCampaign(c){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>اسم الحملة</label><input id=ecn class=input value="${esc(c.name)}"></div><div class=field><label>الحالة</label><select id=ecs class=input><option>draft</option><option>pending</option><option>needs_changes</option><option>preparing</option><option>active</option><option>paused</option><option>completed</option><option>rejected</option></select></div><div class=field><label>الميزانية JOD</label><input id=ecb class=input type=number value="${Number(c.budget||0)}"></div><div class=field><label>المصروف JOD</label><input id=ecsp class=input type=number value="${Number(c.results?.spent||0)}"></div><div class=field><label>المكافأة لكل شخص</label><input id=ecr class=input type=number value="${Number(c.rewardPerPerson||0)}"></div><div class=field><label>XP</label><input id=ecxp class=input type=number value="${Number(c.xp||0)}"></div><div class=field><label>أقصى عدد للشخص</label><input id=ecm class=input type=number value="${Number(c.maxPerUser||1)}"></div><div class=field><label>الحد الأدنى للمستوى</label><select id=ecl class=input><option value="bronze">Bronze</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="diamond">Diamond</option></select></div><div class=field><label>أقل باقة</label><select id=ecp class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>تاريخ البداية</label><input id=ecsdate class=input type=datetime-local value="${c.startAt?String(c.startAt).slice(0,16):''}"></div><div class=field><label>تاريخ النهاية</label><input id=ecedate class=input type=datetime-local value="${c.endAt?String(c.endAt).slice(0,16):''}"></div><div class=field><label>التحقق</label><select id=ecv class=input><option>auto</option><option>pending</option><option>manual</option></select></div></div><div class=field><label>الوصف</label><textarea id=ecd class=input rows=3>${esc(c.description||'')}</textarea></div><div class=field><label>التعليمات</label><textarea id=eci class=input rows=4>${esc(c.conditions||'')}</textarea></div><div class=field><label>رابط المحتوى</label><input id=ecu class=input value="${esc(c.contentUrl||'')}"></div><div class=field><label>رابط التتبع</label><input id=eclu class=input value="${esc(c.landingUrl||'')}"></div><div class=notice>Reference / Tracking ID: <b>${esc(c.referenceId||'—')}</b> · Tracking: <b>${esc(c.trackingId||'—')}</b></div><div class=row style="margin-top:14px"><button class=btn onclick="saveCampaignEdit('${esc(c.id)}')">حفظ التعديل</button><button class="btn secondary" onclick="campaignDecision('${esc(c.id)}','active')">اعتماد ونشر</button><button class="btn ghost" onclick="campaignDecision('${esc(c.id)}','paused')">إيقاف مؤقت</button><button class="btn danger" onclick="campaignDecision('${esc(c.id)}','rejected')">رفض</button></div></div>`;document.body.appendChild(m);$('#ecs').value=c.status||'pending';$('#ecl').value=c.levelMinId||levelLabel(c).toLowerCase();$('#ecp').value=c.packageMin||'Free';$('#ecv').value=c.verification||'pending'}
async function saveCampaignEdit(id){try{await api('/api/admin/campaigns/update',{method:'POST',body:JSON.stringify({id,name:$('#ecn').value,status:$('#ecs').value,budget:Number($('#ecb').value)||0,spent:Number($('#ecsp').value)||0,rewardPerPerson:Number($('#ecr').value)||0,xp:Number($('#ecxp').value)||0,maxPerUser:Number($('#ecm').value)||1,levelMinId:$('#ecl').value,packageMin:$('#ecp').value,startAt:$('#ecsdate').value||null,endAt:$('#ecedate').value||null,verification:$('#ecv').value,description:$('#ecd').value,conditions:$('#eci').value,contentUrl:$('#ecu').value,landingUrl:$('#eclu').value,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تعديل الحملة');render()}catch(e){toast(e.message)}}
async function campaignDecision(id,status){try{await api('/api/admin/campaigns/status',{method:'POST',body:JSON.stringify({id,status,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تحديث حالة الحملة');render()}catch(e){toast(e.message)}}
function adminAdvertisers(){return `<div class=space><div><h1>المعلنون</h1><p class=subtitle>حسابات الشركات + طلبات إنشاء حسابات المعلنين.</p></div><button class=btn onclick="v27CreateAdvertiserModal()">+ إنشاء معلن</button></div><div id=advBox class=section>جارٍ التحميل...</div><div id=reqBox class=section>جارٍ تحميل طلبات المعلنين...</div>`}
function v27CreateAdvertiserModal(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><div class=space><h2>إنشاء معلن</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>الشركة</label><input id=ac class=input></div><div class=field><label>جهة الاتصال</label><input id=acn class=input></div><div class=field><label>البريد</label><input id=ace class=input type=email></div><div class=field><label>كلمة المرور</label><input id=acp class=input type=password></div></div><label class=checkRow><input id=vip type=checkbox> VIP Advertiser</label><button class=btn onclick="createAdv();document.querySelector('.modalBack')?.remove()">إنشاء الحساب</button></div>`;document.body.appendChild(m)}
async function loadAdv(){const d=await api('/api/admin/advertisers');$('#advBox').innerHTML=d.advertisers.map(a=>`<div class=card style="margin:10px 0"><div class=space><h3>${esc(a.company)}</h3><span class="pill ${a.vip?'gold':'blue'}">${a.vip?'VIP':'Regular'}</span></div><p>${esc(a.email)} · ${esc(a.status)}</p><small class=muted>${date(a.verifiedAt)}</small><button class="btn ghost" style="margin-top:8px" onclick="openAdvertiserProfile('${esc(a.id)}')">فتح الملف</button></div>`).join('')||'<div class=card empty>لا يوجد معلنون.</div>';loadAdvertiserRequests()}
async function loadAdvertiserRequests(){const e=$('#reqBox');if(!e)return;try{const d=await api('/api/admin/advertiser-requests');e.innerHTML=`<div class=card><div class=space><h2>طلبات إنشاء حساب معلن</h2><span class=pill>${fmt(d.requests.length)} طلب</span></div>${d.requests.map(r=>`<div class=detailItem" style="margin:10px 0"><div class=space><div><b>${esc(r.company)}</b><small style="display:block">${esc(r.contact)} · ${esc(r.email)} · ${esc(r.phone)}</small></div><span class="pill ${r.status==='pending'?'gold':r.status==='approved'?'green':'red'}">${esc(r.status)}</span></div><button class="btn ghost" style="margin-top:8px" onclick='openAdvertiserRequest(${JSON.stringify(r).replace(/'/g,"&#39;")})'>فتح الطلب</button></div>`).join('')||'<div class=empty>لا توجد طلبات.</div>'}</div>`}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل طلبات المعلنين.</div>'}}
function openAdvertiserRequest(r){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>تفاصيل طلب المعلن</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=detailList>${[['الشركة',r.company],['المسؤول',r.contact],['المسمى',r.jobTitle],['البريد',r.email],['الهاتف',r.phone],['المجال',r.businessType||r.industry],['النبذة',r.description],['الحالة',r.status]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div><div class=field style="margin-top:14px"><label>تعديل الحالة</label><select id=arStatus class=input><option value="pending">قيد الانتظار</option><option value="under_review">قيد المراجعة</option><option value="needs_changes">يحتاج تعديلات</option><option value="approved">مقبول</option><option value="rejected">مرفوض</option></select></div><div class=row style="margin-top:14px"><button class=btn onclick="saveAdvertiserRequestStatus('${esc(r.id)}')">حفظ الحالة</button><button class="btn secondary" onclick="processAdvertiserRequest('${esc(r.id)}','approve')">موافقة وإنشاء الحساب</button><button class="btn danger" onclick="processAdvertiserRequest('${esc(r.id)}','reject')">رفض</button></div></div>`;document.body.appendChild(m);$('#arStatus').value=r.status||'pending'}
async function saveAdvertiserRequestStatus(id){try{const d=await api('/api/admin/advertiser-request/status',{method:'POST',body:JSON.stringify({id,status:$('#arStatus').value,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تعديل حالة الطلب');render()}catch(e){toast(e.message)}}



async function updateAdmin(id,data){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/admins/update',{method:'POST',body:JSON.stringify({id,...data,confirm})});toast('تم تحديث الأدمن');render()}catch(e){toast(e.message)}}function toggleAdmin(id,stateVal){updateAdmin(id,{accountState:stateVal})}



async function switchTestPackage(id,pkg){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{const d=await api('/api/admin/test-user/package',{method:'POST',body:JSON.stringify({id,package:pkg,confirm})});const m=document.querySelector('.modalBack .modal');if(m){m.querySelectorAll('.detailItem').forEach(x=>{if(x.querySelector('small')?.textContent==='الباقة')x.querySelector('b').textContent=d.user.package});m.querySelectorAll('.row .btn').forEach(b=>b.classList.remove('secondary'));const active=[...m.querySelectorAll('.row .btn')].find(b=>b.textContent.trim()===pkg);active?.classList.add('secondary')}toast('تم تغيير الباقة بدون Reset للبيانات')}catch(e){toast(e.message)}}



/* ===== Tasko V14 ===== */
const P_META={users:'المستخدمون',tasks:'المهام',campaigns:'الحملات',partners:'الشركاء',withdrawals:'السحوبات',rewards:'المكافآت',referrals:'الإحالات',subscriptions:'الاشتراكات',fraud:'المخالفات',support:'الدعم والتذاكر',reports:'التقارير',audit:'سجل التدقيق',settings:'مركز التحكم',sandbox:'Sandbox',admins:'إدارة الأدمن',advertisers:'المعلنون',preview:'المعاينة'};


function pathView(){const a=location.pathname.replace(/\/$/,'').split('/').filter(Boolean);if(a[0]==='admin'||a[0]==='advertiser'||a[0]==='preview')return a[1]||'dashboard';return a[0]||'dashboard'}

window.addEventListener('popstate',()=>{state.view=pathView();render()});



async function login(){try{const p=state.portal,d=await api('/api/login/'+p,{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});state.token=d.token;state.user=d.user;state.portal=d.portal;sessionStorage.setItem('taskoToken',d.token);sessionStorage.setItem('taskoPortal',d.portal);localStorage.setItem('taskoPortal',d.portal);if($('#rememberDevice')?.checked)localStorage.setItem('taskoToken',d.token);else localStorage.removeItem('taskoToken');history.replaceState({},'',routeForView('dashboard'));render()}catch(e){toast(e.message)}}
async function logout(){try{if(state.token)await api('/api/logout',{method:'POST'})}catch{}sessionStorage.clear();localStorage.removeItem('taskoToken');localStorage.removeItem('taskoPortal');state={token:null,user:null,view:'dashboard',portal:'user',preview:false,lang:state.lang||'ar'};history.replaceState({},'','/');auth()}
function adminsPage(){return `<div class=space><div><h1>إدارة الأدمن</h1><p class=subtitle>لكل Admin كود أمان سري مستقل، والصلاحيات يحددها الـOwner فقط.</p></div><button class=btn onclick="v27CreateAdminModal()">+ إضافة Admin</button></div><div id=adminsBox class=section>جارٍ التحميل...</div>`}
function v27CreateAdminModal(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class="modal adminPermModal"><div class=space><h2>إضافة Admin</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>الاسم</label><input id=adn class=input></div><div class=field><label>البريد</label><input id=ade class=input type=email></div><div class=field><label>كلمة المرور</label><input id=adp class=input type=password></div><div class=field><label>كود الأمان الخاص بالأدمن (4 أرقام)</label><input id=adpin class=input type=password inputmode=numeric maxlength=4></div></div><div class=field><label>الصلاحيات</label><div id=perms></div></div><button class=btn onclick="createAdmin();document.querySelector('.modalBack')?.remove()">إنشاء Admin</button></div>`;document.body.appendChild(m);loadPerms()}
function editAdmin(id){api('/api/admin/admins').then(d=>{const a=d.admins.find(x=>x.id===id),m=document.createElement('div');if(!a)return; m.className='modalBack';m.innerHTML=`<div class="modal adminPermModal"><div class=space><h2>تعديل صلاحيات ${esc(a.name)}</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div id=editPerms>${Object.entries(P_META).map(([k,v])=>`<label class=checkRow><input type=checkbox value=${k} ${a.permissions.includes(k)?'checked':''}> ${v}</label>`).join('')}</div><div class=field><label>كود أمان جديد (اختياري)</label><input id=editAdminPin class=input type=password maxlength=4 inputmode=numeric></div><button class=btn onclick="saveAdminEdit('${esc(id)}')">حفظ التعديلات</button></div>`;document.body.appendChild(m)})}
async function saveAdminEdit(id){const pin=$('#editAdminPin').value;if(pin&&!/^\d{4}$/.test(pin))return toast('الكود يجب أن يكون 4 أرقام');const permissions=[...document.querySelectorAll('#editPerms input:checked')].map(x=>x.value);const confirm=prompt('أدخل كود الأمان الخاص بحسابك');if(confirm===null)return;const body={id,permissions,confirm};if(pin)body.emergencyPin=pin;try{await api('/api/admin/admins/update',{method:'POST',body:JSON.stringify(body)});document.querySelector('.modalBack')?.remove();toast('تم تحديث الأدمن');render()}catch(e){toast(e.message)}}
async function changeAdminPin(id){const pin=prompt('كود الأمان الجديد (4 أرقام)');if(pin===null)return;if(!/^\d{4}$/.test(pin))return toast('الكود يجب أن يكون 4 أرقام');const confirm=prompt('أدخل كود الأمان الخاص بحسابك');if(confirm===null)return;try{await api('/api/admin/admins/update',{method:'POST',body:JSON.stringify({id,emergencyPin:pin,confirm})});toast('تم تغيير كود الأمان');render()}catch(e){toast(e.message)}}
async function adminResetPassword(id){const np=prompt('كلمة المرور الجديدة');if(!np)return;const confirm=prompt('أدخل كود الأمان الخاص بحسابك');if(confirm===null)return;try{await api('/api/admin/admins/password',{method:'POST',body:JSON.stringify({id,password:np,confirm})});toast('تم تغيير كلمة المرور');render()}catch(e){toast(e.message)}}
async function openAdminPerson(id){try{const d=await api('/api/admin/user/'+encodeURIComponent(id)),u=d.user;const m=document.createElement('div');m.className='modalBack';const pkg=u.role==='user'?`<div class="card packageControl"><h3>تغيير الباقة — اختبار</h3><p class=muted>بدون Reset للبيانات.</p><div class=row><button class=btn onclick="switchTestPackage('${esc(u.id)}','Free')">Free</button><button class=btn onclick="switchTestPackage('${esc(u.id)}','Plus')">Plus</button><button class=btn onclick="switchTestPackage('${esc(u.id)}','Premium')">Premium</button></div></div>`:`<div class="card packageControl"><h3>حساب معلن</h3><p class=muted>المعلنون منفصلون عن باقات المستخدمين. لا يوجد Free / Plus / Premium.</p></div>`;m.innerHTML=`<div class="modal profileModal"><div class=space><div><h2>${esc(u.company||u.name)}</h2><small>ID: ${esc(u.id)} <button class="btn secondary copyMini" onclick="copyText('${esc(u.id)}')">نسخ</button></small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=profileAdminGrid><div class=card><div class=detailList>${[['الاسم',u.name],['البريد',u.email],['الهاتف',u.phone],['الحالة',u.accountState],['الباقة',u.package||'Free'],['المستوى',u.level?.name||levelInfo(u.xp).name],['XP',u.xp||0],['Points',u.points||0],['Cash',u.cash||0]].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div></div>${pkg}</div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}}
function copyText(v){navigator.clipboard?.writeText(v).then(()=>toast('تم النسخ')).catch(()=>toast('انسخ يدوياً: '+v))}
function auditPage(){return `<h1>سجل التدقيق</h1><p class=subtitle>سجل واضح للعمليات بدون JSON خام.</p><div class=card><input id=aq class=input placeholder="بحث باسم الشخص أو العملية أو الهدف" oninput=loadAudit()></div><div id=auBox class=section>جارٍ التحميل...</div>`}
async function loadAudit(){const d=await api('/api/admin/audit?q='+encodeURIComponent($('#aq')?.value||'')+'&page=1&size=50'),act={admin_create:'إنشاء أدمن',admin_update:'تعديل أدمن',admin_password_change:'تغيير كلمة مرور',emergency_control:'تغيير وضع الطوارئ',test_user_package_switch:'تغيير باقة مستخدم تجريبي',task_create:'إنشاء مهمة',task_update:'تعديل مهمة',task_toggle:'تغيير حالة مهمة',campaign_create:'إنشاء حملة',campaign_update:'تعديل حملة',campaign_status:'تغيير حالة حملة',ticket_update:'تحديث تذكرة',fraud_action:'إجراء مخالفة',package_update:'تعديل باقة',reward_create:'إنشاء مكافأة',reward_update:'تعديل مكافأة',reward_delete:'حذف مكافأة',sandbox_user_edit:'تعديل مستخدم Sandbox'};$('#auBox').innerHTML=`<div class=card><div class=space><h2>السجل</h2><span class=pill>${d.total} عملية</span></div><div class=tableWrap><table class=table><tr><th>الوقت</th><th>المنفذ</th><th>العملية</th><th>الهدف</th><th>التفاصيل</th></tr>${d.items.map(x=>`<tr><td>${date(x.at)}</td><td>${esc(x.actorName||x.actorId)}</td><td>${esc(act[x.action]||x.action)}</td><td>${esc(x.targetName||x.target)}</td><td>${x.meta?.from!==undefined?esc(`من ${x.meta.from} إلى ${x.meta.to}`):x.meta?.reason?esc(x.meta.reason):x.meta?.permissions?`صلاحيات: ${x.meta.permissions.length}`:'—'}</td></tr>`).join('')||'<tr><td colspan=5 class=empty>لا نتائج.</td></tr>'}</table></div></div>`}
function adminSupport(){return `<h1>الدعم والتذاكر</h1><div id=sBox>جارٍ التحميل...</div>`}
async function loadSupport(){const d=await api('/api/admin/tickets'),open=d.tickets.filter(t=>t.status!=='closed'),closed=d.tickets.filter(t=>t.status==='closed');const card=t=>`<div class=card style="margin:10px 0"><div class=space><b>${esc(t.subject)}</b><span class=pill>${esc(t.status)}</span></div>${t.messages.map(m=>`<p><b>${esc(m.by)}</b>: ${esc(m.text)}</p>`).join('')}${t.status!=='closed'?`<div class=row><button class=btn onclick="replyTicket('${esc(t.id)}')">رد</button><button class="btn danger" onclick="closeTicket('${esc(t.id)}')">إغلاق التذكرة</button></div>`:'<div class=notice>مغلقة — قراءة فقط.</div>'}</div>`;$('#sBox').innerHTML=`<h2>تحتاج إجراء (${open.length})</h2>${open.map(card).join('')||'<div class=card empty>لا توجد تذاكر تحتاج إجراء.</div>'}<div class=section><h2>مغلقة (${closed.length})</h2>${closed.map(card).join('')||'<div class=card empty>لا توجد تذاكر مغلقة.</div>'}</div>`}
async function closeTicket(id){const confirm=prompt('أدخل كود الأمان الخاص بحسابك');if(confirm===null)return;try{await api('/api/admin/ticket',{method:'POST',body:JSON.stringify({id,status:'closed',confirm})});toast('تم إغلاق التذكرة');render()}catch(e){toast(e.message)}}
async function supportPage(){const d=await api('/api/tickets');return `<h1>الدعم</h1><div class=grid2><div class=card><h2>فتح تذكرة</h2><div class=field><label>الموضوع</label><input id=ts class=input></div><div class=field><label>الرسالة</label><textarea id=tm class=input rows=5></textarea></div><button class=btn onclick=ticket()>إرسال</button></div><div><h2>تذاكرك</h2>${d.tickets.map(t=>`<div class=card style="margin:10px 0"><div class=space><b>${esc(t.subject)}</b><span class=pill>${esc(t.status)}</span></div>${t.messages.map(m=>`<p><b>${esc(m.by)}</b>: ${esc(m.text)}</p>`).join('')}${t.status!=='closed'?`<textarea id="reply_${esc(t.id)}" class=input rows=2 placeholder="اكتب ردك"></textarea><button class=btn onclick="replyUserTicket('${esc(t.id)}')">إرسال</button>`:'<div class=notice>التذكرة مغلقة.</div>'}</div>`).join('')||'<div class=card empty>لا توجد تذاكر.</div>'}</div></div>`}
async function replyUserTicket(id){const e=$('#reply_'+CSS.escape(id)),message=e?.value?.trim();if(!message)return toast('اكتب الرسالة أولاً');try{await api('/api/ticket/reply',{method:'POST',body:JSON.stringify({id,message})});toast('تم إرسال الرد');render()}catch(e){toast(e.message)}}

const previewState={package:'Free',points:1250,xp:1850,cash:12,tickets:[]};
function previewUserRender(){const u={name:'Preview User',id:'preview-user',xp:previewState.xp,points:previewState.points,cash:previewState.cash,package:previewState.package,accountState:'Normal'};let c;if(state.view==='dashboard')c=`<div class=hero><div class=preview>PREVIEW / SANDBOX</div><h1>مرحباً بك في Tasko 👋</h1><p>محاكاة كاملة معزولة عن البيانات الحقيقية.</p><button class=btn onclick="go('tasks')">استكشف المهام</button></div><div class=grid><div class=card metric><span class=kpi>Points</span><strong>${u.points}</strong></div><div class=card metric><span class=kpi>Cash</span><strong>${u.cash}</strong></div><div class=card metric><span class=kpi>XP</span><strong>${u.xp}</strong></div><div class=card metric><span class=kpi>الباقة</span><strong>${u.package}</strong></div></div>`;else if(state.view==='tasks')c=`<h1>المهام — Sandbox</h1><div class=grid2>${[['مشاهدة فيديو',50,20],['استبيان قصير',150,50],['اختبار موقع',300,100]].map(x=>`<div class=card><h2>${x[0]}</h2><div class=taskMeta><span class=reward>${x[1]} Points</span><span class=pill>+${x[2]} XP</span></div><button class=btn onclick="previewTask(${x[1]},${x[2]})">إكمال تجريبي</button></div>`).join('')}</div>`;else if(state.view==='packages')c=`<h1>الباقات — Sandbox</h1><div class=grid3>${['Free','Plus','Premium'].map(x=>`<div class="card package ${x.toLowerCase()} ${u.package===x?'current':''}"><h2>${x}</h2><p>تدفق اشتراك تجريبي.</p><button class=btn onclick="previewBuy('${x}')">${u.package===x?'الحالية':'اختيار'}</button></div>`).join('')}</div>`;else if(state.view==='wallet')c=`<h1>المحفظة — Sandbox</h1><div class=grid2><div class=card metric><span class=kpi>Points</span><strong>${u.points}</strong></div><div class=card metric><span class=kpi>Cash</span><strong>${u.cash}</strong></div></div><button class=btn onclick="toast('تمت محاكاة السحب فقط')">محاكاة سحب</button>`;else if(state.view==='support')c=previewSupport();else c=`<h1>الملف الشخصي — Sandbox</h1><div class=card><div class=detailList><div class=detailItem><small>Account ID</small><b>${u.id}</b></div><div class=detailItem><small>Package</small><b>${u.package}</b></div></div></div>`;layout(c)}
function previewTask(p,x){previewState.points+=p;previewState.xp+=x;toast('تم إكمال المهمة داخل Sandbox فقط');render()}
function previewBuy(pkg){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><h2>اشتراك ${pkg} — Sandbox</h2><p class=muted>لن يتم خصم أي مبلغ حقيقي.</p><input class=input value="4242 4242 4242 4242"><div class=row style="margin-top:12px"><button class=btn onclick="previewFinish('${pkg}')">متابعة الدفع التجريبي</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)}function previewFinish(pkg){previewState.package=pkg;document.querySelector('.modalBack')?.remove();toast('تم تفعيل الباقة داخل Sandbox فقط');render()}
function previewSupport(){return `<h1>الدعم — Sandbox</h1><div class=grid2><div class=card><h2>فتح تذكرة</h2><input id=psub class=input placeholder="الموضوع"><textarea id=pmsg class=input rows=4 placeholder="الرسالة" style="margin-top:8px"></textarea><button class=btn style="margin-top:8px" onclick="previewTicket()">إرسال</button></div><div>${previewState.tickets.map(t=>`<div class=card><div class=space><b>${esc(t.subject)}</b><span class=pill>${t.status}</span></div>${t.messages.map(m=>`<p>${esc(m.by)}: ${esc(m.text)}</p>`).join('')}${t.status!=='closed'?`<input id=pr_${t.id} class=input placeholder="رد"><button class=btn onclick="previewReply('${t.id}')">إرسال</button><button class="btn danger" onclick="previewClose('${t.id}')">إغلاق</button>`:''}</div>`).join('')||'<div class=card empty>لا توجد تذاكر.</div>'}</div></div>`}
function previewTicket(){const s=$('#psub').value.trim(),m=$('#pmsg').value.trim();if(!s||!m)return toast('أكمل بيانات التذكرة');previewState.tickets.push({id:'p'+Date.now(),subject:s,status:'open',messages:[{by:'Preview User',text:m},{by:'Tasko Support (Sandbox)',text:'تم استلام التذكرة التجريبية.'}]});render()}function previewReply(id){const e=$('#pr_'+CSS.escape(id)),m=e?.value?.trim(),t=previewState.tickets.find(x=>x.id===id);if(!m||!t||t.status==='closed')return;t.messages.push({by:'Preview User',text:m});t.messages.push({by:'Tasko Support (Sandbox)',text:'تم استلام الرد التجريبي.'});render()}function previewClose(id){const t=previewState.tickets.find(x=>x.id===id);if(t)t.status='closed';render()}
function exitPreview(){state.preview=false;state.portal='admin';history.pushState({},'', '/admin/preview');render()}
async function startPreview(){try{const d=await api('/api/admin/preview',{method:'POST'});state.preview=true;state.previewData=d;state.portal='user';history.pushState({},'', '/preview');render()}catch(e){toast(e.message)}}
async function loadAdmins(){const e=$('#adminsBox');if(!e)return;try{const d=await api('/api/admin/admins');const rows=d.admins||[];e.innerHTML=rows.map(a=>`<div class="card" style="margin:10px 0"><div class="space"><div><h3>${esc(a.name||'Admin')}</h3><small class=muted>${esc(a.email||'—')} · ${esc(a.id||'')}</small></div><span class="pill ${a.accountState==='Normal'?'green':'gold'}">${esc(a.accountState||'Normal')}</span></div><div class="taskMeta">${(a.permissions||[]).map(p=>`<span class="pill">${esc(p)}</span>`).join('')||'<span class="muted">لا توجد صلاحيات مخصصة.</span>'}</div><div class="row" style="margin-top:10px"><button class="btn secondary" onclick="editAdmin('${esc(a.id)}')">تعديل الصلاحيات</button></div></div>`).join('')||'<div class="card empty">لا يوجد أدمن حالياً.</div>'}catch(err){e.innerHTML='<div class="card empty">تعذر تحميل الأدمن.</div>'}}

function afterLayout(){const jobs=[[loadSummary,'#summaryBox'],[loadUsers,'#usersBox'],[loadAdv,'#adBox'],[loadAdmins,'#adminsBox'],[loadAdv,'#advBox'],[loadAdvertiserRequests,'#reqBox'],[loadCampaigns,'#campBox'],[loadAdminTasks,'#taskAdminBox'],[loadW,'#wBox'],[loadSupport,'#sBox'],[loadFraud,'#fraudBox'],[loadReports,'#reportBox'],[loadActivities,'#activityBox'],[loadAudit,'#auBox'],[loadSettings,'#emergencyPanel'],[loadPackagesAdmin,'#pkgAdmin'],[loadRewardsAdmin,'#rewardsAdminBox'],[loadAdvDash,'#advDash'],[loadAdvertiserAccount,'#advAccountBox'],[loadSandbox,'#sbUser'],[loadUserWithdrawals,'#userWithdrawals'],[loadUserWithdrawals,'#wUser']];for(const [fn,sel] of jobs){if(!$(sel))continue;Promise.resolve().then(()=>fn()).catch(err=>{console.error('Tasko loader failed:',sel,err);const e=$(sel);if(e)e.innerHTML='<div class=card empty>تعذر تحميل هذه البيانات. جرّب تحديث الصفحة.</div>'})}}
/* Keep the detected/persisted language instead of overriding it after initialization. */
state.lang=state.lang||v17LangDefault();state.view=pathView();render();

function advertiserCompanyProfile(){const u=state.user||{};return `<h1>ملف الشركة</h1><p class=subtitle>بيانات الشركة منفصلة عن الحملات وباقات المستخدمين.</p><div class=grid2 section><div class=card><h2>${esc(u.company||'شركة المعلن')}</h2><div class=detailList><div class=detailItem><small>Account ID</small><div class=row><b>${esc(u.id||'—')}</b><button class="btn secondary" onclick="copyText('${esc(u.id||'')}')">نسخ</button></div></div><div class=detailItem><small>المسؤول</small><b>${esc(u.name||'—')}</b></div><div class=detailItem><small>البريد</small><b>${esc(u.email||'—')}</b></div><div class=detailItem><small>الهاتف</small><b>${esc(u.phone||'—')}</b></div></div></div><div class=card><h2>حساب المعلن</h2><p class=muted>${u.vip?'VIP Advertiser':'Regular Advertiser'}</p><div class=notice>Free / Plus / Premium غير متاحة للمعلنين.</div></div></div>`}
function usersPage(){return `<h1>المستخدمون</h1><p class=subtitle>ابحث بالاسم أو البريد أو الهاتف أو Account ID.</p><div class=card><div class=searchRow><input id=uq class=input placeholder="بحث بالاسم أو البريد أو الهاتف أو ID" oninput="loadUsers()"><select id=us class=input onchange="loadUsers()"><option value="">كل الحالات</option><option>Normal</option><option>Limited</option><option>Suspended</option><option>Banned</option></select><button class="btn secondary" onclick="loadUsers()">تحديث</button></div></div><div id=usersBox class=section>جارٍ التحميل...</div>`}
async function loadUsers(){const q=$('#uq')?.value||'',s=$('#us')?.value||'';const d=await api('/api/admin/users?q='+encodeURIComponent(q)+'&state='+encodeURIComponent(s));$('#usersBox').innerHTML=`<div class=card><div class=space><h2>النتائج</h2><span class=pill>${d.total} مستخدم</span></div><div class=tableWrap><table class=table><tr><th>المستخدم</th><th>ID</th><th>الحالة</th><th>المستوى</th><th>الباقة</th><th>إجراء</th></tr>${d.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small>${esc(u.email)}</small></td><td><div class=row><code>${esc(u.id)}</code><button class="btn secondary copyMini" onclick="copyText('${esc(u.id)}')">نسخ</button></div></td><td>${esc(u.accountState)}</td><td>${esc(u.level?.name||levelInfo(u.xp).name)}</td><td>${esc(u.package||'Free')}</td><td><button class="btn ghost" onclick="openAdminPerson('${esc(u.id)}')">فتح الملف</button></td></tr>`).join('')||'<tr><td colspan=6 class=empty>لا نتائج.</td></tr>'}</table></div></div>`}
function adminDashboard(){return `<div class=hero><h1>Owner Control Center</h1><p>المهمات التي تحتاج إجراء تظهر أولاً.</p><div id=summaryBox class=grid2>جارٍ التحميل...</div></div>`}
function auth(){const p=location.pathname.replace(/\/$/,'')||'/';state.portal=p==='/admin'||p.startsWith('/admin/')?'admin':p==='/advertiser'||p.startsWith('/advertiser/')?'advertiser':'user';const special=state.portal!=='user';if(state.portal==='advertiser'&&!advertiserLoginMode)return advertiserLanding();root.innerHTML=`<div class=auth><div class=authbox><div class=space><div><div class=authBrand>${state.portal==='advertiser'?'Tasko for Business':state.portal==='admin'?'Tasko Control Center':'Tasko'}</div><div class=muted>${state.portal==='advertiser'?'بوابة الشركات والمعلنين':state.portal==='admin'?'بوابة الإدارة والتشغيل':'Do Tasks. Earn More.'}</div></div><span class=pill>${state.portal==='advertiser'?'ADVERTISER':state.portal==='admin'?'ADMIN':'MEMBER'}</span></div><div class=tabs style="margin:24px 0"><button id=loginTab class=active onclick="authMode('login')">تسجيل الدخول</button>${special?'':`<button id=signupTab onclick="authMode('signup')">إنشاء حساب</button>`}</div><div id=authForm></div>${state.portal==='user'?`<div class="card" style="margin-top:16px;background:#f7fafc"><div class=space><div><b>للشركات والمعلنين</b><div class=muted>لديكم بوابة مستقلة.</div></div><button class="btn dark" onclick="location.href='/advertiser?from=user'">أعلن معنا</button></div></div>`:''}</div></div>`;authMode('login')}
async function openAdvertiserProfile(idv){try{const d=await api('/api/admin/advertiser/'+encodeURIComponent(idv)),a=d.advertiser,cs=d.campaigns||[];const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><div><h2>${esc(a.company||'المعلن')}</h2><small class=muted>${esc(a.id)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2 style="margin-top:16px"><div class=card><h3>معلومات الحساب</h3><div class=detailList>${[['المسؤول',a.name],['البريد',a.email],['الهاتف',a.phone],['المسمى الوظيفي',a.jobTitle],['نوع النشاط',a.businessType],['الدولة',a.country],['المدينة',a.city],['تاريخ الإنشاء',date(a.createdAt)],['الحالة',a.status],['التحقق',a.verification]].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></div><div class=card><h3>الحملات</h3><div class=grid2><div class=reportStat><small>الإجمالي</small><strong>${cs.length}</strong></div><div class=reportStat><small>النشطة</small><strong>${cs.filter(c=>c.status==='active').length}</strong></div><div class=reportStat><small>قيد المراجعة</small><strong>${cs.filter(c=>c.status==='pending').length}</strong></div><div class=reportStat><small>الإنفاق</small><strong>${fmt(cs.reduce((n,c)=>n+Number(c.results?.spent||0),0))} JOD</strong></div></div></div></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}}


