function adminProfilePage(){const u=state.user||{};return `<h1>${state.user?.role==='owner'?'Owner Account':'Admin Account'}</h1><p class=subtitle>Personal and security information for the current administrative account.</p><div class=grid2 section><div class=card><h2>${esc(u.name||'Tasko Admin')}</h2><div class=detailList>${[['Account ID',u.id],['Name',u.name],['Email',u.email],['Phone',u.phone],['Role',u.role],['Status',u.accountState],['Created',date(u.createdAt)],['Last login',date(u.lastLogin)]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></div><div class=card><h2>Security</h2><div class=notice>4-digit confirmation code is required for sensitive administrative operations. The code is never displayed here.</div><div class=taskMeta style="margin-top:14px">${(u.permissions||[]).map(p=>`<span class=pill>${esc(p)}</span>`).join('')}</div></div></div>`}

function adminRender(){let c;if(state.view==='dashboard')c=adminDashboard();else if(state.view==='profile')c=adminProfilePage();else if(state.view==='users')c=usersPage();else if(state.view==='admins')c=adminsPage();else if(state.view==='advertisers')c=adminAdvertisers();else if(state.view==='campaigns')c=campaignsPage();else if(state.view==='tasks')c=adminTasks();else if(state.view==='withdrawals')c=withdrawalsPage();else if(state.view==='support')c=adminSupport();else if(state.view==='fraud')c=fraudPage();else if(state.view==='reports')c=reportsPage();else if(state.view==='activities')c=activitiesPage();else if(state.view==='audit')c=auditPage();else if(state.view==='settings')c=settingsPage();else if(state.view==='packagesAdmin')c=packagesAdminPage();else if(state.view==='rewardsAdmin')c=rewardsAdminPage();else if(state.view==='sandbox')c=sandboxPage();else c=previewPage();layout(c)}


async function loadSettings(){const d=await api('/api/admin/settings');renderEmergency(d.settings)}
function renderEmergency(x){const item=(id,label,on)=>`<div class="controlRow"><div><b>${label}</b><div class="muted">${on?'Enabled':'Disabled'}</div></div><button class="btn ${on?'danger':'secondary'}" onclick="changeEmergency('${id}',${on?'false':'true'})">${on?'Disable':'Enable'}</button></div>`;$('#emergencyPanel').innerHTML=`<div class="emergencyBox"><div class="space"><div><b>${x.emergencyMode?'🔴 Emergency mode is active':'🟢 Normal operating mode'}</b><div class=muted>${esc(x.emergencyReason||'No emergency reason')}</div></div><span class="pill ${x.emergencyMode?'red':'green'}">${x.emergencyMode?'EMERGENCY':'OPERATIONAL'}</span></div><div class="controlList">${item('registrationsOpen','Registration',!!x.registrationsOpen)}${item('tasksOpen','Tasks',!!x.tasksOpen)}${item('withdrawalsOpen','Withdrawals',!!x.withdrawalsOpen)}${item('maintenance','Maintenance',!!x.maintenance)}</div><div class=field><label>Emergency reason</label><input id=ereason class=input value="${esc(x.emergencyReason||'')}" placeholder="Reason (optional)"></div></div>`}

async function doEmergencyChange(key,value){try{const confirm=$('#emCode')?.value||'';const reason=$('#ereason')?.value||'';const payload={confirm,reason};payload[key]=value;const d=await api('/api/admin/emergency',{method:'POST',body:JSON.stringify(payload)});$('#emModal')?.remove();toast('Platform status updated');renderEmergency(d.settings)}catch(e){toast(e.message)}}

function fraudPage(){return `<h1>Fraud & Violations</h1><p class=subtitle>Search any user, record a violation, then manage the action and history.</p><div class=card><div class=searchRow"><input id=fuid class=input placeholder="User ID / email / name"><input id=fr class=input placeholder="Violation reason"><select id=fs class=input><option value="minor">Minor</option><option value="serious">Serious</option></select><button class=btn onclick="addFraud()">Record violation</button></div></div><div id=fBox class=section>Loading...</div>`}
async function addFraud(){const q=$('#fuid')?.value?.trim();if(!q)return toast('Enter a user ID, email or name');try{const d=await api('/api/admin/users?q='+encodeURIComponent(q));const u=d.users?.[0];if(!u)return toast('User not found');const reason=$('#fr').value.trim();if(!reason)return toast('Enter the violation reason');const code=prompt('4-digit security code');if(code===null)return;await api('/api/admin/fraud',{method:'POST',body:JSON.stringify({userId:u.id,reason,severity:$('#fs').value,confirm:code})});toast('Violation recorded');loadFraud()}catch(e){toast(e.message)}}
async function loadFraud(){try{const q=$('#fuid')?.value||'';const d=await api('/api/admin/fraud?q='+encodeURIComponent(q));$('#fBox').innerHTML=d.violations.map(v=>`<div class="card" style="margin:9px 0"><div class=space><div><b>${esc(v.user?.name||v.userId)}</b><small style="display:block" class=muted>${esc(v.user?.email||v.userId)} · ${esc(v.referenceId||v.id)}</small></div><span class="pill ${v.severity==='serious'?'red':'gold'}">${esc(v.severity)}</span></div><p>${esc(v.reason||'—')}</p><div class=taskMeta><span class=pill>Status: ${esc(v.status||'open')}</span><span class=pill>Action: ${esc(v.actionTaken||'warning')}</span><span class=pill>${date(v.createdAt)}</span></div><div class=row><button class="btn secondary" onclick="fraudAction('${v.id}','warning')">Warning</button><button class="btn secondary" onclick="fraudAction('${v.id}','restrict')">Restrict</button><button class="btn secondary" onclick="fraudAction('${v.id}','suspend')">Suspend</button><button class="btn danger" onclick="fraudAction('${v.id}','ban')">Ban</button><button class="btn ghost" onclick="fraudAction('${v.id}','clear')">Clear</button><button class="btn ghost" onclick="fraudAction('${v.id}','unban')">Unban</button></div></div>`).join('')||'<div class="card empty">No violations found.</div>'}catch(e){toast(e.message)}}
async function fraudAction(idv,action){const code=prompt('4-digit security code');if(code===null)return;try{await api('/api/admin/fraud/action',{method:'POST',body:JSON.stringify({id:idv,action,confirm:code})});toast('Violation action updated');loadFraud()}catch(e){toast(e.message)}}

function activitiesPage(){return `<h1>سجل العمليات</h1><p class=subtitle>Human-readable operational history with filters and pagination.</p><div class=card><div class=searchRow><input id=actq class=input placeholder="Search reference, user or operation"><select id=acttype class=input><option value="">All operations</option><option value="task_attempt">Task attempts</option><option value="withdrawal">Withdrawals</option><option value="redemption">Reward redemptions</option><option value="transaction">Financial transactions</option><option value="campaign">Campaigns</option></select><select id=actdays class=input><option value="1">Last day</option><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option><option value="365">Last year</option><option value="0">All</option></select><button class="btn secondary" onclick="loadActivities()">Refresh</button></div></div><div id=actBox class=section>Loading...</div>`}
async function loadActivities(){const q=$('#actq')?.value||'',type=$('#acttype')?.value||'',days=$('#actdays')?.value||30;const d=await api('/api/admin/activities?q='+encodeURIComponent(q)+'&type='+encodeURIComponent(type)+'&days='+encodeURIComponent(days)+'&page=1&size=50');$('#actBox').innerHTML=`<div class=card><div class=space><h2>Activity log</h2><span class=pill>${fmt(d.total)} operations</span></div><div class=tableWrap style="margin-top:12px"><table class=table><tr><th>Time</th><th>Operation</th><th>Reference</th><th>User / target</th><th>Status</th><th>Details</th></tr>${d.items.map(x=>`<tr><td>${date(x.at||x.createdAt||x.startedAt)}</td><td><b>${esc(x.humanType||x.activityType||'Activity')}</b></td><td><code>${esc(x.referenceId||x.id||'—')}</code></td><td>${esc(x.userId||x.advertiserId||x.id||'—')}</td><td>${esc(x.status||'—')}</td><td><div class=detailList>${Object.entries(x.humanDetails||{}).filter(([k,v])=>v!==''&&v!==undefined).map(([k,v])=>`<div class=detailItem><small>${esc(k)}</small><b>${esc(String(v))}</b></div>`).join('')||'<span class=muted>—</span>'}</div></td></tr>`).join('')||'<tr><td colspan=6 class=empty>No operations match the current filters.</td></tr>'}</table></div></div>`}


async function loadActionCenter(){try{const d=await api('/api/admin/summary');const n=(d.pendingTasks||0)+(d.pendingWithdrawals||0)+(d.tickets||0);let e=$('#actionCenter');if(!n){e?.remove();return}if(!e){e=document.createElement('div');e.id='actionCenter';e.className='actionCenter';document.body.appendChild(e)}const target=d.pendingTasks?'tasks':d.pendingWithdrawals?'withdrawals':d.tickets?'support':'dashboard';e.innerHTML=`<button type="button" onclick="go('${target}')">⚠️ ${n} عناصر تحتاج إجراء</button>`}catch{document.getElementById('actionCenter')?.remove()}}






async function startCampaignTask(c){try{const d=await api('/api/campaign/start',{method:'POST',body:JSON.stringify({campaignId:c.id})});const box=$('#campaignExecMsg');if(!box)return;box.innerHTML=`<div class=notice>Task started. Reference: <b>${esc(d.attempt.referenceId)}</b></div><button class="btn" style="margin-top:10px" onclick="submitCampaignTask('${esc(d.attempt.id)}')">Submit completed task</button>`}catch(e){toast(e.message)}}
async function submitCampaignTask(idv){try{const d=await api('/api/campaign/submit',{method:'POST',body:JSON.stringify({attemptId:idv})});$('#campaignExecMsg').innerHTML=`<div class="notice ${d.attempt.status==='approved'?'':'warning'}">${d.attempt.status==='approved'?'Task approved and reward credited.':'Task submitted for review.'}</div>`;state.user=d.user;setTimeout(()=>{document.querySelector('.modalBack')?.remove();render()},900)}catch(e){toast(e.message)}}

