function v17LangDefault(){if(localStorage.getItem('taskoLang'))return localStorage.getItem('taskoLang');const l=(navigator.language||'ar').toLowerCase();return l.startsWith('ar')?'ar':'en'}
function v17AdminNav(){return [['dashboard','⌂ لوحة التحكم'],['users','👥 المستخدمون'],['admins','🛡️ إدارة الأدمن'],['advertisers','📣 المعلنون'],['campaigns','📊 الحملات'],['tasks','✓ المهام'],['withdrawals','💳 السحوبات'],['support','💬 الدعم والتذاكر'],['fraud','⚠️ المخالفات'],['reports','▥ التقارير والتحليلات'],['activities','⌁ سجل العمليات'],['audit','◷ سجل التدقيق'],['settings','⚙ مركز التحكم'],['packagesAdmin','💳 إدارة الباقات'],['rewardsAdmin','🎁 إدارة المكافآت'],['sandbox','🧪 Test Center'],['systemHealth','🩺 System Health'],['errors','🧯 Error Center'],['sessions','🔐 Sessions'],['backup','💾 Backup / Restore'],['featureFlags','🚦 Feature Flags'],['workflow','⚡ Action Center'],['preview','👁 Preview as User']]}

async function v17ActionCenter(){try{const d=await api('/api/admin/workflow/summary?size=5');const n=Number(d.needsAction?.total||0);let e=$('#actionCenter');if(!n){e?.remove();return}if(!e){e=document.createElement('div');e.id='actionCenter';e.className='actionCenter';document.body.appendChild(e)}e.innerHTML=`<button type="button" onclick="go('workflow')">⚠️ ${n} عناصر تحتاج إجراء</button>`}catch{document.getElementById('actionCenter')?.remove()}}

async function v17ErrorsPage(){const d=await api('/api/admin/errors?size=50');return `<h1>Error Center</h1><p class=subtitle>الأخطاء التقنية تبقى داخل الإدارة مع Error ID. المستخدم يحصل على رسالة مفهومة فقط.</p><div class=card>${d.items.map(e=>`<div class=card style="margin:10px 0"><div class=space><b>${esc(e.code||e.id)}</b><span class=pill>${e.resolved?'Resolved':'Open'}</span></div><p>${esc(e.message)}</p><small class=muted>${date(e.at)}</small>${!e.resolved?`<button class="btn secondary" style="margin-top:10px" onclick="v17ResolveError('${esc(e.id)}')">Mark resolved</button>`:''}</div>`).join('')||'<div class=empty>لا توجد أخطاء.</div>'}</div>`}
async function v17ResolveError(idv){const c=prompt('رمز التأكيد');if(c===null)return;try{await api('/api/admin/errors/resolve',{method:'POST',body:JSON.stringify({id:idv,confirm:c})});toast('تم حل الخطأ');render()}catch(e){toast(e.message)}}

async function v17LogoutAll(){const c=prompt('أدخل كود التأكيد مرتين: XXXX ثم XXXX');if(c===null)return;const c2=prompt('أعد إدخال الكود');if(c2===null)return;try{await api('/api/admin/logout-all',{method:'POST',body:JSON.stringify({confirm:c,confirm2:c2})});toast('تم تسجيل الخروج من كل الجلسات');render()}catch(e){toast(e.message)}}
async function v17BackupPage(){return `<h1>Backup / Restore</h1><p class=subtitle>Owner-only. النسخ الاحتياطية تحفظ حالة المنصة لاسترجاعها عند الحاجة.</p><div class=card><button class=btn onclick="v17Backup()">إنشاء Backup</button><p class=muted style="margin-top:10px">الاسترجاع عملية عالية الخطورة وتتطلب تأكيداً مزدوجاً.</p></div>`}
async function v17Backup(){const c=prompt('رمز التأكيد');if(c===null)return;const c2=prompt('أعد إدخال الرمز');if(c2===null)return;try{const d=await api('/api/admin/backup',{method:'POST',body:JSON.stringify({confirm:c,confirm2:c2})});toast('تم إنشاء النسخة '+d.backup.id)}catch(e){toast(e.message)}}
async function v17FlagsPage(){const d=await api('/api/admin/feature-flags');const rows=Object.entries(d.flags||{});return `<h1>Feature Flags</h1><p class=subtitle>تبديل الميزات فقط عندما تحتاج فعلاً إلى تشغيل/إيقاف ميزة.</p><div class=card>${rows.map(([k,v])=>`<div class=controlRow><b>${esc(k)}</b><button class="btn ${v?'danger':'secondary'}" onclick="v17Flag('${esc(k)}',${!v})">${v?'Disable':'Enable'}</button></div>`).join('')||'<div class=empty>لا توجد Feature Flags.</div>'}</div>`}
async function v17Flag(k,en){const c=prompt('رمز التأكيد');if(c===null)return;try{await api('/api/admin/feature-flags',{method:'POST',body:JSON.stringify({key:k,enabled:en,confirm:c})});render()}catch(e){toast(e.message)}}
async function v17WorkflowPage(){const d=await api('/api/admin/workflow/summary?size=20');return `<h1>Action Center</h1><p class=subtitle>كل ما يحتاج مراجعة أو موافقة يظهر أولاً.</p><div class=grid4>${Object.entries(d.needsAction).filter(([k])=>k!=='total').map(([k,v])=>`<div class=card metric"><span class=kpi>${esc(k)}</span><strong>${v}</strong></div>`).join('')}</div><div class=grid2 section><div class=card><h2>Campaigns needing action</h2>${d.campaigns.items.map(x=>`<div class=controlRow><span>${esc(x.name)}</span><b>${esc(x.status)}</b></div>`).join('')||'<div class=empty>لا شيء.</div>'}</div><div class=card><h2>Withdrawals needing action</h2>${d.withdrawals.items.map(x=>`<div class=controlRow><span>${esc(x.referenceId)}</span><b>${esc(x.status)}</b></div>`).join('')||'<div class=empty>لا شيء.</div>'}</div></div>`}
function v17AdminRender(){let c;if(state.view==='systemHealth')c=v17HealthPage();else if(state.view==='errors')c=v17ErrorsPage();else if(state.view==='sessions')c=v17SessionsPage();else if(state.view==='backup')c=v17BackupPage();else if(state.view==='featureFlags')c=v17FlagsPage();else if(state.view==='workflow')c=v17WorkflowPage();else {return adminRenderBase()}return Promise.resolve(c).then(x=>v17Layout(x))}
function adminRenderBase(){let c;if(state.view==='dashboard')c=adminDashboard();else if(state.view==='profile')c=adminProfilePage();else if(state.view==='users')c=usersPage();else if(state.view==='admins')c=adminsPage();else if(state.view==='advertisers')c=adminAdvertisers();else if(state.view==='campaigns')c=campaignsPage();else if(state.view==='tasks')c=adminTasks();else if(state.view==='withdrawals')c=withdrawalsPage();else if(state.view==='support')c=adminSupport();else if(state.view==='fraud')c=fraudPage();else if(state.view==='reports')c=reportsPage();else if(state.view==='activities')c=activitiesPage();else if(state.view==='audit')c=auditPage();else if(state.view==='settings')c=settingsPage();else if(state.view==='packagesAdmin')c=packagesAdminPage();else if(state.view==='rewardsAdmin')c=rewardsAdminPage();else if(state.view==='sandbox')c=sandboxPage();else c=previewPage();return Promise.resolve(c).then(x=>v17Layout(x))}


function routeForView(v){if(state.preview)return v==='dashboard'?'/preview':`/preview/${v}`;if(state.portal==='admin')return v==='dashboard'?'/admin':`/admin/${v}`;if(state.portal==='advertiser')return v==='dashboard'?'/advertiser':`/advertiser/${v}`;return v==='dashboard'?'/dashboard':`/${v}`}
