async function loadW(){try{const d=await api('/api/admin/withdrawals?q='+encodeURIComponent($('#wq')?.value||'')+'&status='+encodeURIComponent($('#ws')?.value||''));$('#wBox').innerHTML=(d.withdrawals||[]).map(w=>`<div class="card" style="margin:10px 0"><div class=space><div><h3>${esc(w.referenceId)}</h3><small class=muted>User: ${esc(w.userId)} · ${esc(w.method||'cliq')}</small></div><span class="pill ${w.status==='rejected'?'red':w.status==='approved'?'green':'gold'}">${esc(w.status)}</span></div><div class=grid3 style="margin-top:12px"><div class=detailItem><small>المبلغ</small><b>${fmt(w.amount)} JOD</b></div><div class=detailItem><small>الرسوم</small><b>${fmt(w.fee||0)} JOD</b></div><div class=detailItem><small>الإجمالي</small><b>${fmt(w.total||w.amount)} JOD</b></div></div>${w.status==='pending'?`<div class=row style="margin-top:12px"><button class="btn secondary" onclick="processOp('withdrawal','${esc(w.id)}','processing')">بدء المعالجة</button><button class=btn onclick="processOp('withdrawal','${esc(w.id)}','approve')">إكمال السحب</button><button class="btn danger" onclick="processOp('withdrawal','${esc(w.id)}','reject')">رفض</button></div>`:w.status==='processing'?`<div class=row style="margin-top:12px"><button class=btn onclick="processOp('withdrawal','${esc(w.id)}','approve')">إكمال السحب</button><button class="btn danger" onclick="processOp('withdrawal','${esc(w.id)}','reject')">رفض وإرجاع الرصيد</button></div>`:`<div class=notice style="margin-top:12px">تمت المعالجة بواسطة ${esc(w.processedBy||'—')} · ${esc(w.reason||'بدون سبب')}</div>`}</div>`).join('')||'<div class="card empty">لا توجد عمليات.</div>'}catch(e){toast(e.message)}}
function openCampaignDetails(c){if(state.portal!=='user'){const m=document.createElement('div');m.className='modalBack';const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;const conv=Number(c.results?.conversions||0),clicks=Number(c.results?.clicks||0);m.innerHTML=`<div class=modal><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId||c.id)} · ${esc(c.status||'')}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid4 section><div class=card metric><span class=kpi>Budget</span><strong>${fmt(c.budget)} JOD</strong></div><div class=card metric><span class=kpi>Spent</span><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=card metric><span class=kpi>Clicks</span><strong>${fmt(clicks)}</strong></div><div class=card metric><span class=kpi>Conversions</span><strong>${fmt(conv)}</strong></div></div><div class=card section><h3>Campaign progress</h3><div class=progress><span style="width:${pct}%"></span></div><div class=space style="margin-top:8px"><span>${pct}% spent</span><span>${clicks?Math.round(conv/clicks*10000)/100:0}% conversion rate</span></div><div class=chartBars>${[clicks,conv,Number(c.results?.spent||0),Number(c.budget||0)].map((v,i)=>`<div class=bar title="${v}" style="height:${Math.max(8,Math.min(100,(v/Math.max(1,Number(c.budget||1)))*100))}%"></div>`).join('')}</div></div><div class=grid2 section><div class=card><h3>Financials</h3><div class=detailList><div class=detailItem><small>Total budget</small><b>${fmt(c.budget)} JOD</b></div><div class=detailItem><small>Spent</small><b>${fmt(c.results?.spent)} JOD</b></div><div class=detailItem><small>Remaining</small><b>${fmt(Math.max(0,Number(c.budget||0)-Number(c.results?.spent||0)))} JOD</b></div><div class=detailItem><small>Reward per participant</small><b>${fmt(c.rewardPerPerson)} Points</b></div></div></div><div class=card><h3>Workflow</h3><div class=detailList><div class=detailItem><small>Status</small><b>${esc(c.status||'—')}</b></div><div class=detailItem><small>Verification</small><b>${esc(c.verification||'—')}</b></div><div class=detailItem><small>Reference</small><b>${esc(c.referenceId||c.id)}</b></div></div></div></div></div>`;document.body.appendChild(m);return}const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:90vh;overflow:auto"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>Tasko Task · ${esc(c.referenceId||c.id)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2 section><div class=card><h3>تفاصيل المهمة</h3><div class=detailList>${[['الوصف',c.description||'—'],['الشروط',c.conditions||'—'],['المكافأة',`${fmt(c.rewardPerPerson||0)} Points`],['XP',c.xp||0],['المدة المتوقعة',c.estimatedMinutes?`${c.estimatedMinutes} min`:'—'],['الفرص لكل مستخدم',c.maxPerUser||1]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(String(x[1]))}</b></div>`).join('')}</div></div><div class=card><h3>تنفيذ المهمة</h3><p class=muted>ابدأ المهمة ثم نفّذ الخطوات المطلوبة وأرسلها للمراجعة.</p>${c.contentUrl?`<a class="btn secondary" href="${esc(c.contentUrl)}" target="_blank" rel="noopener">فتح الرابط</a>`:''}<div class=row style="margin-top:12px"><button class=btn onclick='startCampaignTask(${JSON.stringify(c).replace(/"/g,'&quot;')})'>Start Task</button></div><div id=campaignExecMsg style="margin-top:12px"></div></div></div></div>`;document.body.appendChild(m)}
function v17CodeModal(title,extra=''){return new Promise(resolve=>{const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-width:460px"><h2>${esc(title)}</h2>${extra?`<p class=muted>${esc(extra)}</p>`:''}<div class=field><label>رمز التأكيد المكوّن من 4 أرقام</label><input id=v17pin class=input inputmode=numeric maxlength=4 autocomplete=one-time-code></div><div class=row><button class=btn id=v17ok>تأكيد</button><button class="btn ghost" id=v17cancel>إلغاء</button></div></div>`;document.body.appendChild(m);m.querySelector('#v17ok').onclick=()=>{const v=m.querySelector('#v17pin').value.trim();if(!/^\d{4}$/.test(v))return toast('أدخل رمزاً من 4 أرقام');m.remove();resolve(v)};m.querySelector('#v17cancel').onclick=()=>{m.remove();resolve(null)};m.querySelector('#v17pin').focus()})}
async function processOp(kind,idv,decision){const pin=await v17CodeModal(decision==='reject'?'تأكيد رفض العملية':decision==='processing'?'بدء معالجة السحب':'تأكيد العملية');if(!pin)return;let reason='';if(decision==='reject'){reason=prompt('سبب الرفض')||''}try{await api('/api/admin/verify',{method:'POST',body:JSON.stringify({kind,id:idv,decision,confirm:pin,reason})});toast('تمت معالجة العملية');render()}catch(e){toast(e.message)}}
async function changeEmergency(key,value){const pin=await v17CodeModal('تأكيد تغيير حالة المنصة',`سيتم ${value?'تفعيل':'إيقاف'} ${key}.`);if(!pin)return;try{await api('/api/admin/emergency',{method:'POST',body:JSON.stringify({[key]:value,reason:$('#ereason')?.value||'',confirm:pin})});toast('تم تحديث حالة المنصة');render()}catch(e){toast(e.message)}}


