function translateUI(v){return String(v??'')}
function v18Landing(){return `<div class="publicShell"><header class="publicTop"><div class="brand">Task<span>o</span></div><nav><a href="/about">عن Tasko</a><a href="/how-it-works">كيف تعمل</a><a href="/for-users">للمستخدمين</a><a href="/for-business">للشركات</a><a href="/faq">FAQ</a><a href="/contact">تواصل</a></nav><div class="row"><a class="btn ghost" href="/login/user">دخول المستخدم</a><a class="btn" href="/signup">إنشاء حساب</a></div></header><main><section class="publicHero"><div><span class="pill blue">Tasko</span><h1>نفّذ المهام. اكسب. وتابع تقدمك.</h1><p>منصة مهام ومكافآت للمستخدمين، وحملات ونتائج للشركات والمعلنين.</p><div class="row"><a class="btn" href="/login/user">ابدأ كمستخدم</a><a class="btn secondary" href="/for-business">Tasko for Business</a></div></div><div class="publicVisual"><div class="card"><b>Tasks</b><strong>Rewards</strong><span>Points · XP · Cash</span></div><div class="card"><b>For Business</b><strong>Campaigns</strong><span>Budget · Analytics · Results</span></div></div></section><section class="publicGrid"><a class="card" href="/about"><h2>عن Tasko</h2><p>ما هي المنصة وكيف تعمل.</p></a><a class="card" href="/how-it-works"><h2>كيف تعمل</h2><p>الخطوات من التسجيل حتى المكافأة.</p></a><a class="card" href="/for-users"><h2>للمستخدمين</h2><p>المهام، النقاط، XP، السحب والإحالات.</p></a><a class="card" href="/for-business"><h2>للشركات والمعلنين</h2><p>إنشاء الحملات وقياس النتائج.</p></a><a class="card" href="/privacy"><h2>Privacy</h2><p>الخصوصية واستخدام البيانات.</p></a><a class="card" href="/terms"><h2>Terms</h2><p>الشروط وFair Play.</p></a></section></main><footer>Tasko · <a href="/privacy">Privacy</a> · <a href="/terms">Terms</a> · <a href="/contact">Contact</a></footer></div>`}
function v18PublicPage(kind){const data={
 about:['عن Tasko','Tasko منصة تربط المستخدمين بمهام قابلة للتنفيذ ومكافآت، وتوفر للشركات والمعلنين أدوات لإنشاء الحملات ومتابعة النتائج.'],
 'how-it-works':['كيف تعمل Tasko','أنشئ حساباً، اختر مهمة مؤهلة، نفّذها وأرسلها عند الحاجة للمراجعة. عند اعتماد المهمة تُحدّث Points وXP وفق قواعدها. الحملات المنشورة تظهر كمهمات فعلية للمستخدمين المؤهلين.'],
 'for-users':['Tasko للمستخدمين','تصفح المهام المتاحة حسب الباقة والمستوى والاستهداف. تابع Points وCash وXP، الإحالات، السحوبات والنشاط الأخير.'],
 'for-business':['Tasko for Business','قدّم طلبك، وبعد اعتماد الحساب سجّل دخول المعلن. أنشئ حملة، راجعها، اضبط إعدادات Free وPlus وPremium بشكل منفصل ثم انشرها.'],
 faq:['FAQ','كيف أسحب؟ حسب طرق السحب المتاحة في حسابك. كيف تتحدد المهام؟ حسب الباقة والمستوى والشروط والاستهداف. هل الحسابات الإدارية تستخدم Google؟ لا؛ دخول الإدارة منفصل ومباشر.'],
 contact:['تواصل','للاستفسارات والدعم استخدم مركز الدعم بعد تسجيل الدخول، أو نموذج التواصل المتاح في هذه الصفحة عند ربط قناة الدعم.'],
 privacy:['Privacy','نحتفظ بالبيانات اللازمة لتشغيل الحسابات والمهام والمكافآت والأمان، ونستخدم سجلات التدقيق والأنظمة الأمنية لحماية المنصة.'],
 terms:['Terms & Fair Play','يجب إدخال معلومات حقيقية وعدم إساءة استخدام الإحالات أو المهام أو السحب. المخالفات قد تؤدي إلى تقييد أو تعليق أو إنهاء الحساب وفق الشروط والأدلة المتاحة.']
 }[kind]||['Tasko','صفحة عامة غير معروفة.'];return `<div class="publicShell"><header class="publicTop"><div class="brand">Task<span>o</span></div><div class="row"><a class="btn ghost" href="/">الرئيسية</a>${kind==='for-business'?'<a class="btn ghost" href="/login/user">العودة لتسجيل المستخدم</a>':''}</div></header><main><div class="publicDoc card"><span class="pill blue">Tasko</span><h1>${esc(data[0])}</h1><p>${esc(data[1])}</p><div class="row" style="margin-top:22px"><a class="btn" href="/login/user">دخول المستخدم</a><a class="btn secondary" href="/for-business">للشركات</a></div></div></main></div>`}
function v18LoginPage(portal){const labels={user:['تسجيل دخول المستخدم','User Login'],advertiser:['تسجيل دخول المعلن','Advertiser Login'],admin:['تسجيل دخول الإدارة','Admin Login'],owner:['تسجيل دخول Owner','Owner Login']};const x=labels[portal]||labels.user;state.portal=portal;return `<div class="auth"><div class="authbox"><div class="space"><div><div class="authBrand">Task<span style="color:#102844">o</span></div><div class="muted">${x[0]}</div></div><span class="pill">${x[1]}</span></div><div class="notice" style="margin-top:18px">${portal==='user'?'بوابة المستخدمين للمهام والمكافآت.':portal==='advertiser'?'بوابة الحسابات الإعلانية المعتمدة.':'حسابات الإدارة تُنشأ من Owner وتستخدم دخولاً مباشراً.'}</div><div class="field"><label>Email</label><input id=email class=input type=email autocomplete=email></div><div class="field" style="position:relative"><label>Password</label><input id=password class=input type=password autocomplete=current-password>${eye('password')}</div><div id=v18Turnstile class="section"></div><label class=checkRow><input id=rememberDevice type=checkbox> تذكرني</label><button class=btn style="width:100%;margin-top:8px" onclick="v18Login('${portal}')">تسجيل الدخول</button>${portal==='user'?'<div class="row" style="margin-top:12px"><button class="btn secondary" onclick="v18Social(\'google\')">Continue with Google</button><button class="btn secondary" onclick="v18Social(\'facebook\')">Continue with Facebook</button></div><div class="muted" style="font-size:12px;margin-top:10px">تسجيل الدخول الاجتماعي يحتاج مفاتيح المزود في Render.</div>':''}<div class="row" style="margin-top:18px"><a href="/" class="btn ghost">الرئيسية</a>${portal==='user'?'<a href="/signup" class="btn ghost">إنشاء حساب</a>':''}${portal==='advertiser'?'<a href="/for-business" class="btn ghost">Tasko for Business</a>':''}</div></div></div>`}
async function v18Login(portal){try{const path=portal==='owner'?'/api/login/owner':'/api/login/'+portal;const d=await api(path,{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value,turnstileToken:window.__turnstileToken||''})});state.token=d.token;state.user=d.user;sessionStorage.setItem('taskoToken',d.token);localStorage.setItem('taskoPortal',portal);location.href=portal==='owner'||portal==='admin'?'/admin':portal==='advertiser'?'/advertiser':'/dashboard'}catch(e){toast(e.message)}}
function v18Social(provider,mode='login'){location.href='/api/oauth/'+provider+'/start?returnTo='+encodeURIComponent(mode==='signup'?'/settings':'/dashboard')+'&mode='+encodeURIComponent(mode)}
function v18Signup(){auth();}
function v18Layout(content){const admin=isAdmin()&&!state.preview;const items=admin?v17AdminNav():state.portal==='advertiser'?[['dashboard','⌂ لوحة المعلن'],['campaigns','📊 حملاتي'],['account','◉ معلومات الحساب']]:[['dashboard','⌂ الرئيسية'],['tasks','✓ المهام'],['packages','◇ الباقات'],['rewards','🎁 متجر المكافآت'],['wallet','💳 المحفظة'],['referrals','↗ الإحالات'],['notifications','🔔 الإشعارات'],['support','💬 الدعم'],['fairplay','✓ Fair Play'],['activity','⌁ نشاطي'],['profile','◉ الملف الشخصي']];const ini=(state.user?.name||state.user?.company||'T')[0].toUpperCase();root.innerHTML=`<div class="app ${state.user?.package==='Premium'?'premiumTheme':''}"><header class=top><button class="desktopCollapse btn ghost" onclick="state.desktopSidebarCollapsed=!state.desktopSidebarCollapsed;render()">☰</button><div class=row><button class=mobileMenu type=button aria-label="فتح القائمة" onclick="toggleMobileMenu()">☰</button><div class=brand>Task<span>o</span></div></div><div class=topUser><button class="avatar avatarBtn" onclick="go(state.portal==='advertiser'?'account':'profile')">${esc(ini)}</button><button class=accountHeaderBtn onclick="go(state.portal==='advertiser'?'account':'profile')">${esc(state.user?.name||state.user?.company||'')}</button><button class="btn ghost" onclick="logout()">خروج</button></div></header><div class="shell ${state.desktopSidebarCollapsed?'sidebarCollapsed':''} ${state.mobileMenuOpen?'open':''}"><aside><div style="padding:4px 10px 18px"><small>${admin?'CONTROL CENTER':state.portal==='advertiser'?'ADVERTISER PORTAL':'MEMBER AREA'}</small><b style="display:block;font-size:17px">${esc(state.user?.name||state.user?.company||'')}</b></div>${nav(items)}</aside><main class=main>${content}</main></div></div>`;afterLayout();if(admin)v17ActionCenter();else document.getElementById('actionCenter')?.remove()}
async function v18ActivityPage(){const d=await api('/api/user/activity');return `<div class="space"><div><h1>نشاطي</h1><p class=subtitle>النشاط المفيد لآخر 14 يوماً فقط في واجهة المستخدم.</p></div><span class=pill>${d.items.length} نشاط</span></div><div class="card activityTimeline">${d.items.map(x=>`<div class="activityItem"><div><b>${esc(x.description)}</b><small>${date(x.at)} · ${esc(x.referenceId)}</small></div><div class="activityValue">${x.points?`+${fmt(x.points)} Points `:''}${x.xp?`+${fmt(x.xp)} XP `:''}${x.cash?` ${fmt(x.cash)} JOD`:''}</div></div>`).join('')||'<div class=empty>لا يوجد نشاط مفيد خلال آخر 14 يوماً.</div>'}</div>`}
async function v18HealthPage(){const d=await api('/api/admin/system-health');return `<div class=space><div><h1>System Health / Security & Integrity</h1><p class=subtitle>فحوص تلقائية مجدولة، سجل مشاكل مفتوحة ومحلولة، وفحص تكامل البيانات والمحركات الأساسية.</p></div><span class="pill ${d.summary?.critical?'red':d.summary?.open?'gold':'green'}">${d.summary?.open||0} مشاكل مفتوحة</span></div><div class=grid4>${[['Critical',d.summary?.critical||0],['High',d.summary?.high||0],['Medium',d.summary?.medium||0],['Low',d.summary?.low||0]].map(x=>`<div class=card metric><span class=kpi>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="card section"><div class=space><h2>آخر فحص</h2><span class=pill>${date(d.lastCheck?.at)}</span></div><div class=grid4 style="margin-top:12px">${Object.entries(d.lastCheck?.counts||{}).map(([k,v])=>`<div class=detailItem><small>${esc(k)}</small><b>${v}</b></div>`).join('')}</div></div><div class="card section"><h2>المشاكل</h2>${(d.issues||[]).map(x=>`<div class="controlRow"><div><b>${esc(x.problem)}</b><small class=muted style="display:block">${esc(x.referenceId)} · ${esc(x.location||'')} · أول ظهور ${date(x.firstSeenAt)} · آخر فحص ${date(x.lastCheckedAt)}</small></div><span class="pill ${x.severity==='Critical'?'red':x.severity==='High'?'gold':''}">${esc(x.severity)}</span></div>`).join('')||'<div class=empty>لا توجد مشاكل مكتشفة حالياً.</div>'}</div><div class="card section"><h2>Resolved history</h2>${(d.history||[]).slice(0,20).map(x=>`<div class=detailItem><small>${date(x.at)}</small><b>${esc(x.status)} · ${x.issues||0} issues</b></div>`).join('')}</div>`}
function v18CampaignPackageModal(c){const cfg=c.packageConfigs||{Free:{},Plus:{},Premium:{}};const levels=v18Levels();const body=['Free','Plus','Premium'].map(k=>{const z=cfg[k]||{};return `<div class="packageAdmin"><div class=space><h2>${k}</h2><label class=checkRow><input id=pc_${k}_eligible type=checkbox ${z.eligible?'checked':''}> مؤهل</label></div><div class=grid3><div class=field><label>Cash reward</label><input id=pc_${k}_cash class=input type=number step=.01 value="${Number(z.cashReward||0)}"></div><div class=field><label>Points</label><input id=pc_${k}_points class=input type=number value="${Number(z.points||0)}"></div><div class=field><label>XP</label><input id=pc_${k}_xp class=input type=number value="${Number(z.xp||0)}"></div><div class=field><label>Minimum Level</label><select id=pc_${k}_level class=input>${levels.map(l=>`<option value="${l[0]}" ${z.levelMinId===l[0]?'selected':''}>${l[1]}</option>`).join('')}</select></div><div class=field><label>Max per user</label><input id=pc_${k}_max class=input type=number value="${Number(z.maxPerUser||1)}"></div><div class=field><label>ظهور من (Jordan)</label><input id=pc_${k}_start class=input type=datetime-local value="${esc(z.startsAtJordan||'')}"></div><div class=field><label>ظهور حتى (Jordan)</label><input id=pc_${k}_end class=input type=datetime-local value="${esc(z.endsAtJordan||'')}"></div></div></div>`}).join('');const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="width:min(1100px,96vw)"><div class=space><div><h2>Campaign ↔ Package Configuration</h2><p class=muted>${esc(c.name)} · ${esc(c.referenceId||c.id)}</p></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div>${body}<div class="row" style="margin-top:16px"><button class=btn onclick="v18SaveCampaignPackages('${esc(c.id)}')">حفظ إعدادات الباقات</button><button class="btn secondary" onclick="v18PublishCampaign('${esc(c.id)}')">Publish</button></div></div>`;document.body.appendChild(m)}
function v18PackagePayload(){const o={};for(const k of ['Free','Plus','Premium'])o[k]={eligible:$('#pc_'+k+'_eligible').checked,cashReward:Number($('#pc_'+k+'_cash').value)||0,points:Number($('#pc_'+k+'_points').value)||0,xp:Number($('#pc_'+k+'_xp').value)||0,levelMinId:$('#pc_'+k+'_level').value,maxPerUser:Number($('#pc_'+k+'_max').value)||1,startsAtJordan:$('#pc_'+k+'_start').value||null,endsAtJordan:$('#pc_'+k+'_end').value||null};return o}
async function v18SaveCampaignPackages(idv){const pin=await v17CodeModal('تأكيد حفظ إعدادات الباقات');if(!pin)return;try{await api('/api/admin/campaign-package-config',{method:'POST',body:JSON.stringify({campaignId:idv,packages:v18PackagePayload(),confirm:pin})});toast('تم حفظ إعدادات Free / Plus / Premium');document.querySelector('.modalBack')?.remove();render()}catch(e){toast(e.message)}}
async function v18PublishCampaign(idv){const pin=await v17CodeModal('تأكيد نشر الحملة');if(!pin)return;try{await api('/api/admin/campaigns/publish',{method:'POST',body:JSON.stringify({id:idv,confirm:pin})});toast('تم نشر الحملة');document.querySelector('.modalBack')?.remove();render()}catch(e){toast(e.message)}}

async function v18AdvertiserCreateAccount(r){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><h2>Approve & Create Account</h2><p class=muted>أدخل البريد وكلمة المرور للحساب الجديد. يمكن تعديل البريد قبل الإنشاء.</p><div class=field><label>Company name</label><input id=advCompany class=input value="${esc(r.company||'')}"></div><div class=field><label>Responsible person</label><input id=advResponsible class=input value="${esc(r.contact||'')}"></div><div class=field><label>Email</label><input id=advEmail class=input type=email value="${esc(r.email||'')}"></div><div class=field><label>Password</label><input id=advPassword class=input type=password minlength=8></div><div class=field><label>Phone</label><input id=advPhone class=input value="${esc(r.phone||'')}"></div><div class=row><button class=btn onclick="v18CreateAdvertiser('${esc(r.id)}')">Approve & Create Account</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">Cancel</button></div></div>`;document.body.appendChild(m)}
async function v18CreateAdvertiser(idv){const pin=await v17CodeModal('تأكيد إنشاء حساب المعلن');if(!pin)return;try{await api('/api/admin/advertiser-request/create-account',{method:'POST',body:JSON.stringify({requestId:idv,company:$('#advCompany').value,responsibleName:$('#advResponsible').value,email:$('#advEmail').value,password:$('#advPassword').value,phone:$('#advPhone').value,approve:true,confirm:pin})});toast('تم إنشاء حساب المعلن');document.querySelector('.modalBack')?.remove();render()}catch(e){toast(e.message)}}
function v18PatchCampaignCardActions(){const old=window.openCampaignDetails;window.__v18OldOpenCampaignDetails=old;window.openCampaignDetails=v18OpenCampaign}
async function v18SocialConfig(){try{const d=await api('/api/auth/provider-config');return d}catch{return {google:false,facebook:false,turnstile:false}}}
function v18InitTurnstile(){if(!document.getElementById('v18Turnstile'))return;api('/api/auth/provider-config').then(d=>{if(!d.turnstile||!d.turnstile.siteKey)return;const sc=document.createElement('script');sc.src='https://challenges.cloudflare.com/turnstile/v0/api.js';sc.async=true;sc.defer=true;sc.onload=()=>{if(window.turnstile)window.turnstile.render('#v18Turnstile',{sitekey:d.turnstile.siteKey,callback:t=>window.__turnstileToken=t});};document.head.appendChild(sc)}).catch(()=>{})}
async function render(){
 const path=location.pathname.replace(/\/$/,'')||'/';
 if(!state.token){
   if(path==='/'||path==='')return root.innerHTML=v18Landing();
   if(path==='/signup')return auth();
   if(path==='/login'||path==='/login/user'){root.innerHTML=v18LoginPage('user');setTimeout(v18InitTurnstile,0);return}
   if(path==='/login/advertiser'){root.innerHTML=v18LoginPage('advertiser');setTimeout(v18InitTurnstile,0);return}
   if(path==='/login/admin'){root.innerHTML=v18LoginPage('admin');setTimeout(v18InitTurnstile,0);return}
   if(path==='/login/owner'){root.innerHTML=v18LoginPage('owner');setTimeout(v18InitTurnstile,0);return}
   if(['/about','/how-it-works','/for-users','/for-business','/faq','/contact','/privacy','/terms'].includes(path))return root.innerHTML=v18PublicPage(path.slice(1));
   if(path==='/advertiser')return root.innerHTML=v18PublicPage('for-business');
   return root.innerHTML=v18Landing();
 }
 try{state.user=(await api('/api/me')).user}catch{sessionStorage.removeItem('taskoToken');localStorage.removeItem('taskoToken');state.token=null;return render()}
 state.view=pathView();
 if(state.preview)return previewUserRender();
 if(state.user.role==='advertiser'){state.portal='advertiser';return advertiserRender();}
 if(isAdmin()){state.portal='admin';const need=permFor(state.view);if(state.user.role!=='owner'&&need&&!state.user.permissions?.includes(need)){history.replaceState({},'','/admin');state.view='dashboard'}return v17AdminRender();}
 state.portal='user';if(state.view==='activity')return v18Layout(await v18ActivityPage());return userRender();
}
function go(v){closeMobileMenu();state.view=v;const p=routeForView(v);if(location.pathname!==p)history.pushState({view:v},'',p);render()}
function closeMobileMenu(){state.mobileMenuOpen=false;document.querySelector('.shell')?.classList.remove('open')}
function toggleMobileMenu(){state.mobileMenuOpen=!state.mobileMenuOpen;document.querySelector('.shell')?.classList.toggle('open',state.mobileMenuOpen)}
function nav(items){return `<div class=nav>${items.map(x=>`<button class="${state.view===x[0]?'active':''}" onclick="go('${x[0]}')">${x[1]}</button>`).join('')}</div>`}
window.addEventListener('popstate',()=>render());
setTimeout(()=>{v18PatchCampaignCardActions();v18InitTurnstile()},0);

function goBack(){const q=new URLSearchParams(location.search);const from=q.get('from');location.href=from==='user'?'/login/user':from==='advertiser'?'/login/advertiser':'/login/advertiser'}


/* V18 management UX overrides */
function settingsPage(){return `<h1>Owner Control Center</h1><p class=subtitle>هنا العمليات الحرجة فقط: حالة المنصة والطوارئ. إعدادات الباقات والمكافآت في صفحاتها المستقلة.</p><div class="emergencyBox"><div id=emergencyPanel>جارٍ التحميل...</div></div>`}
function packagesAdminPage(){return `<div class=space><div><h1>إدارة الباقات</h1><p class=subtitle>هذه هي باقات اشتراك المستخدمين: Free / Plus / Premium وأي باقات إضافية. الأولوية من 1 إلى 5 وتؤثر فعلياً في ترتيب الباقات.</p></div><button class=btn onclick="v18AddPackageModal()">+ إضافة باقة</button></div><div id=pkgAdmin class=section>جارٍ التحميل...</div>`}
async function loadPackagesAdmin(){const d=await api('/api/admin/packages');const rows=Object.values(d.packages||{}).sort((a,b)=>Number(b.priority||1)-Number(a.priority||1));$('#pkgAdmin').innerHTML=rows.map(p=>`<div class="packageAdmin"><div class=space><div><h2>${esc(p.name||p.key)}</h2><small class=muted>${esc(p.key)} · Priority ${Number(p.priority||1)}/5</small></div><span class="pill ${p.active?'green':'red'}">${p.active?'Active':'Inactive'}</span></div><div class=grid4 style="margin-top:12px"><div class=detailItem><small>Price</small><b>${fmt(p.price)} ${esc(p.currency||'JOD')}</b></div><div class=detailItem><small>Daily tasks</small><b>${p.dailyTasks||0}</b></div><div class=detailItem><small>Min level</small><b>${esc(levelLabel({levelMinId:p.minLevelId}))}</b></div><div class=detailItem><small>Priority</small><b>${Number(p.priority||1)} / 5</b></div></div><div class=row style="margin-top:12px"><button class=btn secondary onclick='v18EditPackage(${JSON.stringify(p).replace(/'/g,"&#039;")})'>تعديل</button><button class="btn ghost" onclick="v18PreviewPackage('${esc(p.key)}')">Preview</button></div></div>`).join('')||'<div class=card empty>لا توجد باقات.</div>'}
function v18AddPackageModal(existing){const p=existing||{name:'',price:0,durationDays:30,dailyTasks:30,priority:1,currency:'JOD',features:[]};const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><h2>${existing?'تعديل الباقة':'إضافة باقة'}</h2><div class=grid2><div class=field><label>اسم الباقة</label><input id=npName class=input value="${esc(p.name||'')}"></div><div class=field><label>السعر</label><input id=npPrice class=input type=number step=.01 value="${Number(p.price||0)}"></div><div class=field><label>المدة بالأيام</label><input id=npDur class=input type=number value="${Number(p.durationDays||0)}"></div><div class=field><label>Daily tasks</label><input id=npDaily class=input type=number value="${Number(p.dailyTasks||0)}"></div><div class=field><label>Priority 1–5</label><select id=npPriority class=input>${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(p.priority||1)===x?'selected':''}>${x}</option>`).join('')}</select></div><div class=field><label>Currency</label><input id=npCurrency class=input value="${esc(p.currency||'JOD')}"></div></div><div class=field><label>Features — one per line</label><textarea id=npFeatures class=input rows=5>${esc((p.features||[]).join('\n'))}</textarea></div><div class=row><button class=btn onclick="v18SavePackage('${esc(p.key||'')}')">حفظ</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)}
function v18EditPackage(p){v18AddPackageModal(p)}
async function v18SavePackage(key){const pin=await v17CodeModal('تأكيد تعديل/إضافة الباقة');if(!pin)return;const payload={name:$('#npName').value,price:Number($('#npPrice').value)||0,durationDays:Number($('#npDur').value)||0,dailyTasks:Number($('#npDaily').value)||0,priority:Number($('#npPriority').value)||1,minLevelId:$('#npLevel').value,currency:$('#npCurrency').value,features:$('#npFeatures').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),active:true,visible:true};try{if(key){await api('/api/admin/packages',{method:'POST',body:JSON.stringify({key,package:payload,confirm:pin})})}else{await api('/api/admin/packages/create',{method:'POST',body:JSON.stringify({...payload,confirm:pin})})}document.querySelector('.modalBack')?.remove();toast('تم حفظ الباقة');loadPackagesAdmin()}catch(e){toast(e.message)}}
function v18PreviewPackage(k){toast('Preview: '+k)}
function campaignsPage(){return `<div class=space><div><h1>الحملات</h1><p class=subtitle>إنشاء → مراجعة/اعتماد → إعداد Free / Plus / Premium → Publish. الحملة لا تصبح مهمة للمستخدم قبل النشر.</p></div><button class=btn onclick="v18CreateCampaignModal()">+ إنشاء حملة</button></div><div id=campBox class=section>جارٍ التحميل...</div>`}
function v18CreateCampaignModal(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="width:min(1000px,96vw)"><div class=space><h2>إنشاء حملة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>اسم الحملة</label><input id=v18cn class=input></div><div class=field><label>المعلن</label><select id=v18ca class=input><option value="">بدون معلن</option></select></div><div class=field><label>Objective</label><select id=v18co class=input><option>conversion</option><option>lead</option><option>traffic</option><option>video</option></select></div><div class=field><label>Task type</label><select id=v18ct class=input><option>video</option><option>survey</option><option>signup</option><option>lead</option><option>testing</option><option>purchase</option></select></div><div class=field><label>Budget JOD</label><input id=v18cb class=input type=number></div><div class=field><label>Platform revenue</label><input id=v18rev class=input type=number></div><div class=field><label>Start — Jordan time</label><input id=v18cs class=input type=datetime-local></div><div class=field><label>End — Jordan time</label><input id=v18ce class=input type=datetime-local></div><div class=field><label>Default Points</label><input id=v18cr class=input type=number></div><div class=field><label>Default XP</label><input id=v18cx class=input type=number></div><div class=field><label>Verification</label><select id=v18cv class=input><option>pending</option><option>auto</option><option>manual</option></select></div><div class=field><label>Max per user</label><input id=v18cm class=input type=number value=1></div></div><div class=field><label>Description</label><textarea id=v18cd class=input rows=3></textarea></div><div class=field><label>Conditions / execution steps</label><textarea id=v18ci class=input rows=4></textarea></div><div class=field><label>Content URL</label><input id=v18cu class=input></div><button class=btn onclick=v18CreateCampaign()>إنشاء للحالة Pending</button></div>`;document.body.appendChild(m);api('/api/admin/advertisers').then(d=>$('#v18ca').innerHTML='<option value="">بدون معلن</option>'+d.advertisers.map(a=>`<option value="${a.id}">${esc(a.company)}</option>`).join('')).catch(()=>{})}
async function v18CreateCampaign(){const pin=await v17CodeModal('تأكيد إنشاء الحملة');if(!pin)return;try{await api('/api/admin/campaigns',{method:'POST',body:JSON.stringify({name:$('#v18cn').value,advertiserId:$('#v18ca').value,objective:$('#v18co').value,taskType:$('#v18ct').value,budget:Number($('#v18cb').value)||0,platformRevenue:Number($('#v18rev').value)||0,startAtJordan:$('#v18cs').value||null,endAtJordan:$('#v18ce').value||null,rewardPerPerson:Number($('#v18cr').value)||0,xp:Number($('#v18cx').value)||0,verification:$('#v18cv').value,maxPerUser:Number($('#v18cm').value)||1,description:$('#v18cd').value,conditions:$('#v18ci').value,contentUrl:$('#v18cu').value,confirm:pin})});document.querySelector('.modalBack')?.remove();toast('تم إنشاء الحملة — Pending');render()}catch(e){toast(e.message)}}
async function loadCampaigns(){const d=await api('/api/admin/campaigns');$('#campBox').innerHTML=(d.campaigns||[]).map(c=>{const canApprove=['pending','draft','needs_changes'].includes(c.status),active=['active','paused','completed'].includes(c.status);return `<div class="card" style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId)} · ${esc(c.advertiser?.company||'غير مسند')}</small></div><span class="pill">${esc(c.status)}</span></div><div class=grid4 style="margin-top:12px"><div class=reportStat><small>Budget</small><strong>${fmt(c.budget)} JOD</strong></div><div class=reportStat><small>Spent</small><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=reportStat><small>Clicks</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(c.results?.conversions)}</strong></div></div><div class=row style="margin-top:12px">${canApprove?`<button class=btn onclick="v18ApproveCampaign('${esc(c.id)}')">Approve → Configure Packages</button>`:''}${active?`<button class=btn secondary onclick='openCampaignDetails(${JSON.stringify(c).replace(/'/g,"&#39;")})'>Analytics</button>`:''}${c.status==='preparing'?`<button class=btn onclick='v18CampaignPackageModal(${JSON.stringify(c).replace(/'/g,"&#39;")})'>Configure Free / Plus / Premium</button>`:''}</div></div>`}).join('')||'<div class=card empty>لا توجد حملات.</div>'}
async function v18ApproveCampaign(idv){const pin=await v17CodeModal('اعتماد الحملة والانتقال لإعداد الباقات');if(!pin)return;try{const d=await api('/api/admin/campaigns/approve',{method:'POST',body:JSON.stringify({id:idv,confirm:pin})});toast('تم اعتماد الحملة. الآن اضبط الباقات الثلاث.');v18CampaignPackageModal(d.campaign)}catch(e){toast(e.message)}}
function adminTasks(){return `<div class=space><div><h1>المهام</h1><p class=subtitle>إنشاء مهمة أو مهمة إضافية من نافذة مستقلة، بدون إغراق لوحة الإدارة بالنموذج.</p></div><button class=btn onclick="v18TaskModal()">+ إنشاء مهمة</button></div><div id=taskAdminBox class=section>جارٍ التحميل...</div>`}
function v18TaskModal(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="width:min(1000px,96vw)"><h2>إنشاء مهمة</h2><div class=grid2><div class=field><label>العنوان</label><input id=v18tn class=input></div><div class=field><label>Type / Goal</label><select id=v18tt class=input><option value=custom>مخصصة</option><option value=complete_tasks>إكمال مهام</option><option value=login_count>تسجيل الدخول</option><option value=collect_points>جمع Points</option><option value=referrals>إحالات</option><option value=category_tasks>مهام فئة</option></select></div><div class=field><label>Goal</label><input id=v18goal class=input type=number value=1></div><div class=field><label>Period</label><select id=v18period class=input><option>once</option><option>daily</option><option>weekly</option><option>monthly</option></select></div><div class=field><label>Start — Jordan time</label><input id=v18ts class=input type=datetime-local></div><div class=field><label>End — Jordan time</label><input id=v18te class=input type=datetime-local></div><div class=field><label>Points</label><input id=v18tp class=input type=number value=100></div><div class=field><label>XP</label><input id=v18tx class=input type=number value=20></div><div class=field><label>Minimum Level</label><select id=v18tl class=input>${v18Levels().map(x=>[x.id,x.name]).map(x=>`<option value=${x[0]}>${x[1]}</option>`).join('')}</select></div><div class=field><label>Package minimum</label><select id=v18pkg class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>Category</label><input id=v18cat class=input value=عام></div><div class=field><label>Daily limit</label><input id=v18dl class=input type=number value=1></div></div><div class=field><label>Description</label><textarea id=v18td class=input rows=3></textarea></div><div class=field><label>Conditions</label><textarea id=v18tc class=input rows=3></textarea></div><label class=checkRow><input id=v18add type=checkbox> مهمة إضافية / Challenge</label><label class=checkRow><input id=v18req type=checkbox> Requires Start by User</label><label class=checkRow><input id=v18show type=checkbox> Show before start as Upcoming</label><div class=row><button class=btn onclick=v18CreateTask()>حفظ</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)}
async function v18CreateTask(){const pin=await v17CodeModal('تأكيد إنشاء المهمة');if(!pin)return;try{await api('/api/admin/tasks',{method:'POST',body:JSON.stringify({title:$('#v18tn').value,type:$('#v18tt').value,goalType:$('#v18tt').value,goalTarget:Number($('#v18goal').value)||1,period:$('#v18period').value,startsAtJordan:$('#v18ts').value||null,endsAtJordan:$('#v18te').value||null,startsAt:$('#v18ts').value||null,endsAt:$('#v18te').value||null,points:Number($('#v18tp').value)||0,xp:Number($('#v18tx').value)||0,levelMinId:$('#v18tl').value,package:$('#v18pkg').value,category:$('#v18cat').value,description:$('#v18td').value,conditions:$('#v18tc').value,isAdditional:$('#v18add').checked,requiresStart:$('#v18req').checked,showBeforeStart:$('#v18show').checked,dailyLimit:Number($('#v18dl').value)||1,confirm:pin})});document.querySelector('.modalBack')?.remove();toast('تم إنشاء المهمة');render()}catch(e){toast(e.message)}}


function taskCard(t){const additional=!!t.isAdditional;const upcoming=t.eligibility==='مهمة إضافية قادمة';const action=additional&&!t.requiresStart?(upcoming?`<span class="pill gold">Upcoming</span>`:`<span class="pill green">Active automatically</span>`):`<button class="btn ${t.eligibility?'ghost':''}" ${t.eligibility?'disabled':''} onclick='openTask(${JSON.stringify(t).replace(/'/g,"&#39;")})'>التفاصيل</button>`;return `<div class="card taskCard"><div class=space><span class=pill>${esc(t.category||t.type)}</span><span class="pill ${t.eligibility?'gold':'green'}">${t.eligibility?'غير مؤهل':'مؤهل'}</span></div><h2 style="margin-top:13px">${esc(t.title)}</h2><p class=muted>${esc(t.description||'مهمة متاحة ضمن Tasko.')}</p><div class=taskMeta><span class=reward>${fmt(t.points)} Points</span><span class=pill>+${fmt(t.xp)} XP</span><span class=pill>Level ${esc(levelLabel(t))}+</span></div><div class=space>${action}</div></div>`}
function v18HandleOAuthToken(){const q=new URLSearchParams(location.search);const t=q.get('oauthToken');if(t){state.token=t;sessionStorage.setItem('taskoToken',t);history.replaceState({},'',location.pathname)}}
const __v18BaseRender=render;render=async function(){v18HandleOAuthToken();return __v18BaseRender()}

