async function processAdvertiserRequest(id,decision){
  if(decision==='approve'){
    const pin=await v17CodeModal('تأكيد اعتماد طلب المعلن');if(!pin)return;
    try{const d=await api('/api/admin/advertiser-request',{method:'POST',body:JSON.stringify({id,decision:'approve',confirm:pin})});document.querySelector('.modalBack')?.remove();v18AdvertiserCreateAccount(d.request)}catch(e){toast(e.message)}
  }else{const reason=prompt('سبب الرفض')||'';const pin=await v17CodeModal('تأكيد رفض الطلب');if(!pin)return;try{await api('/api/admin/advertiser-request',{method:'POST',body:JSON.stringify({id,decision:'reject',reason,confirm:pin})});document.querySelector('.modalBack')?.remove();render()}catch(e){toast(e.message)}}
}
function profilePage(){const u=state.user||{};return `<div class=space><div><h1>الملف الشخصي</h1><p class=subtitle>بيانات الحساب والاشتراك والمستوى.</p></div><span class=pill>${esc(u.accountState||'Normal')}</span></div><div class=grid2 section><div class=card><h2>${esc(u.name||'')}</h2><div class=detailList>${[['Account ID',u.id],['Email',u.email],['Phone',u.phone],['Country',u.country],['City',u.city],['Date of birth',u.dateOfBirth],['Gender',u.gender],['Level',u.level?.name],['Points',u.points],['XP',u.xp],['Cash',u.cash]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1]??'—')}</b></div>`).join('')}</div></div><div class=card><div class=space><h2>تفاصيل الاشتراك</h2><span class=pill>${esc(u.packageInfo?.status||'Active')}</span></div><div class=detailList>${[['الباقة',u.packageInfo?.type||u.package||'Free'],['تاريخ الاشتراك',date(u.packageInfo?.subscriptionDate)],['تاريخ الانتهاء',date(u.packageInfo?.expirationDate)],['الأيام المتبقية',u.packageInfo?.daysRemaining==null?'غير محدد':u.packageInfo.daysRemaining],['أولوية الباقة',u.packageInfo?.priority||1]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1])}</b></div>`).join('')}</div><div class=section>${levelBlock(u)}</div></div></div>`}

function v18CampaignAnalytics(c){const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;const clicks=Number(c.results?.clicks||0),conv=Number(c.results?.conversions||0),spent=Number(c.results?.spent||0),budget=Number(c.budget||0);const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="width:min(1100px,96vw)"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId||c.id)} · ${esc(c.status)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid4 section>${[['Budget',budget+' JOD'],['Spent',spent+' JOD'],['Remaining',Math.max(0,budget-spent)+' JOD'],['Conversion rate',(clicks?Math.round(conv/clicks*10000)/100:0)+'%']].map(x=>`<div class=card metric><span class=kpi>${x[0]}</span><strong>${esc(String(x[1]))}</strong></div>`).join('')}</div><div class="card section"><div class=space><h3>Campaign progress</h3><span>${pct}% spent</span></div><div class=progress style="margin-top:10px"><span style="width:${pct}%"></span></div><div class=grid4" style="margin-top:14px"><div class=detailItem><small>Clicks</small><b>${clicks}</b></div><div class=detailItem><small>Conversions</small><b>${conv}</b></div><div class=detailItem><small>Spent</small><b>${spent} JOD</b></div><div class=detailItem><small>Remaining</small><b>${Math.max(0,budget-spent)} JOD</b></div></div><div class=chartBars style="margin-top:18px"><div style="flex:1;text-align:center"><div class=bar style="height:${Math.max(8,Math.min(100,clicks/Math.max(1,budget)*100))}%"></div><small>Clicks: ${clicks}</small></div><div style="flex:1;text-align:center"><div class=bar style="height:${Math.max(8,Math.min(100,conv/Math.max(1,clicks||1)*100))}%"></div><small>Conversions: ${conv}</small></div><div style="flex:1;text-align:center"><div class=bar style="height:${Math.max(8,Math.min(100,spent/Math.max(1,budget)*100))}%"></div><small>Spent: ${spent} JOD</small></div></div></div><div class=card section><h3>Workflow</h3><div class=detailList><div class=detailItem><small>Status</small><b>${esc(c.status)}</b></div><div class=detailItem><small>Reference</small><b>${esc(c.referenceId||c.id)}</b></div><div class=detailItem><small>Verification</small><b>${esc(c.verification||'—')}</b></div><div class=detailItem><small>Packages</small><b>Free · Plus · Premium</b></div></div></div><div class="row section"><button class=btn onclick='v18EditCampaignModal(${JSON.stringify(c).replace(/'/g,"&#39;")})'>تعديل الحملة</button>${c.status==='active'?`<button class="btn secondary" onclick="v18CampaignStatus('${esc(c.id)}','paused')">Pause</button><button class="btn danger" onclick="v18CampaignStatus('${esc(c.id)}','completed')">Stop / End</button>`:''}${c.status==='paused'?`<button class=btn onclick="v18CampaignStatus('${esc(c.id)}','active')">Resume</button><button class="btn danger" onclick="v18CampaignStatus('${esc(c.id)}','completed')">Stop / End</button>`:''}</div></div>`;document.body.appendChild(m)}
function v18EditCampaignModal(c){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="width:min(1000px,96vw)"><h2>تعديل الحملة</h2><div class=grid2><div class=field><label>الاسم</label><input id=ecName class=input value="${esc(c.name||'')}"></div><div class=field><label>Budget JOD</label><input id=ecBudget class=input type=number value="${Number(c.budget||0)}"></div><div class=field><label>Start — Jordan</label><input id=ecStart class=input type=datetime-local value="${esc(c.startAtJordan||c.startAt||'')}"></div><div class=field><label>End — Jordan</label><input id=ecEnd class=input type=datetime-local value="${esc(c.endAtJordan||c.endAt||'')}"></div><div class=field><label>Verification</label><select id=ecVerify class=input><option ${c.verification==='pending'?'selected':''}>pending</option><option ${c.verification==='auto'?'selected':''}>auto</option><option ${c.verification==='manual'?'selected':''}>manual</option></select></div><div class=field><label>Max per user</label><input id=ecMax class=input type=number value="${Number(c.maxPerUser||1)}"></div></div><div class=field><label>Description</label><textarea id=ecDesc class=input rows=4>${esc(c.description||'')}</textarea></div><div class=field><label>Conditions / steps</label><textarea id=ecCond class=input rows=4>${esc(c.conditions||'')}</textarea></div><div class=row><button class=btn onclick="v18SaveCampaignEdit('${esc(c.id)}','${esc(c.updatedAt||'')}')">حفظ التعديل</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)}
async function v18SaveCampaignEdit(idv,updatedAt){const pin=await v17CodeModal('تأكيد تعديل الحملة');if(!pin)return;try{await api('/api/admin/campaigns/update',{method:'POST',body:JSON.stringify({id:idv,expectedUpdatedAt:updatedAt,name:$('#ecName').value,budget:Number($('#ecBudget').value)||0,startAtJordan:$('#ecStart').value||null,endAtJordan:$('#ecEnd').value||null,startAt:$('#ecStart').value||null,endAt:$('#ecEnd').value||null,verification:$('#ecVerify').value,maxPerUser:Number($('#ecMax').value)||1,description:$('#ecDesc').value,conditions:$('#ecCond').value,confirm:pin})});document.querySelector('.modalBack')?.remove();toast('تم حفظ التعديل');render()}catch(e){toast(e.message)}}
async function v18CampaignStatus(idv,status){const pin=await v17CodeModal('تأكيد تغيير حالة الحملة');if(!pin)return;try{await api('/api/admin/campaigns/status',{method:'POST',body:JSON.stringify({id:idv,status,confirm:pin})});document.querySelector('.modalBack')?.remove();toast('تم تحديث حالة الحملة');render()}catch(e){toast(e.message)}}

window.openCampaignDetails=v18OpenCampaign;
async function v17SessionsPage(){const d=await api('/api/admin/sessions');return `<h1>Sessions & Devices</h1><p class=subtitle>الجلسات النشطة، الجهاز، IP ووقت الدخول.</p><div class=card><div class=space><span class=pill>${d.sessions.length} sessions</span><button class="btn danger" onclick="v17LogoutAll()">تسجيل خروج كل الجلسات</button></div><div class=tableWrap section><table class=table><thead><tr><th>User</th><th>Portal</th><th>Device</th><th>IP</th><th>Started</th><th>Expires</th></tr></thead><tbody>${d.sessions.map(s=>`<tr><td>${esc(s.name)}<small class=muted style="display:block">${esc(s.email)}</small></td><td>${esc(s.portal)}</td><td>${esc((s.userAgent||'').slice(0,120))}</td><td>${esc(s.ip||'—')}</td><td>${date(s.createdAt)}</td><td>${date(s.expires)}</td></tr>`).join('')||'<tr><td colspan=6 class=empty>لا توجد جلسات.</td></tr>'}</tbody></table></div></div>`}
state.dirty=false;
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
const __v18OldGo=go;go=function(v){if(state.dirty&&!confirm('لديك تغييرات غير محفوظة. هل تريد المغادرة؟'))return;state.dirty=false;return __v18OldGo(v)};
document.addEventListener('input',e=>{if(e.target.closest('.modal'))state.dirty=true});
document.addEventListener('change',e=>{if(e.target.closest('.modal'))state.dirty=true});
function rewardsAdminPage(){return `<div class=space><div><h1>إدارة المكافآت</h1><p class=subtitle>إضافة وتعديل وتفعيل/تعطيل المكافآت من خلال واجهة مستقلة.</p></div><button class=btn onclick=v18RewardModal()>+ إضافة مكافأة</button></div><div id=rewardsAdminBox class=section>جارٍ التحميل...</div>`}
function v18RewardModal(existing){const r=existing||{};const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><h2>${existing?'تعديل المكافأة':'إضافة مكافأة'}</h2><div class=grid2><div class=field><label>اسم المكافأة</label><input id=vrTitle class=input value="${esc(r.title||'')}"></div><div class=field><label>الوصف</label><input id=vrDesc class=input value="${esc(r.description||'')}"></div><div class=field><label>Points cost</label><input id=vrCost class=input type=number value="${Number(r.pointsCost||0)}"></div><div class=field><label>Minimum Level</label><select id=vrLevel class=input>${v18Levels().map(x=>[x.id,x.name]).map(x=>`<option value=${x[0]}>${x[1]}</option>`).join('')}</select></div><div class=field><label>Package</label><select id=vrPkg class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>Uses / user</label><input id=vrUses class=input type=number value="${Number(r.usesPerUser||1)}"></div><div class=field><label>Redemption</label><select id=vrType class=input><option value=code>Code</option><option value=qr>QR</option><option value=manual>Manual</option></select></div></div><label class=checkRow><input id=vrActive type=checkbox ${r.active!==false?'checked':''}> Active</label><div class=row><button class=btn onclick="v18SaveReward('${esc(r.id||'')}')">حفظ</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m);if(r.levelMinId)$('#vrLevel').value=r.levelMinId;else if(r.levelMin!=null)$('#vrLevel').value=Number(r.levelMin)>=30000?'diamond':Number(r.levelMin)>=15000?'platinum':Number(r.levelMin)>=6000?'gold':Number(r.levelMin)>=1500?'silver':'bronze';if(r.packageMin)$('#vrPkg').value=r.packageMin;if(r.redemptionType)$('#vrType').value=r.redemptionType}
async function v18SaveReward(idv){const pin=await v17CodeModal('تأكيد حفظ المكافأة');if(!pin)return;try{const lv={bronze:0,silver:1500,gold:6000,platinum:15000,diamond:30000};const payload={id:idv,title:$('#vrTitle').value,description:$('#vrDesc').value,pointsCost:Number($('#vrCost').value)||0,levelMin:lv[$('#vrLevel').value]||0,packageMin:$('#vrPkg').value,usesPerUser:Number($('#vrUses').value)||1,redemptionType:$('#vrType').value,active:$('#vrActive').checked,confirm:pin};await api(idv?'/api/admin/rewards/update':'/api/admin/rewards',{method:'POST',body:JSON.stringify(payload)});document.querySelector('.modalBack')?.remove();toast('تم حفظ المكافأة');render()}catch(e){toast(e.message)}}
const __v18OldAuthMode=authMode;authMode=function(m){__v18OldAuthMode(m);if(m==='signup'){const f=document.getElementById('authForm');if(f&&!document.getElementById('v18SignupTurnstile')){const d=document.createElement('div');d.id='v18SignupTurnstile';d.className='section';f.insertBefore(d,f.lastElementChild);v18InitTurnstile()}}};
async function tasksPage(){const d=await api('/api/tasks');const all=(d.tasks||[]),main=all.filter(t=>!t.isAdditional),add=all.filter(t=>t.isAdditional),campaigns=d.campaigns||[];const cCards=campaigns.map(c=>{const cfg=c.packageConfig||{};const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;return `<div class=card taskCard><div class=space><span class=pill blue>Task</span><span class="pill ${c.eligibility?'gold':'green'}">${c.eligibility||'مؤهل'}</span></div><h2>${esc(c.name)}</h2><p class=muted>${esc(c.description||'مهمة منشورة عبر Tasko.')}</p><div class=taskMeta><span class=reward>${fmt(cfg.points||0)} Points</span><span class=pill>+${fmt(cfg.xp||0)} XP</span><span class=pill>${fmt(cfg.cashReward||0)} JOD Cash</span><span class=pill>Level ${esc(levelLabel({levelMinId:cfg.levelMinId||'bronze'}))}+</span></div><div class=progress><span style="width:${pct}%"></span></div><div class=space style="margin-top:8px"><small class=muted>التقدم يعتمد على إنجازات المهمة</small><button class="btn ${c.eligibility?'ghost':''}" ${c.eligibility?'disabled':''} onclick='openCampaignDetails(${JSON.stringify(c).replace(/'/g,"&#39;")})'>التفاصيل</button></div></div>`});return `<div class=space><div><h1>المهام</h1><p class=subtitle>الحملات المنشورة تظهر هنا كمهمات فعلية، والمهام الإضافية تبقى منفصلة.</p></div><span class=pill blue>${main.filter(t=>!t.eligibility).length+campaigns.filter(c=>!c.eligibility).length} مؤهل</span></div><div class=section><div class=sectionTitle><h2>المهام</h2></div><div class=grid2>${main.map(taskCard).join('')}${cCards.join('')||''}</div></div>${add.length?`<div class=section><div class=sectionTitle><h2>المهام الإضافية</h2><span class=pill>${add.length}</span></div><div class=grid2>${add.map(taskCard).join('')}</div></div>`:''}`}
function v18OpenCampaign(c){if(state.portal==='user')return window.__v18OldOpenCampaignDetails?window.__v18OldOpenCampaignDetails(c):null;if(['active','paused','completed'].includes(c.status))return v18CampaignAnalytics(c);return v18CampaignPackageModal(c)}
window.openCampaignDetails=v18OpenCampaign;

function v18Levels(){return state.levels||[{id:'bronze',name:'Bronze',minXP:0},{id:'silver',name:'Silver',minXP:1500},{id:'gold',name:'Gold',minXP:6000},{id:'platinum',name:'Platinum',minXP:15000},{id:'diamond',name:'Diamond',minXP:30000}]}

const __v18RenderWithLevels=render;render=async function(){if(state.token&&!state.levels){try{state.levels=(await api('/api/config/levels')).levels||null}catch{}}return __v18RenderWithLevels()};
function levelInfo(xp){const n=Number(xp)||0;const ls=v18Levels();let z=ls[0],next=null;for(let i=0;i<ls.length;i++){if(n>=Number(ls[i].minXP||0)){z=ls[i];next=ls[i+1]?.minXP??null}}return {id:z.id,name:z.name,min:Number(z.minXP||0),next,cls:z.id}}
function levelLabel(x){const id=x?.levelMinId||x?.levelId;if(id){const z=v18Levels().find(l=>l.id===id);if(z)return z.name}const n=Number(x?.levelMin||0);let z=v18Levels()[0];for(const l of v18Levels())if(n>=Number(l.minXP||0))z=l;return z.name}

