function v20CountryChanged(){const input=$('#country'),list=$('#cityList');if(!input||!list)return;const raw=input.value.trim();const c=window.__v20CountryByLabel?.get(raw)||window.__taskoCountriesV20?.find(x=>x.code===raw||x.nameEn.toLowerCase()===raw.toLowerCase()||x.nameAr===raw);const cap=c?.capital||'';list.innerHTML=cap?`<option value="${esc(cap)}"></option>`:''}
authMode=async function(m){$('#loginTab')?.classList.toggle('active',m==='login');$('#signupTab')?.classList.toggle('active',m==='signup');if(m==='signup')return v20SignupMode();return __v20OldAuthMode(m)};

async function v20Login(portal){try{const d=await api('/api/login/'+portal,{method:'POST',body:JSON.stringify({email:$('#email').value.trim(),password:$('#password').value,turnstileToken:window.__turnstileToken||''})});state.token=d.token;state.user=d.user;state.portal=d.portal;sessionStorage.setItem('taskoToken',d.token);sessionStorage.setItem('taskoPortal',d.portal);localStorage.setItem('taskoPortal',d.portal);if($('#rememberDevice')?.checked)localStorage.setItem('taskoToken',d.token);else localStorage.removeItem('taskoToken');location.href=portal==='owner'||portal==='admin'?'/admin':portal==='advertiser'?'/advertiser':'/dashboard'}catch(e){toast(e.message)}}
