const __v20OldPackagesPage=packagesPage;
packagesPage=function packagesPageV20(){return `<div class=space><div><h1>الباقات</h1><p class=subtitle>باقات اشتراك المستخدمين فقط. الأسعار والمزايا والحدود تأتي من إعدادات المنصة.</p></div><span class=pill>${esc(state.user?.package||'Free')}</span></div><div id=userPackagesBox class=grid3><div class=card empty>جارٍ تحميل الباقات...</div></div>`}
async function v20LoadUserPackages(){const box=$('#userPackagesBox');if(!box)return;try{const d=await api('/api/packages');const ps=Object.values(d.settings||{});box.innerHTML=ps.map(p=>{const current=d.current===p.key;const features=Array.isArray(p.features)?p.features:[];return `<div class="card package ${current?'current':''}"><span class="pill ${current?'green':'blue'}">${current?'الحالية':'متاحة'}</span><h2 style="margin-top:12px">${esc(p.name||p.key)}</h2><div style="font-size:27px;font-weight:800">${fmt(p.price||0)} ${esc(p.currency||'JOD')}</div><small class=muted>${p.durationDays?`${p.durationDays} يوم`:'بدون مدة محددة'}</small><ul>${features.map(f=>`<li>${esc(f)}</li>`).join('')||'<li>مزايا أساسية حسب إعدادات المنصة</li>'}</ul><div class=detailList><div class=detailItem><small>الأولوية</small><b>${Number(p.priority||1)}/5</b></div><div class=detailItem><small>المهام اليومية</small><b>${Number(p.dailyTasks||0)}</b></div></div>${current?'<button class="btn ghost" disabled>الباقة الحالية</button>':'<button class="btn ghost" disabled>الاشتراك يُدار من نظام الدفع</button>'}</div>`}).join('')||'<div class=card empty>لا توجد باقات منشورة.</div>'}catch(e){box.innerHTML=`<div class="card empty">${esc(e.message)}</div>`}}

