function v21CountryChanged(){const input=$('#country'),list=$('#cityList');if(!input||!list)return;const raw=input.value.trim();const c=window.__taskoCountriesV21?.find(x=>`${x.nameEn} — ${x.nameAr}`===raw||x.code===raw||x.nameEn.toLowerCase()===raw.toLowerCase()||x.nameAr===raw);const cities=(c?.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x);list.innerHTML=cities.map(x=>`<option value="${esc(x.en)} — ${esc(x.ar)}"></option>`).join('');}

