const V25_SOCIAL={facebook:'https://www.facebook.com/share/1E19HgKC6d/',instagram:'https://www.instagram.com/taskoplatform?stkn=bXBwczI3aWEzaXBx'};
function v25SocialLinks(){return `<div class="socialLinksV25" aria-label="مواقع Tasko"><a href="${V25_SOCIAL.facebook}" target="_blank" rel="noopener noreferrer" aria-label="Facebook"><span class="socialGlyph fb" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M14 8h3V4h-3c-3.31 0-5 1.69-5 5v2H6v4h3v5h4v-5h3l1-4h-4V9c0-.67.33-1 1-1Z" fill="currentColor"/></svg></span><span>Facebook</span></a><a href="${V25_SOCIAL.instagram}" target="_blank" rel="noopener noreferrer" aria-label="Instagram"><span class="socialGlyph ig" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4.25" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="17.5" cy="6.7" r="1.2" fill="currentColor"/></svg></span><span>Instagram</span></a><span class="socialHandleV27">@taskoplatform</span></div>`}
const __v25OldFooter=v21PublicFooter; v21PublicFooter=function(){return `<footer class="v21PublicFooter"><div><b>Tasko</b><span> — منصة مهام ومكافآت وحلول حملات للمعلنين.</span></div><div class="footerLinks"><a href="/privacy">الخصوصية</a><a href="/terms">الشروط</a><a href="/faq">FAQ</a><a href="/contact">تواصل</a></div>${v25SocialLinks()}</footer>`}
function v25AuthFooter(){return `<div class="v25AuthSocial">${v25SocialLinks()}</div>`}

// Auth routes: /owner and /admin are real direct entry points, not homepage fallbacks.
const __v25BaseRender=render;
render=async function(){
  const p=location.pathname.replace(/\/$/,'')||'/';
  if(!state.token && (p==='/owner'||p.startsWith('/owner/'))) return v21AuthShell('login','owner');
  if(!state.token && (p==='/admin'||p.startsWith('/admin/'))) return v21AuthShell('login','admin');
  return __v25BaseRender();
};

// Country/city searchable selectors: no free text, no typing-only acceptance.
let v25RegCountries=[],v25RegCountry=null,v25RegCity=null;
function v25CountryPicker(id,label,placeholder,onSelect){return `<div class="field v25Combo"><label>${label}</label><input id="${id}" class="input" autocomplete="off" placeholder="${placeholder}" readonly onclick="v25OpenCombo('${id}')"><div id="${id}Menu" class="v25ComboMenu"></div></div>`}
function v25OpenCombo(id){document.querySelectorAll('.v25ComboMenu.open').forEach(x=>x.classList.remove('open'));const m=document.getElementById(id+'Menu');if(!m)return;m.classList.add('open');const input=document.getElementById(id);m.innerHTML=`<input class="input v25ComboSearch" placeholder="ابحث..." oninput="v25FilterCombo('${id}',this.value)" autofocus><div id="${id}Options" class="v25ComboOptions"></div>`;v25RenderComboOptions(id,'')}
function v25FilterCombo(id,q){v25RenderComboOptions(id,q)}
function v25RenderComboOptions(id,q){const box=document.getElementById(id+'Options');if(!box)return;const query=(q||'').trim().toLowerCase();let rows=[];if(id==='country'){rows=v25RegCountries.filter(c=>`${c.nameEn} ${c.nameAr}`.toLowerCase().includes(query)).map(c=>`<button type="button" class="v25ComboOption" onclick="v25SelectCountry('${esc(c.code)}')"><span class="flag">${v25Flag(c.code)}</span><span>${esc(c.nameAr)} <small>${esc(c.nameEn)}</small></span></button>`)}else{const c=v25RegCountries.find(x=>x.code===v25RegCountry);const cities=(c?.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).filter(x=>`${x.en} ${x.ar}`.toLowerCase().includes(query));rows=cities.map(x=>`<button type="button" class="v25ComboOption" onclick="v25SelectCity(${JSON.stringify(x.en)},${JSON.stringify(x.ar)})"><span>📍</span><span>${esc(x.ar)} <small>${esc(x.en)}</small></span></button>`)}box.innerHTML=rows.join('')||'<div class="empty" style="padding:14px">لا توجد نتائج.</div>'}
function v25SelectCountry(code){v25RegCountry=code;v25RegCity=null;const c=v25RegCountries.find(x=>x.code===code);$('#country').value=`${c.nameAr} — ${c.nameEn}`;$('#country').dataset.code=code;$('#city').value='';$('#city').disabled=false;$('#city').dataset.code='';$('#countryMenu')?.classList.remove('open');}
function v25SelectCity(en,ar){v25RegCity=en;$('#city').value=`${ar} — ${en}`;$('#city').dataset.en=en;$('#city').dataset.ar=ar;$('#cityMenu')?.classList.remove('open')}
function v25ValidateRegistration(){if(!v25RegCountry||!v25RegCity)return toast('اختر الدولة والمدينة من القائمة أولاً'),false;return true}
async function v25SetAuthMode(mode){document.querySelectorAll('.authTabsV21 button').forEach(b=>b.classList.toggle('active',(mode==='login'&&b.id==='v21LoginTab')||(mode==='signup'&&b.id==='v21SignupTab')));if(mode==='login')return v21RenderLogin('user');const f=$('#v21AuthForm');if(!f)return;let d;try{d=await api('/api/config/countries')}catch(e){f.innerHTML='<div class="card empty">تعذر تحميل الدول. حاول مرة أخرى.</div>';return}v25RegCountries=d.countries||[];v25RegCountry=null;v25RegCity=null;f.innerHTML=`<div class="notice">اختر الدولة ثم المدينة من القوائم. الكتابة وحدها لا تكفي لإنشاء الحساب.</div><div class=field><label>الاسم</label><input id=name class=input autocomplete=name></div><div class=field><label>البريد الإلكتروني</label><input id=email class=input type=email autocomplete=email></div><div class=field><label>رقم الهاتف</label><input id=phone class=input autocomplete=tel placeholder="07xxxxxxxx"></div><div class=grid2>${v25CountryPicker('country','الدولة / Country','اختر الدولة')} ${v25CountryPicker('city','المدينة / City','اختر الدولة أولاً')}</div><div class=grid2><div class=field><label>تاريخ الميلاد</label><input id=dateOfBirth class=input type=date></div><div class=field><label>الجنس</label><select id=gender class=input><option value="">اختر</option><option value="Male">ذكر</option><option value="Female">أنثى</option></select></div></div><div class=field><label>كيف سمعت عن Tasko؟</label><select id=acquisitionSource class=input><option value="">اختر مصدراً واحداً</option>${['Instagram','Facebook','TikTok','YouTube','Social Media','Friend','Advertisement','Search Engine','Website','Online Community/Group','University/School','Company/Other','AI Tool','Other'].map(x=>`<option value="${x}">${esc(({Instagram:'Instagram',Facebook:'Facebook',TikTok:'TikTok',YouTube:'يوتيوب','Social Media':'وسائل التواصل الاجتماعي',Friend:'صديق/معارف',Advertisement:'إعلان','Search Engine':'محرك بحث',Website:'موقع إلكتروني','Online Community/Group':'مجتمع/مجموعة إلكترونية','University/School':'جامعة/مدرسة','Company/Other':'شركة/أخرى','AI Tool':'أداة ذكاء اصطناعي',Other:'أخرى'}[x]||x))}</option>`).join('')}</select></div><div class=field><label>كود الإحالة (اختياري)</label><input id=ref class=input></div><div class=field style="position:relative"><label>كلمة المرور</label><input id=password class=input type=password oninput="pwCheck()" autocomplete=new-password>${eye('password')}</div><div id=pwChecklist style="font-size:12px;margin:8px 0"></div><div class=field style="position:relative"><label>تأكيد كلمة المرور</label><input id=passwordConfirm class=input type=password autocomplete=new-password>${eye('passwordConfirm')}</div><div class="card consentCard"><label><input type=checkbox id=consent> أوافق على الشروط والخصوصية وقواعد Fair Play بعد قراءتها.</label><label class=checkRow><input type=checkbox id=demographicConsent> أقر أن بياناتي الحقيقية تخصني.</label><button class="btn ghost" type="button" onclick="showRules()">قراءة الشروط والقواعد</button></div><div id=v18Turnstile class=section></div><button class="btn v21PrimaryAuth" onclick="v25Register()">إنشاء الحساب</button>${v21SocialButton('google',true)}${v21SocialButton('facebook',true)}`;v25SetComboOutsideClose();v18InitTurnstile()}
function v25SetComboOutsideClose(){if(window.__v25ComboBound)return;window.__v25ComboBound=true;document.addEventListener('click',function(e){if(!e.target.closest('.v25Combo'))document.querySelectorAll('.v25ComboMenu.open').forEach(x=>x.classList.remove('open'))})}
async function v25Register(){try{if(!v25ValidateRegistration())return;if(!rulesRead)return toast('افتح قواعد الاستخدام واقرأها أولاً');if(!$('#consent').checked||!$('#demographicConsent').checked)return toast('يجب الموافقة على الشروط وإقرار صحة البيانات');if($('#password').value!==$('#passwordConfirm').value)return toast('كلمتا المرور غير متطابقتين');const d=await api('/api/register',{method:'POST',body:JSON.stringify({name:$('#name').value,email:$('#email').value,phone:$('#phone').value,password:$('#password').value,passwordConfirm:$('#passwordConfirm').value,ref:$('#ref').value,country:v25RegCountry,city:v25RegCity,dateOfBirth:$('#dateOfBirth').value,gender:$('#gender').value,acquisitionSource:$('#acquisitionSource').value,acquisitionOther:'',consent:true,demographicConsent:true,rulesRead:true,turnstileToken:window.__turnstileToken||''})});toast('تم إنشاء الحساب بنجاح');v25SetAuthMode('login');setTimeout(()=>{$('#email').value=d.user.email},50)}catch(e){toast(e.message)}}
v21SetAuthMode=v25SetAuthMode; // final registration UI override

// Tasks: real type filters, opportunity semantics, no eligibility-reason action, additional tasks preserved.
function v25TypeOf(t){return String(t.type||t.taskType||t.contentType||'custom').toLowerCase()}
function v25FilterButton(type,label){const active=state.taskFilter===type;return `<button type="button" class="btn ${active?'':'secondary'}" aria-pressed="${active}" onclick="state.taskFilter=state.taskFilter==='${type}'?'all':'${type}';render()">${label}</button>`}
function v25TaskCard(t){const [icon,label,tip]=v21TaskType(t),locked=!!t.eligibility,remaining=Number(t.attemptsRemaining??t.maxAttempts??1),max=Number(t.maxAttempts??1),mins=Math.max(1,Math.ceil(Number(t.duration||60)/60));return `<article class="taskCardV21 taskType-${esc(v25TypeOf(t))}"><div class=taskVisual><span class=taskIcon>${icon}</span><span class=pill>${esc(label)}</span></div><div class=space><span class="pill ${locked?'gold':'green'}">${locked?'غير متاح حالياً':'متاح الآن'}</span><span class=taskReward>${fmt(t.points)} Points</span></div><h2>${esc(t.title)}</h2><p>${esc(t.description||tip)}</p><div class=taskFacts><div><small>المدة</small><b>${mins} د</b></div><div><small>XP</small><b>+${fmt(t.xp)}</b></div><div><small>المستوى</small><b>${esc(levelLabel(t))}+</b></div><div><small>الفرص</small><b>${remaining} من ${max}</b></div></div><div class=taskCardFoot><button class="btn ${locked?'ghost':''}" ${locked?'disabled':''} onclick='openTask(${JSON.stringify(t).replace(/'/g,'&#39;')})'>${locked?'غير متاح':'عرض التفاصيل'}</button></div></article>`}
function v25CampaignCard(c){const cfg=c.packageConfig||{},[icon,label,tip]=v21TaskType({type:c.taskType||c.contentType}),locked=!!c.eligibility,remaining=Number(c.attemptsRemaining??c.maxAttempts??1),max=Number(c.maxAttempts??1);return `<article class="taskCardV21 campaignType-${esc(v25TypeOf(c))}"><div class=taskVisual><span class=taskIcon>${icon}</span><span class="pill blue">حملة منشورة</span></div><div class=space><span class="pill ${locked?'gold':'green'}">${locked?'غير متاح حالياً':'متاحة لك'}</span><span class=taskReward>${fmt(cfg.points||c.rewardPerPerson||0)} Points</span></div><h2>${esc(c.name)}</h2><p>${esc(c.description||tip)}</p><div class=taskFacts><div><small>الفرص</small><b>${remaining} من ${max}</b></div><div><small>XP</small><b>+${fmt(cfg.xp||c.xp||0)}</b></div><div><small>النوع</small><b>${esc(label)}</b></div><div><small>الإنجاز</small><b>${fmt(c.results?.conversions||0)}${c.requiredPeople?` / ${fmt(c.requiredPeople)}`:''}</b></div></div><div class=taskCardFoot><button class="btn ${locked?'ghost':''}" ${locked?'disabled':''} onclick='openCampaignDetails(${JSON.stringify(c).replace(/'/g,'&#39;')})'>${locked?'غير متاح':'عرض التفاصيل'}</button></div></article>`}
async function v25TasksPage(){const d=await api('/api/tasks'),all=d.tasks||[],main=all.filter(t=>!t.isAdditional),add=all.filter(t=>t.isAdditional),campaigns=d.campaigns||[];const f=state.taskFilter;const match=x=>f==='all'||v25TypeOf(x)===f;const m=main.filter(match),c=campaigns.filter(match),a=add.filter(match);return `<div class=space><div><h1>المهام</h1><p class=subtitle>اختر نوع المهمة. الفرص هي عدد المحاولات المسموح بها لكل مهمة وليست تكراراً يومياً.</p></div><span class="pill blue">${m.filter(x=>!x.eligibility).length+c.filter(x=>!x.eligibility).length} متاحة</span></div><div class="categoryTabs taskFilterV25">${v25FilterButton('all','الكل')}${v25FilterButton('video','🎬 فيديو')}${v25FilterButton('survey','📝 استبيان')}${v25FilterButton('testing','🧪 اختبار')}${v25FilterButton('signup','👤 تسجيل')}${v25FilterButton('lead','📩 Lead')}${v25FilterButton('purchase','🛍️ شراء')}</div><section class=section><div class=sectionTitle><h2>المهام المتاحة</h2><span class=muted>${m.length+c.length} مهمة/حملة</span></div><div class=taskGridV21>${m.map(v25TaskCard).join('')}${c.map(v25CampaignCard).join('')}</div></section><section class=section><div class=sectionTitle><h2>المهام الإضافية</h2><span class=pill>${a.length}</span></div>${a.length?`<div class=taskGridV21>${a.map(v25TaskCard).join('')}</div>`:'<div class="card empty">لا توجد مهام إضافية متاحة حالياً.</div>'}</section>`}
v21TasksPage=v25TasksPage;

// Task details: opportunities, not daily repetition; no eligibility-reason UI.
openTask=function(t){const [icon,label,tip]=v21TaskType(t),remaining=Number(t.attemptsRemaining??t.maxAttempts??1),max=Number(t.maxAttempts??1);const m=document.createElement('div');m.className='modalBack';m.id='taskModal';m.innerHTML=`<div class="modal taskDetailV21"><div class=space><div><span class=taskIcon>${icon}</span><span class=pill>${esc(label)}</span><h2 style="margin-top:10px">${esc(t.title)}</h2></div><button class="btn ghost" onclick="$('#taskModal').remove()">إغلاق</button></div><p class=subtitle>${esc(t.description||tip)}</p><div class=detailList><div class=detailItem><small>المكافأة</small><b>${fmt(t.points)} Points</b></div><div class=detailItem><small>XP</small><b>+${fmt(t.xp)} XP</b></div><div class=detailItem><small>المدة المتوقعة</small><b>حوالي ${Math.max(1,Math.ceil((t.duration||60)/60))} دقيقة</b></div><div class=detailItem><small>طريقة التحقق</small><b>${esc(t.verify||t.verification||'مراجعة')}</b></div><div class=detailItem><small>الفرص</small><b>${remaining} من ${max}</b></div></div><div class=typeGuideV21><b>${label==='فيديو'?'طريقة التنفيذ':label==='استبيان'?'قبل الإرسال':label==='اختبار'?'خطوات الاختبار':'المطلوب منك'}</b><p>${esc(t.conditions||tip)}</p></div><div class=notice><b>قبل البدء:</b> ستُسجل محاولة مستقلة عند البدء، وتُحتسب كفرصة من الفرص المتاحة.</div><div class=row style="margin-top:18px"><button class=btn ${remaining<=0?'disabled':''} ${remaining<=0?'disabled':''} onclick="startTask('${esc(t.id)}')">ابدأ المهمة</button><button class="btn ghost" onclick="$('#taskModal').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)};

// Rewards search: filter current cards in-place, preserving focus/caret.
function v25RewardLiveSearch(value){v21RewardSearch=String(value||'');const q=v21RewardSearch.trim().toLowerCase();document.querySelectorAll('.rewardCardV21').forEach(c=>{c.style.display=(!q||String(c.dataset.search||'').includes(q))?'flex':'none'});const shown=[...document.querySelectorAll('.rewardCardV21')].filter(c=>c.style.display!=='none').length;const e=document.getElementById('v25RewardEmpty');if(e)e.style.display=shown?'none':'block'}
const __v25OldRewards=v21RewardsPage;v21RewardsPage=async function(){let html=await __v25OldRewards();html=html.replace(/oninput="v21RewardSearch=this.value;v21RewardPage=1;render\(\)"/,'oninput="v25RewardLiveSearch(this.value)" id="v25RewardSearchInput"');html=html.replace(/<article class="rewardCardV21">/g,'<article class="rewardCardV21" data-search="">');return html.replace(/<\/div><div class="paginationV21">/, '<div id="v25RewardEmpty" class="card empty" style="display:none">لا توجد مكافآت مطابقة للبحث.</div></div><div class="paginationV21">')}

// Packages: remove package-level per-task limit and explain benefits are not guaranteed earnings.
const __v25OldPackages=v21PackagesPage;v21PackagesPage=async function(){let html=await __v25OldPackages();html=html.replace(/<div class=detailItem><small>حد المهمة<\/small><b>.*?<\/b><\/div>/g,'');html=html.replace(/<div class="notice" style="margin-top:16px">([^<]*)<\/div>/g,'<div class="notice" style="margin-top:16px">هذه الباقة توفر مزايا وميزات وصول فقط، وليست وعداً بربح فعلي أو دخلاً مضموناً.</div>');return html}
const __v25OldPackageDetails=v21OpenPackageDetails;v21OpenPackageDetails=function(p,current){const m=document.createElement('div');m.className='modalBack';const features=Array.isArray(p.features)?p.features:[];m.innerHTML=`<div class="modal packageDetailModalV21"><div class=space><div><span class="pill blue">${esc(p.name||p.key)}</span><h2>${esc(p.name||p.key)}</h2></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class="packageDetailHeroV21"><strong>${fmt(p.price||0)} ${esc(p.currency||'JOD')}</strong><span>${p.durationDays?`${fmt(p.durationDays)} يوم`:'بدون مدة محددة'}</span></div><h3>المزايا</h3><ul class=v21FeatureList>${features.map(f=>`<li>✓ ${esc(f)}</li>`).join('')||'<li>المزايا الأساسية المتاحة في هذه الباقة.</li>'}</ul><div class=detailList><div class=detailItem><small>الأولوية</small><b>${fmt(p.priority||1)} / 5</b></div><div class=detailItem><small>المهام اليومية</small><b>${fmt(p.dailyTasks||0)}</b></div><div class=detailItem><small>الحد الأدنى للسحب</small><b>${fmt(p.withdrawalMin||0)} JOD</b></div></div><div class="notice" style="margin-top:16px">هذه الباقة توفر مزايا وميزات وصول فقط، وليست وعداً بربح فعلي أو دخلاً مضموناً. ${current?'هذه باقتك الحالية.':'بعد طلب الاشتراك تنتقل العملية إلى الدفع، ثم تُفعّل الباقة عند نجاح الدفع.'}</div>${current?'<button class="btn ghost" disabled style="width:100%;margin-top:12px">الباقة الحالية</button>':'<button class="btn" style="width:100%;margin-top:12px" onclick="v21RequestPackage(&quot;'+esc(p.key)+'&quot;)">طلب الاشتراك</button>'}</div>`;document.body.appendChild(m)}

// Notifications: mark all read and show status clearly.
notificationsPage=async function(){const d=await api('/api/notifications');return `<div class="space"><div><h1>الإشعارات</h1><p class=subtitle>${fmt(d.unread)} غير مقروء</p></div><button class="btn secondary" onclick="v25MarkNotificationsRead()" ${d.unread?'':'disabled'}>تحديد الكل كمقروء</button></div>${d.items.map(n=>`<article class="card notificationCardV25 ${n.read?'read':'unread'}"><div class=space><h3>${esc(n.title)}</h3><span class="pill">${esc(n.type||'info')}</span></div><p>${esc(n.message)}</p><small class=muted>${date(n.at)}</small></article>`).join('')||'<div class=card empty>لا توجد إشعارات.</div>'}`}
async function v25MarkNotificationsRead(){try{await api('/api/notifications/read',{method:'POST'});render()}catch(e){toast(e.message)}}

// Account settings: country/city every 2 months with password; phone password + OTP.
async function v25SettingsPage(){const d=await api('/api/profile'),u=d.user;const countries=(await api('/api/config/countries')).countries||[];const currentC=countries.find(c=>c.code===u.country);const currentCity=(currentC?.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).find(x=>x.en===u.city||x.ar===u.city);const last=u.locationChangedAt?new Date(u.locationChangedAt).getTime():0;const next=last?new Date(last+60*86400000):null;const locked=next&&next.getTime()>Date.now();return `<div class=space><div><h1>الإعدادات</h1><p class=subtitle>بيانات الحساب، الأمان والجلسات.</p></div><span class=pill>${esc(u.accountState||'Normal')}</span></div><div class=grid2><div class=card><h2>بيانات الحساب</h2><div class=field><label>الاسم</label><input id=sName class=input value="${esc(u.name||'')}"></div><button class=btn onclick="v25SaveName()">حفظ الاسم</button><hr class=v25Hr><h3>الدولة والمدينة</h3><p class=muted>يمكن تغيير الدولة والمدينة مرة كل شهرين، ويتطلب ذلك كلمة مرور الحساب الحالية.</p>${locked?`<div class="notice warning">التغيير متاح بعد: <b>${date(next)}</b></div>`:''}<div class=grid2><div class=field><label>الدولة</label><select id=sCountry class=input onchange="v25FillSettingsCities()" ${locked?'disabled':''}><option value="">اختر الدولة</option>${countries.map(c=>`<option value="${esc(c.code)}" ${u.country===c.code?'selected':''}>${v25Flag(c.code)} ${esc(c.nameAr)} — ${esc(c.nameEn)}</option>`).join('')}</select></div><div class=field><label>المدينة</label><select id=sCity class=input ${locked?'disabled':''}></select></div></div><div class=field><label>كلمة المرور الحالية</label><input id=sLocationPass class=input type=password ${locked?'disabled':''}></div><button class="btn" onclick="v25SaveLocation()" ${locked?'disabled':''}>حفظ الدولة والمدينة</button><hr class=v25Hr><h3>رقم الهاتف</h3><p class=muted>تغيير الرقم يتطلب كلمة مرور الحساب ثم رمز OTP يُرسل إلى الرقم الجديد.</p><div class=field><label>الرقم الحالي</label><input class=input value="${esc(u.phone||'—')}" disabled></div><div class=field><label>الرقم الجديد</label><input id=sNewPhone class=input placeholder="07xxxxxxxx"></div><div class=field><label>كلمة المرور الحالية</label><input id=sPhonePass class=input type=password></div><button class="btn secondary" onclick="v25RequestPhoneOtp()">إرسال OTP للرقم الجديد</button><div id=v25OtpWrap></div></div><div class=card><h2>البريد الإلكتروني</h2><p class=muted>تغيير البريد يتطلب كلمة المرور الحالية.</p><div class=field><label>البريد الجديد</label><input id=sEmail class=input type=email value="${esc(u.email||'')}"></div><div class=field><label>كلمة المرور الحالية</label><input id=sEmailPass class=input type=password></div><button class=btn secondary onclick="v21ChangeEmail()">تغيير البريد الإلكتروني</button><hr class=v25Hr><h2>تغيير كلمة المرور</h2><div class=field><label>كلمة المرور الحالية</label><input id=sOld class=input type=password></div><div class=field><label>كلمة المرور الجديدة</label><input id=sNew class=input type=password></div><div class=field><label>تأكيد الجديدة</label><input id=sNew2 class=input type=password></div><button class=btn onclick="v20ChangePassword()">تغيير كلمة المرور</button><hr class=v25Hr><h2>الجلسات</h2><div id=v20Sessions>${(d.sessions||[]).map(s=>`<div class=detailItem style="margin:8px 0"><b>${esc(s.portal)}</b><small>${esc(s.userAgent||'—')} · ${esc(s.ip||'—')}</small><small>${date(s.createdAt)}</small></div>`).join('')||'<div class=empty>لا توجد جلسات.</div>'}</div><button class="btn danger" style="margin-top:10px" onclick="v17LogoutAll()">تسجيل الخروج من كل الجلسات</button></div></div>`}
function v25FillSettingsCities(){const c=$('#sCountry')?.value,el=$('#sCity');if(!el)return;api('/api/config/countries').then(d=>{const x=(d.countries||[]).find(z=>z.code===c);el.innerHTML='<option value="">اختر المدينة</option>'+(x?.cities||[]).map(y=>{const z=typeof y==='string'?{en:y,ar:y}:y;return `<option value="${esc(z.en)}">${esc(z.ar)} — ${esc(z.en)}</option>`}).join('');if(state.user?.city)el.value=state.user.city})}
async function v25SaveName(){try{const d=await api('/api/profile/update',{method:'POST',body:JSON.stringify({name:$('#sName').value})});state.user=d.user;toast('تم حفظ الاسم');render()}catch(e){toast(e.message)}}
async function v25SaveLocation(){try{const d=await api('/api/profile/location',{method:'POST',body:JSON.stringify({country:$('#sCountry').value,city:$('#sCity').value,currentPassword:$('#sLocationPass').value})});state.user=d.user;toast('تم تحديث الدولة والمدينة');render()}catch(e){toast(e.message)}}
async function v25RequestPhoneOtp(){try{const d=await api('/api/profile/phone/request',{method:'POST',body:JSON.stringify({newPhone:$('#sNewPhone').value,currentPassword:$('#sPhonePass').value})});$('#v25OtpWrap').innerHTML=`<div class=field><label>رمز OTP</label><input id=sPhoneOtp class=input inputmode=numeric maxlength=6></div><button class="btn" onclick="v25VerifyPhoneOtp()">تأكيد الرقم</button>${d.devOtp?`<div class="notice" style="margin-top:10px">وضع التطوير: OTP = <b>${esc(d.devOtp)}</b></div>`:''}`;toast(d.message)}catch(e){toast(e.message)}}
async function v25VerifyPhoneOtp(){try{const d=await api('/api/profile/phone/verify',{method:'POST',body:JSON.stringify({otp:$('#sPhoneOtp').value})});state.user=d.user;toast('تم تحديث رقم الهاتف');render()}catch(e){toast(e.message)}}
// Override settings route for user.
const __v25OldUserRender=userRender;userRender=async function(){if(state.view==='settings'){layout(await v25SettingsPage());setTimeout(v25FillSettingsCities,0);return}if(state.view==='tasks')return layout(await v25TasksPage());if(state.view==='packages')return layout(await v21PackagesPage());if(state.view==='rewards')return layout(await v21RewardsPage());return __v25OldUserRender()};

// FAQ: admin-managed, searchable, reorderable, optional links.
async function v25FaqAdminPage(){return `<div class=space><div><h1>إدارة الأسئلة الشائعة</h1><p class=subtitle>أضف، عدّل، احذف ورتّب الأسئلة. الرابط اختياري لكل سؤال.</p></div><button class=btn onclick="v25FaqModal()">+ إضافة سؤال</button></div><div id=v25FaqAdminBox class=section>جارٍ التحميل...</div>`}
async function v25LoadFaqAdmin(){const d=await api('/api/admin/faqs');const box=$('#v25FaqAdminBox');if(!box)return;box.innerHTML=(d.faqs||[]).map((f,i)=>`<article class="card faqAdminRow" draggable="true" data-id="${esc(f.id)}"><div class=space><div><span class=pill>${i+1}</span><h3 style="display:inline;margin-inline-start:8px">${esc(f.question)}</h3></div><span class="pill ${f.active!==false?'green':'gold'}">${f.active!==false?'منشور':'مخفي'}</span></div><p>${esc(f.answer)}</p>${f.link?`<div class=notice>الرابط: <a href="${esc(f.link)}" target="_blank" rel="noopener">${esc(f.link)}</a></div>`:''}<div class=row style="margin-top:12px"><button class="btn secondary" onclick='v25FaqModal(${JSON.stringify(f).replace(/'/g,"&#39;")})'>تعديل</button><button class="btn danger" onclick="v25DeleteFaq('${esc(f.id)}')">حذف</button></div></article>`).join('')||'<div class=card empty>لا توجد أسئلة.</div>';v25BindFaqDrag()}
function v25FaqModal(f=null){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal><div class=space><h2>${f?'تعديل السؤال':'إضافة سؤال'}</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=field><label>السؤال</label><input id=v25FaqQ class=input value="${esc(f?.question||'')}"></div><div class=field><label>الإجابة</label><textarea id=v25FaqA class=input rows=7>${esc(f?.answer||'')}</textarea></div><div class=field><label>الرابط (اختياري)</label><input id=v25FaqL class=input placeholder="/tasks أو https://..." value="${esc(f?.link||'')}"></div><label class=checkRow><input id=v25FaqActive type=checkbox ${f?.active!==false?'checked':''}> منشور للمستخدمين</label><div class=row><button class=btn onclick="v25SaveFaq(${JSON.stringify(f?.id||'')})">حفظ</button><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إلغاء</button></div></div>`;document.body.appendChild(m)}
async function v25SaveFaq(idv){const pin=await v17CodeModal('تأكيد حفظ FAQ');if(!pin)return;try{await api('/api/admin/faqs',{method:'POST',body:JSON.stringify({id:idv||undefined,question:$('#v25FaqQ').value,answer:$('#v25FaqA').value,link:$('#v25FaqL').value,active:$('#v25FaqActive').checked,confirm:pin})});document.querySelector('.modalBack')?.remove();toast('تم حفظ السؤال');v25LoadFaqAdmin()}catch(e){toast(e.message)}}
async function v25DeleteFaq(idv){const pin=await v17CodeModal('تأكيد حذف السؤال');if(!pin)return;try{await api('/api/admin/faqs/delete',{method:'POST',body:JSON.stringify({id:idv,confirm:pin})});toast('تم حذف السؤال');v25LoadFaqAdmin()}catch(e){toast(e.message)}}
function v25BindFaqDrag(){const box=$('#v25FaqAdminBox');if(!box)return;let dragged=null;box.querySelectorAll('.faqAdminRow').forEach(row=>{row.addEventListener('dragstart',()=>dragged=row);row.addEventListener('dragover',e=>e.preventDefault());row.addEventListener('drop',async e=>{e.preventDefault();if(!dragged||dragged===row)return;row.parentNode.insertBefore(dragged,row);const ids=[...box.querySelectorAll('.faqAdminRow')].map(x=>x.dataset.id);const pin=prompt('رمز الأمان المكوّن من 4 أرقام');if(!pin)return;try{await api('/api/admin/faqs/reorder',{method:'POST',body:JSON.stringify({ids,confirm:pin})});toast('تم ترتيب الأسئلة')}catch(e){toast(e.message)}})})}
const __v25OldAdminNav=v17AdminNav;v17AdminNav=function(){return [...__v25OldAdminNav(),['faqAdmin','❓ إدارة FAQ']]};
const __v25OldPermFor=permFor;permFor=function(v){return v==='faqAdmin'?'settings':__v25OldPermFor(v)};
const __v25OldAdminRenderBase=adminRenderBase;adminRenderBase=function(){if(state.view==='faqAdmin')return Promise.resolve(v25FaqAdminPage()).then(x=>{v18Layout(x);setTimeout(v25LoadFaqAdmin,0)});return __v25OldAdminRenderBase()};

