v26ScheduleMode=function(){const custom=$('#rcperiod')?.value==='custom';const box=$('#v26Schedules');if(box)box.style.display=custom?'block':'none';if(custom&&!$('#v26ScheduleRows')?.children.length)v26AddSchedule()};
v26AddSchedule=function(){const box=$('#v26ScheduleRows');if(!box)return;const i=box.children.length;const row=document.createElement('div');row.className='scheduleRowV26';row.innerHTML=`<div class=grid2><div class=field><label>بداية الموعد ${i+1}</label><input class="input schStart" type=datetime-local></div><div class=field><label>نهاية الموعد ${i+1}</label><input class="input schEnd" type=datetime-local></div></div><button class="btn danger" type=button onclick="this.parentElement.remove()">حذف الموعد</button>`;box.appendChild(row)};
submitCampaignRequestV26=async function(){const required=[['rcn','اسم الحملة'],['rcx','الوصف'],['rcb','الميزانية'],['rcs','البداية'],['rce','النهاية']];const miss=required.filter(([id])=>!String($('#'+id)?.value||'').trim());if(miss.length)return toast('أكمل: '+miss.map(x=>x[1]).join('، '));const start=new Date($('#rcs').value),end=new Date($('#rce').value);if(end<=start)return toast('تاريخ ووقت النهاية يجب أن يكونا بعد البداية');const custom=$('#rcperiod').value==='custom';const customSchedules=[...document.querySelectorAll('#v26ScheduleRows .scheduleRowV26')].map(r=>({startAt:r.querySelector('.schStart').value,endAt:r.querySelector('.schEnd').value}));if(custom&&(!customSchedules.length||customSchedules.some(x=>!x.startAt||!x.endAt||new Date(x.endAt)<=new Date(x.startAt))))return toast('أكمل مواعيد Custom بشكل صحيح');try{await api('/api/advertiser/campaign',{method:'POST',body:JSON.stringify({name:$('#rcn').value,objective:$('#rco').value,budget:$('#rcb').value,startAt:start.toISOString(),endAt:end.toISOString(),taskType:$('#rct').value,maxPerUser:$('#rcm').value,landingUrl:$('#rcu').value,description:$('#rcx').value,conditions:$('#rcc').value,period:$('#rcperiod').value,customSchedules,requiredPeople:$('#rcpeople').value,rewardPerPerson:$('#rcreward').value,xp:$('#rcxp').value})});document.querySelector('.modalBack')?.remove();toast('تم حفظ الحملة وإرسالها للمراجعة');go('campaigns')}catch(e){toast(e.message)}};

// User packages: daily limit only; no weekly/monthly/"per task" wording.
const __v26Packages=v21PackagesPage;
v21PackagesPage=async function(){let h=await __v26Packages();h=h.replace(/<div class=detailItem><small>حد المهمة<\/small><b>.*?<\/b><\/div>/g,'');h=h.replace(/<div class=detailItem><small>المهام الأسبوعية<\/small><b>.*?<\/b><\/div>/g,'');h=h.replace(/<div class=detailItem><small>المهام الشهرية<\/small><b>.*?<\/b><\/div>/g,'');return h};

// Settings: searchable country/city, cooldowns, password checks, email OTP, concise sessions.
v25SettingsPage=async function(){const d=await api('/api/profile'),u=d.user;const countries=(await api('/api/config/countries')).countries||[];const lastName=u.nameChangedAt?new Date(u.nameChangedAt).getTime():0,lastLoc=u.locationChangedAt?new Date(u.locationChangedAt).getTime():0;const nameLocked=lastName&&Date.now()-lastName<60*86400000,locLocked=lastLoc&&Date.now()-lastLoc<60*86400000;return `<div class=space><div><h1>الإعدادات</h1><p class=subtitle>بيانات الحساب، الأمان والجلسات.</p></div><span class=pill>${esc(u.accountState||'Normal')}</span></div><div class="grid2 settingsV26"><div class=card><h2>بيانات الحساب</h2><div class=field><label>الاسم</label><input id=sName class=input value="${esc(u.name||'')}" ${nameLocked?'disabled':''}></div>${nameLocked?`<p class="muted">يمكن تغيير الاسم مرة كل شهرين. الموعد التالي: ${date(new Date(lastName+60*86400000))}</p>`:''}<button class=btn onclick="v25SaveName()" ${nameLocked?'disabled':''}>حفظ الاسم</button><hr class=v25Hr><h3>الدولة والمدينة</h3><p class=muted>التغيير مرة كل شهرين ويتطلب كلمة مرور الحساب.</p>${locLocked?`<div class="notice warning">متاح بعد: ${date(new Date(lastLoc+60*86400000))}</div>`:''}<div class=grid2>${v26SettingsPicker('sCountry','الدولة','اختر الدولة',countries,u.country,locLocked)}${v26SettingsCityPicker('sCity','المدينة','اختر المدينة',locLocked)}</div><div class=field><label>كلمة مرور الحساب</label><input id=sLocationPass class=input type=password ${locLocked?'disabled':''}></div><button class=btn onclick="v25SaveLocation()" ${locLocked?'disabled':''}>حفظ الدولة والمدينة</button><hr class=v25Hr><h3>رقم الهاتف</h3><p class=muted>كلمة المرور + OTP للرقم الجديد.</p><div class=field><label>الرقم الحالي</label><input class=input value="${esc(u.phone||'—')}" disabled></div><div class=field><label>الرقم الجديد</label><input id=sNewPhone class=input placeholder="07xxxxxxxx"></div><div class=field><label>كلمة مرور الحساب</label><input id=sPhonePass class=input type=password></div><button class="btn secondary" onclick="v25RequestPhoneOtp()">إرسال OTP</button><div id=v25OtpWrap></div></div><div class=card><h2>البريد الإلكتروني</h2><p class=muted>اكتب بريدًا جديدًا، كلمة مرور الحساب، ثم أدخل OTP المرسل إلى البريد الجديد.</p><div class=field><label>البريد الحالي</label><input class=input value="${esc(u.email||'')}" disabled></div><div class=field><label>البريد الجديد</label><input id=sEmail class=input type=email></div><div class=field><label>كلمة مرور الحساب</label><input id=sEmailPass class=input type=password></div><button class="btn secondary" onclick="v26RequestEmailOtp()">إرسال OTP للبريد الجديد</button><div id=v26EmailOtpWrap></div><hr class=v25Hr><h2>تغيير كلمة المرور</h2><div class=field><label>كلمة المرور الحالية</label><input id=sOld class=input type=password></div><div class=field><label>كلمة المرور الجديدة</label><input id=sNew class=input type=password></div><div class=field><label>تأكيد الجديدة</label><input id=sNew2 class=input type=password></div><button class=btn onclick="v20ChangePassword()">تغيير كلمة المرور</button><hr class=v25Hr><h2>الجلسات</h2><div>${(d.sessions||[]).map(s=>`<div class="sessionRowV26"><b>${esc(s.deviceName||s.portal||'الجهاز')}</b><small>آخر دخول: ${date(s.createdAt)}</small><small>الموقع: ${esc(s.location||'غير متاح')}</small></div>`).join('')||'<div class=empty>لا توجد جلسات.</div>'}</div><button class="btn danger" style="margin-top:10px" onclick="v26LogoutAll()">تسجيل الخروج من جميع الجلسات</button></div></div>`};
v26SettingsPicker=function(id,label,ph,countries,current,locked){return `<div class="field v26Combo"><label>${label}</label><input id="${id}" class=input value="${esc((countries.find(c=>c.code===current)?.nameAr||''))}" placeholder="${ph}" readonly ${locked?'disabled':''} onclick="v26OpenSettingsCombo('${id}','country')"><div id="${id}Menu" class=v26ComboMenu></div></div>`};
v26SettingsCityPicker=function(id,label,ph,locked){return `<div class="field v26Combo"><label>${label}</label><input id="${id}" class=input placeholder="${ph}" readonly disabled ${locked?'disabled':''} onclick="v26OpenSettingsCombo('${id}','city')"><div id="${id}Menu" class=v26ComboMenu></div></div>`};
window.__v26SettingsCountries=[];window.__v26SettingsCountry='';window.__v26SettingsCity='';
v26OpenSettingsCombo=function(id,type){const menu=$('#'+id+'Menu');if(!menu)return;menu.classList.add('open');menu.innerHTML=`<input class=input placeholder="ابحث..." oninput="v26FilterSettingsCombo('${id}','${type}',this.value)" autofocus><div id="${id}Options"></div>`;v26FilterSettingsCombo(id,type,'')};
v26FilterSettingsCombo=function(id,type,q){const box=$('#'+id+'Options'),query=String(q||'').toLowerCase();if(!box)return;if(type==='country'){box.innerHTML=window.__v26SettingsCountries.filter(c=>`${c.nameAr} ${c.nameEn}`.toLowerCase().includes(query)).map(c=>`<button type=button class=v25ComboOption onclick="v26PickSettingsCountry('${c.code}')">${v25Flag(c.code)} ${esc(c.nameAr)} — ${esc(c.nameEn)}</button>`).join('')}else{const c=window.__v26SettingsCountries.find(x=>x.code===window.__v26SettingsCountry);const cities=(c?.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).filter(x=>`${x.ar} ${x.en}`.toLowerCase().includes(query));box.innerHTML=cities.map(x=>`<button type=button class=v25ComboOption onclick='v26PickSettingsCity(${JSON.stringify(x.en)},${JSON.stringify(x.ar)})'>📍 ${esc(x.ar)} — ${esc(x.en)}</button>`).join('')||'<div class=empty>لا توجد نتائج.</div>'}};
v26PickSettingsCountry=async function(code){window.__v26SettingsCountry=code;window.__v26SettingsCity='';let c=window.__v26SettingsCountries.find(x=>x.code===code);$('#sCountry').value=c?.nameAr||'';$('#sCountry').dataset.code=code;$('#sCity').value='جاري تحميل المدن...';$('#sCity').placeholder='جاري تحميل المدن...';$('#sCity').disabled=true;$('#sCity').dataset.en='';$('#sCity').dataset.ar='';$('#sCountryMenu')?.classList.remove('open');try{c=await v26LoadCountryCities(code,window.__v26SettingsCountries);window.__v26SettingsCountries[window.__v26SettingsCountries.findIndex(x=>x.code===code)]=c;$('#sCity').value='';$('#sCity').placeholder='اختر المدينة';$('#sCity').disabled=false}catch(e){$('#sCity').value='';$('#sCity').placeholder='تعذر تحميل المدن';$('#sCity').disabled=true;toast('تعذر تحميل المدن. حاول اختيار الدولة مرة أخرى')}};
v26PickSettingsCity=function(en,ar){window.__v26SettingsCity=en;$('#sCity').value=ar;$('#sCity').dataset.en=en;$('#sCity').dataset.ar=ar;$('#sCityMenu')?.classList.remove('open')};
const __v26OldSettings=v25SettingsPage;const __v26OldFill=v25FillSettingsCities;v25SettingsPage=async function(){const h=await __v26OldSettings();const countries=(await api('/api/config/countries')).countries||[];window.__v26SettingsCountries=countries;const u=(await api('/api/profile')).user;window.__v26SettingsCountry=u.country||'';window.__v26SettingsCity=u.city||'';if(u.country){try{const fresh=await v26LoadCountryCities(u.country,window.__v26SettingsCountries);window.__v26SettingsCountries[window.__v26SettingsCountries.findIndex(x=>x.code===u.country)]=fresh}catch{}}return h};
v25SaveLocation=async function(){try{if(!window.__v26SettingsCountry||!window.__v26SettingsCity)return toast('اختر الدولة والمدينة من القوائم');const d=await api('/api/profile/location',{method:'POST',body:JSON.stringify({country:window.__v26SettingsCountry,city:window.__v26SettingsCity,currentPassword:$('#sLocationPass').value})});state.user=d.user;toast('تم تحديث الدولة والمدينة');render()}catch(e){toast(e.message)}};
v26RequestEmailOtp=async function(){try{const d=await api('/api/profile/email/request',{method:'POST',body:JSON.stringify({email:$('#sEmail').value,currentPassword:$('#sEmailPass').value})});$('#v26EmailOtpWrap').innerHTML=`<div class=field><label>OTP</label><input id=v26EmailOtp class=input inputmode=numeric maxlength=6></div><button class=btn onclick="v26VerifyEmailOtp()">تأكيد البريد</button>${d.devOtp?`<div class=notice>وضع التطوير: OTP = <b>${esc(d.devOtp)}</b></div>`:''}`;toast(d.message)}catch(e){toast(e.message)}};
v26VerifyEmailOtp=async function(){try{const d=await api('/api/profile/email/verify',{method:'POST',body:JSON.stringify({otp:$('#v26EmailOtp').value})});state.user=d.user;toast('تم تحديث البريد الإلكتروني');render()}catch(e){toast(e.message)}};
v26LogoutAll=async function(){const pass=prompt('أدخل كلمة مرور الحساب الحالية');if(pass===null)return;try{await api('/api/profile/logout-all',{method:'POST',body:JSON.stringify({currentPassword:pass})});sessionStorage.clear();localStorage.removeItem('taskoToken');localStorage.removeItem('taskoPortal');const role=state.user?.role||state.portal;location.href=role==='owner'?'/login/owner':role==='admin'||role==='owner_admin'?'/login/admin':role==='advertiser'?'/login/advertiser':'/login/user'}catch(e){toast(e.message)}};

// Role-aware logout and clean internal footer.
logout=async function(){try{if(state.token)await api('/api/logout',{method:'POST'})}catch{}const role=state.user?.role||state.portal||'user';sessionStorage.clear();localStorage.removeItem('taskoToken');localStorage.setItem('taskoPortal',role);location.href=role==='owner'?'/login/owner':role==='admin'||role==='owner_admin'?'/login/admin':role==='advertiser'?'/login/advertiser':'/login/user'};
const __v26Layout=v18Layout;v18Layout=function(content){const admin=isAdmin()&&!state.preview;const items=admin?v17AdminNav():state.portal==='advertiser'?[['dashboard','⌂ لوحة المعلن'],['campaigns','📊 حملاتي'],['account','◉ معلومات الحساب'],['settings','⚙ الإعدادات']]:[['dashboard','⌂ الرئيسية'],['tasks','✓ المهام'],['packages','◇ الباقات'],['rewards','🎁 متجر المكافآت'],['wallet','💳 المحفظة'],['referrals','↗ الإحالات'],['notifications','🔔 الإشعارات'],['support','💬 الدعم'],['fairplay','✓ Fair Play'],['activity','⌁ نشاطي'],['profile','◉ الملف الشخصي'],['settings','⚙ الإعدادات']];const ini=(state.user?.name||state.user?.company||'T')[0].toUpperCase();root.innerHTML=`<div class="app ${state.user?.package==='Premium'?'premiumTheme':''}"><header class="top v26Top"><div class="brandGroupV26"><button class="mobileMenu stableMenu" type="button" aria-label="فتح القائمة" onclick="toggleTaskoMenu()">☰</button><a class=brand href="${admin?'/admin':state.portal==='advertiser'?'/advertiser':'/dashboard'}">Task<span>o</span></a></div><div class=topUser><button class="avatar avatarBtn" onclick="go(state.portal==='advertiser'?'account':'profile')">${esc(ini)}</button><button class="accountHeaderBtn" onclick="go(state.portal==='advertiser'?'account':'profile')">${esc(state.user?.name||state.user?.company||'')}</button><button class="btn ghost" onclick="logout()">خروج</button></div></header><div class="shell v25Shell ${state.mobileMenuOpen?'open':''}"><aside><div style="padding:4px 10px 18px"><small>${admin?'CONTROL CENTER':state.portal==='advertiser'?'ADVERTISER PORTAL':'MEMBER AREA'}</small><b style="display:block;font-size:17px">${esc(state.user?.name||state.user?.company||'')}</b></div>${nav(items)}</aside><main class=main>${content}<footer class="v21PublicFooter v26InternalFooter">${v25SocialLinks()}</footer></main></div></div>`;afterLayout();if(admin)v17ActionCenter();else document.getElementById('actionCenter')?.remove();};

// Prevent the old misleading eligibility text from resurfacing.
const __v26OldTaskCard=v25TaskCard;v25TaskCard=function(t){return __v26OldTaskCard(t)};

// Admin task/campaign discovery: search + type/owner/status filters, without clutter.
const __v26AdminTasks=loadAdminTasks;
loadAdminTasks=async function(){const e=$('#taskAdminBox');if(!e)return;try{const d=await api('/api/admin/tasks');const types=[...new Set((d.tasks||[]).map(t=>t.type||'custom'))];e.innerHTML=`<div class="adminFilterBar"><input id=v26TaskQ class=input placeholder="ابحث عن مهمة..." oninput="v26RenderAdminTasks()"><select id=v26TaskType class=input onchange="v26RenderAdminTasks()"><option value="">كل أنواع المهام</option>${types.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id=v26TaskAdditional class=input onchange="v26RenderAdminTasks()"><option value="">كل المهام</option><option value="true">المهام الإضافية فقط</option></select><select id=v27TaskOwner class=input onchange="v26RenderAdminTasks()"><option value="">كل المنشئين</option>${[...new Set((d.tasks||[]).map(t=>t.ownerId||t.createdBy).filter(Boolean))].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div><div id=v26TaskRows>${v26TaskRows(d.tasks||[],'')}</div>`;window.__v26AdminTasks=d.tasks||[]}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المهام.</div>'}};
v26TaskRows=function(rows){return rows.map(t=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(t.title)}</h3><small class=muted>${esc(t.category||'عام')} · ${esc(t.type||'custom')} · ${t.startsAt?date(t.startsAt):'بدون بداية'} → ${t.endsAt?date(t.endsAt):'بدون نهاية'}</small></div><span class="pill ${t.active?'green':'red'}">${t.active?'نشطة':'متوقفة'}</span></div><div class=taskMeta><span class=reward>${fmt(t.points)} Points</span><span class=pill>+${fmt(t.xp)} XP</span><span class=pill>${t.isAdditional?'مهمة إضافية':'أساسية'}</span></div><div class=row style="margin-top:10px"><button class="btn ghost" onclick='editTask(${JSON.stringify(t).replace(/'/g,"&#39;")})'>تعديل</button><button class="btn secondary" onclick="toggleTask('${esc(t.id)}')">${t.active?'إيقاف':'تفعيل'}</button></div></div>`).join('')||'<div class=card empty>لا توجد نتائج.</div>'};
v26RenderAdminTasks=function(){const q=String($('#v26TaskQ')?.value||'').toLowerCase(),type=$('#v26TaskType')?.value||'',add=$('#v26TaskAdditional')?.value||'',owner=$('#v27TaskOwner')?.value||'';let rows=window.__v26AdminTasks||[];rows=rows.filter(t=>(!q||JSON.stringify(t).toLowerCase().includes(q))&&(!type||String(t.type||'')===type)&&(!add||String(!!t.isAdditional)===add)&&(!owner||String(t.ownerId||t.createdBy||'')===owner));$('#v26TaskRows').innerHTML=v26TaskRows(rows)};

const __v26LoadCampaigns=loadCampaigns;
loadCampaigns=async function(){const e=$('#campBox');if(!e)return;try{const d=await api('/api/admin/campaigns'),cs=d.campaigns||[];window.__v26AdminCampaigns=cs;e.innerHTML=`<div class="adminFilterBar"><input id=v26CampQ class=input placeholder="ابحث باسم الحملة أو المعلن..." oninput="v26RenderAdminCampaigns()"><select id=v26CampStatus class=input onchange="v26RenderAdminCampaigns()"><option value="">كل الحالات</option>${[...new Set(cs.map(c=>c.status))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id=v26CampType class=input onchange="v26RenderAdminCampaigns()"><option value="">كل أنواع المهام</option>${[...new Set(cs.map(c=>c.taskType||c.contentType||'custom'))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id=v26CampRows>${v26CampaignRows(cs)}</div>`}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل الحملات.</div>'}};
v26CampaignRows=function(cs){return cs.map(c=>`<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId)} · ${esc(c.advertiser?.company||'غير مسند')} · ${esc(c.taskType||'custom')}</small></div><span class=pill>${esc(c.status)}</span></div><div class=grid4 style="margin-top:12px"><div class=reportStat><small>Budget</small><strong>${fmt(c.budget)} JOD</strong></div><div class=reportStat><small>Spent</small><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=reportStat><small>Clicks</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(c.results?.conversions)}</strong></div></div><div class=row style="margin-top:12px"><button class="btn secondary" onclick='openCampaignDetails(${JSON.stringify(c).replace(/'/g,"&#39;")})'>تفاصيل وتحليلات</button><button class="btn ghost" onclick='v26EditCampaignAdmin(${JSON.stringify(c).replace(/'/g,"&#39;")})'>تعديل</button>${['pending','draft','needs_changes'].includes(c.status)?`<button class=btn onclick="v18ApproveCampaign('${esc(c.id)}')">اعتماد</button>`:''}</div></div>`).join('')||'<div class=card empty>لا توجد حملات.</div>'};
v26RenderAdminCampaigns=function(){const q=String($('#v26CampQ')?.value||'').toLowerCase(),st=$('#v26CampStatus')?.value||'',ty=$('#v26CampType')?.value||'';const rows=(window.__v26AdminCampaigns||[]).filter(c=>(!q||`${c.name} ${c.advertiser?.company||''} ${c.referenceId}`.toLowerCase().includes(q))&&(!st||c.status===st)&&(!ty||(c.taskType||c.contentType||'custom')===ty));$('#v26CampRows').innerHTML=v26CampaignRows(rows)};
v26EditCampaignAdmin=function(c){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>تعديل الحملة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2>${[['name','اسم الحملة'],['description','الوصف'],['budget','الميزانية'],['startAt','البداية'],['endAt','النهاية'],['taskType','نوع المهمة'],['objective','الهدف']].map(([k,l])=>`<div class=field><label>${l}</label><input id="ce_${k}" class=input value="${esc(k==='budget'?c[k]||0:k==='startAt'?String(c[k]||'').slice(0,16):c[k]||'')}"></div>`).join('')}</div><button class=btn onclick="v26SaveCampaignAdmin('${esc(c.id)}')">حفظ التعديل</button></div>`;document.body.appendChild(m)};
v26SaveCampaignAdmin=async function(id){const b={id};['name','description','budget','startAt','endAt','taskType','objective'].forEach(k=>{const x=$('#ce_'+k);if(x)b[k]=k==='budget'?Number(x.value):k==='startAt'||k==='endAt'?new Date(x.value).toISOString():x.value});try{await api('/api/admin/campaigns/update',{method:'POST',body:JSON.stringify(b)});document.querySelector('.modalBack')?.remove();toast('تم تعديل الحملة');render()}catch(e){toast(e.message)}};

// Package management: custom packages can be deleted if they are not referenced by campaigns.
const __v26LoadPackagesAdmin=loadPackagesAdmin;
loadPackagesAdmin=async function(){const d=await api('/api/admin/packages');const rows=Object.values(d.packages||{}).sort((a,b)=>Number(b.priority||1)-Number(a.priority||1));$('#pkgAdmin').innerHTML=rows.map(p=>`<div class="packageAdmin"><div class=space><div><h2>${esc(p.name||p.key)}</h2><small class=muted>${esc(p.key)} · Priority ${Number(p.priority||1)}/5</small></div><span class="pill ${p.active?'green':'red'}">${p.active?'Active':'Inactive'}</span></div><div class=grid4 style="margin-top:12px"><div class=detailItem><small>Price</small><b>${fmt(p.price)} ${esc(p.currency||'JOD')}</b></div><div class=detailItem><small>Daily tasks</small><b>${p.dailyTasks||0}</b></div><div class=detailItem><small>Min level</small><b>${esc(levelLabel({levelMinId:p.minLevelId}))}</b></div><div class=detailItem><small>Priority</small><b>${Number(p.priority||1)} / 5</b></div></div><div class=row style="margin-top:12px"><button class=btn secondary onclick='v18EditPackage(${JSON.stringify(p).replace(/'/g,"&#039;")})'>تعديل</button><button class="btn danger" onclick="v26DeletePackage('${esc(p.key)}')">حذف</button><button class="btn ghost" onclick="v18PreviewPackage('${esc(p.key)}')">Preview</button></div></div>`).join('')||'<div class=card empty>لا توجد باقات.</div>'};
v26DeletePackage=async function(key){if(['Free','Plus','Premium'].includes(key))return toast('الباقات الأساسية لا تُحذف؛ يمكن تعديلها أو تعطيلها.');if(!confirm('حذف هذه الباقة؟'))return;const pin=prompt('رمز التأكيد الأمني');if(pin===null)return;try{await api('/api/admin/packages/delete',{method:'POST',body:JSON.stringify({key,confirm:pin})});toast('تم حذف الباقة');loadPackagesAdmin()}catch(e){toast(e.message)}};

// Hide weekly/monthly limits and per-task limit from user package cards, keep daily limit only.

// Load city lists only after a country is chosen. Country -> city is a strict dependency.
async function v26LoadCountryCities(code,store){
  // The selected country is the source of truth. City/province options are bundled
  // with the app so the selector cannot break because an external city service is down.
  let fresh=store?.find?.(x=>x.code===code)||null;
  if(!fresh || !Array.isArray(fresh.cities) || !fresh.cities.length){
    const d=await api('/api/config/countries?country='+encodeURIComponent(code));
    fresh=d.countries?.[0];
  }
  if(!fresh)throw new Error('لم يتم العثور على بيانات المدن');
  fresh={...fresh,cities:Array.isArray(fresh.cities)?fresh.cities:[]};
  if(store){const idx=store.findIndex(x=>x.code===code);if(idx>=0)store[idx]=fresh;else store.push(fresh);}
  return fresh;
}
const __v26RealSelectCountry=v25SelectCountry;
v25SelectCountry=async function(code){
  v25RegCountry=code; v25RegCity=null;
  const c=v25RegCountries.find(x=>x.code===code);
  if(c){$('#country').value=`${c.nameAr} — ${c.nameEn}`;$('#country').dataset.code=code;}
  $('#city').value='جاري تحميل المدن...'; $('#city').placeholder='جاري تحميل المدن...'; $('#city').disabled=true; $('#city').dataset.en=''; $('#city').dataset.ar='';
  $('#countryMenu')?.classList.remove('open'); $('#cityMenu')?.classList.remove('open');
  try{
    const fresh=await v26LoadCountryCities(code,v25RegCountries);
    const cities=(fresh.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).filter(x=>x&&x.en);
    if(!cities.length)throw new Error('لا توجد مدن/محافظات متاحة');
    $('#city').value=''; $('#city').placeholder='اختر المدينة / المحافظة'; $('#city').disabled=false;
    v25RenderComboOptions('city','');
  }catch(e){
    $('#city').value=''; $('#city').placeholder='تعذر تحميل المدن'; $('#city').disabled=true;
    toast('تعذر تحميل المدن. حاول اختيار الدولة مرة أخرى');
  }
};
const __v26OldAuthMode=v25SetAuthMode;
v25SetAuthMode=async function(mode){const r=await __v26OldAuthMode(mode);if(mode==='signup'){if($('#city')){$('#city').disabled=true;$('#city').placeholder='اختر الدولة أولاً';}}return r};
v21SetAuthMode=v25SetAuthMode;

// Settings uses the exact same country -> city source and dependency.
v26PickSettingsCountry=async function(code){
  window.__v26SettingsCountry=code; window.__v26SettingsCity='';
  const c=window.__v26SettingsCountries.find(x=>x.code===code);
  $('#sCountry').value=c?.nameAr||''; $('#sCountry').dataset.code=code;
  $('#sCity').value='جاري تحميل المدن...'; $('#sCity').disabled=true; $('#sCity').placeholder='جاري تحميل المدن...';
  $('#sCountryMenu')?.classList.remove('open'); $('#sCityMenu')?.classList.remove('open');
  try{
    const fresh=await v26LoadCountryCities(code,window.__v26SettingsCountries);
    const cities=(fresh.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).filter(x=>x&&x.en);
    if(!cities.length)throw new Error('لا توجد مدن متاحة');
    $('#sCity').value=''; $('#sCity').placeholder='اختر المدينة'; $('#sCity').disabled=false;
  }catch(e){$('#sCity').value='';$('#sCity').placeholder='تعذر تحميل المدن';$('#sCity').disabled=true;toast('تعذر تحميل المدن. حاول اختيار الدولة مرة أخرى')}
};
const __v26SettingsPageFinal=v25SettingsPage;
v25SettingsPage=async function(){const html=await __v26SettingsPageFinal();try{const u=(await api('/api/profile')).user;if(u.country){const fresh=await v26LoadCountryCities(u.country,window.__v26SettingsCountries);window.__v26SettingsCountry=u.country;window.__v26SettingsCity=u.city||'';setTimeout(()=>{if($('#sCountry'))$('#sCountry').value=fresh.nameAr||fresh.nameEn||'';const city=(fresh.cities||[]).map(x=>typeof x==='string'?{en:x,ar:x}:x).find(x=>x.en===u.city||x.ar===u.city);if(city&&$('#sCity')){$('#sCity').value=city.ar||city.en;$('#sCity').disabled=false;$('#sCity').placeholder='اختر المدينة'}},0)}}catch{}return html};

// Public FAQ reads the same admin-managed FAQ data; no duplicate static FAQ.
async function v26RenderPublicFaq(){
  let faqs=[]; try{faqs=(await api('/api/faq')).faqs||[]}catch{}
  const rows=faqs.map(f=>`<details class=faqItem data-faq="${esc((f.question+' '+f.answer).toLowerCase())}"><summary>${esc(f.question)}<span>＋</span></summary><p>${esc(f.answer)}</p>${f.link?`<p><a class="btn ghost" href="${esc(f.link)}" ${/^https?:\/\//i.test(f.link)?'target="_blank" rel="noopener noreferrer"':''}>فتح الرابط</a></p>`:''}</details>`).join('');
  root.innerHTML=`<div class=publicShell>${v21PublicHeader()}<main class="publicDoc v21Doc faqDoc"><span class="pill blue">FAQ</span><h1>الأسئلة الشائعة</h1><p class=lead>إجابات الأسئلة التي يعتمدها فريق Tasko.</p><div class=faqSearch><span>⌕</span><input id=v21FaqSearch class=input placeholder="ابحث في الأسئلة..." oninput="v21FilterFaq()"></div><div id=v21FaqList class=faqList>${rows||'<div class=card empty>لا توجد أسئلة منشورة حالياً.</div>'}</div><div id=v21FaqEmpty class="card empty" style="display:none">لا توجد نتائج مطابقة.</div></main>${v21PublicFooter()}</div>`;
}
const __v26RenderBeforeFaq=render;
render=async function(){const p=location.pathname.replace(/\/$/,'')||'/';if(!state.token&&p==='/faq')return v26RenderPublicFaq();return __v26RenderBeforeFaq();};

// Campaign analytics: richer, decision-useful view instead of decorative bars.
v18CampaignAnalytics=function(c){const b=Number(c.budget||0),s=Number(c.results?.spent||0),r=Math.max(0,b-s),clicks=Number(c.results?.clicks||0),conv=Number(c.results?.conversions||0),rate=clicks?Math.round(conv/clicks*10000)/100:0,target=Number(c.requiredPeople||c.allocation?.requiredPeople||0),pct=target?Math.min(100,Math.round(conv/target*100)):0;const pk=c.packageConfigs||{};const schedules=Array.isArray(c.customSchedules)?c.customSchedules:[];const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class="modal campaignAnalyticsV26" style="max-width:1050px;max-height:92vh;overflow:auto"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId||c.id)} · ${esc(c.status)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div>${c.adminModifiedNotice?'<div class="notice">تم تعديل بعض بيانات الحملة من قبل أدمن.</div>':''}<div class=grid4 section><div class=reportStat><small>الميزانية</small><strong>${fmt(b)} JOD</strong></div><div class=reportStat><small>المصروف</small><strong>${fmt(s)} JOD</strong></div><div class=reportStat><small>المتبقي</small><strong>${fmt(r)} JOD</strong></div><div class=reportStat><small>معدل التحويل</small><strong>${rate}%</strong></div></div><div class="grid2 section"><div class=card><h3>الجدول الزمني</h3><div class=detailList><div class=detailItem><small>البداية</small><b>${date(c.startAt||c.startAtJordan)}</b></div><div class=detailItem><small>النهاية</small><b>${date(c.endAt||c.endAtJordan)}</b></div><div class=detailItem><small>النوع</small><b>${esc(c.taskType||c.contentType||'—')}</b></div><div class=detailItem><small>التحقق</small><b>${esc(c.verification||c.allocation?.verification||'—')}</b></div></div>${schedules.length?`<h4>مواعيد Custom</h4>${schedules.map((x,i)=>`<div class=detailItem><small>الموعد ${i+1}</small><b>${date(x.startAt)} → ${date(x.endAt)}</b></div>`).join('')}`:''}</div><div class=card><h3>الإنجاز</h3><div class=progress><span style="width:${pct}%"></span></div><p class=muted>${fmt(conv)} مكتمل${target?' من '+fmt(target):''}</p><div class=grid2><div class=reportStat><small>Clicks</small><strong>${fmt(clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(conv)}</strong></div></div></div></div><div class="card section"><h3>أداء الباقات</h3><div class=tableWrap><table class=table><tr><th>الباقة</th><th>مفعلة</th><th>Points</th><th>XP</th><th>Cash</th><th>حد المستخدم</th></tr>${['Free','Plus','Premium'].map(k=>{const x=pk[k]||{};return `<tr><td>${k}</td><td>${x.eligible?'نعم':'لا'}</td><td>${fmt(x.points||0)}</td><td>${fmt(x.xp||0)}</td><td>${fmt(x.cashReward||0)}</td><td>${fmt(x.maxPerUser||1)}</td></tr>`}).join('')}</table></div></div><div class="card section"><h3>التكلفة والأداء</h3><div class=grid4><div class=detailItem><small>تكلفة المشارك</small><b>${fmt(c.rewardPerPerson||c.allocation?.rewardPerPerson||0)} Points</b></div><div class=detailItem><small>عدد المشاركين المستهدف</small><b>${fmt(target)}</b></div><div class=detailItem><small>الإنفاق لكل تحويل</small><b>${conv?fmt(s/conv):'—'} JOD</b></div><div class=detailItem><small>نسبة الميزانية المستخدمة</small><b>${b?Math.round(s/b*100):0}%</b></div></div></div>${v25CampaignCode(c)}</div>`;document.body.appendChild(m)};

