// User package UI: daily task limit only; weekly/monthly/per-task limits are never user-facing.
v21PackagesPage=async function(){
  const d=await api('/api/packages');
  const ps=Object.values(d.settings||{}).filter(p=>p.visible!==false&&p.active!==false);
  return `<div class="space"><div><h1>الباقات</h1><p class="subtitle">الباقات هي مزايا وصول وميزات إضافية للمنصة، وليست استثماراً ولا تضمن أرباحاً أو دخلاً فعلياً.</p></div><span class="pill">${esc(d.current||state.user?.package||'Free')}</span></div><div class="packageGridV21">${ps.map(p=>{const current=d.current===p.key;const features=Array.isArray(p.features)?p.features:[];return `<article class="packageCardV21 ${current?'current':''}"><div class="space"><span class="pill ${current?'green':'blue'}">${current?'الحالية':'متاحة'}</span><span class="pill">${Number(p.priority||1)}/5 أولوية</span></div><h2>${esc(p.name||p.key)}</h2><div class="packagePriceV21">${fmt(p.price||0)} <small>${esc(p.currency||'JOD')}</small></div><div class="packageDuration">${p.durationDays?`${fmt(p.durationDays)} يوم`:'بدون مدة محددة'}</div><ul>${features.slice(0,8).map(f=>`<li>${esc(f)}</li>`).join('')||'<li>مزايا وصول وميزات حسب الباقة</li>'}</ul><div class="detailList"><div class="detailItem"><small>المهام اليومية</small><b>${fmt(p.dailyTasks||0)}</b></div></div><button class="btn ${current?'ghost':'secondary'}" onclick='v21OpenPackageDetails(${JSON.stringify(p).replace(/'/g,"&#39;")},${current})'>${current?'عرض تفاصيل باقتك':'عرض تفاصيل الباقة'}</button></article>`}).join('')}</div>`;
};
v21OpenPackageDetails=function(p,current){
  const m=document.createElement('div');m.className='modalBack';
  const features=Array.isArray(p.features)?p.features:[];
  m.innerHTML=`<div class="modal packageDetailModalV21"><div class="space"><div><span class="pill blue">${esc(p.name||p.key)}</span><h2>${esc(p.name||p.key)}</h2></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class="packageDetailHeroV21"><strong>${fmt(p.price||0)} ${esc(p.currency||'JOD')}</strong><span>${p.durationDays?`${fmt(p.durationDays)} يوم`:'بدون مدة محددة'}</span></div><h3>المزايا</h3><ul class="v21FeatureList">${features.map(f=>`<li>✓ ${esc(f)}</li>`).join('')||'<li>مزايا الوصول الأساسية حسب الباقة.</li>'}</ul><div class="detailList"><div class="detailItem"><small>الأولوية</small><b>${fmt(p.priority||1)} / 5</b></div><div class="detailItem"><small>المهام اليومية</small><b>${fmt(p.dailyTasks||0)}</b></div><div class="detailItem"><small>الحد الأدنى للسحب</small><b>${fmt(p.withdrawalMin||0)} JOD</b></div></div><div class="notice" style="margin-top:16px">هذه الباقة توفر مزايا وميزات وصول فقط، وليست وعداً بربح فعلي أو دخلاً مضموناً. ${current?'هذه باقتك الحالية.':'بعد طلب الاشتراك تنتقل العملية إلى الدفع، ثم تُفعّل الباقة عند نجاح الدفع.'}</div>${current?'<button class="btn ghost" disabled style="width:100%;margin-top:12px">الباقة الحالية</button>':'<button class="btn" style="width:100%;margin-top:12px" onclick="v21RequestPackage(&quot;'+esc(p.key)+'&quot;)">طلب الاشتراك</button>'}</div>`;
  document.body.appendChild(m);
};

